-- =====================================================================================================
-- BASELINE: production-derived schema snapshot of project jncvvsvckxhqgqvkppmj (AGENTFLOW CRM)
-- =====================================================================================================
-- Generated 2026-08-09 from `supabase db dump` (schema-only) AFTER the approved emergency ACL hotfix
-- on wipe_organization_operational_data, with PR #352 migrations 0-of-3 applied. This file replaces
-- the unreplayable pre-baseline migration history (see supabase/migrations_archive/pre_baseline/).
--
-- STRUCTURE:  guard | pg_dump body | Appendix A auth.users triggers | Appendix B storage buckets |
--             Appendix C storage.objects policies | Appendix D generated ACL sync
-- Appendices carry objects `supabase db dump` excludes (auth/storage schemas) or restores
-- incorrectly against a fresh stack's pre-existing default privileges (ACLs — Phase 0 finding).
-- ACL appendices are GENERATED by scripts/generate_acl_sync.sql — never hand-edit; regenerate.
-- Verification authority: scripts/fingerprint.sql + scripts/fingerprint_rollup.sql, run identically
-- against production (read-only) and the local replay. The current category inventory and result
-- live in WORK_LOG.md / the repair PR; this header intentionally embeds no counts.
--
-- GUARD: the first executable statement aborts on any initialized (or partially initialized)
-- AgentFlow database — every core-table sentinel, the private-schema sentinels, the
-- profile-authorization function, and any pre-existing applied migration-history rows. Production
-- never executes this file; its version is reconciled via `supabase migration repair` metadata only
-- (see supabase/rollback/20260806_baseline_history_reconciliation_runbook.md).
-- =====================================================================================================
DO $guard$
DECLARE
  v_sentinel text;
  v_history_rows bigint;
BEGIN
  -- Core AgentFlow tables: any one present means this is not a fresh database.
  SELECT t INTO v_sentinel
  FROM unnest(ARRAY[
    'public.organizations', 'public.profiles', 'public.leads', 'public.campaigns',
    'public.campaign_leads', 'public.calls', 'public.import_history',
    'public.dialer_sessions', 'public.wins',
    -- private-schema sentinels: detect partial initialization
    'private.twilio_provisioning_config', 'private.recording_retention_cron_secret',
    'private.email_sync_cron_secret', 'private.google_sync_cron_secret'
  ]) AS t
  WHERE to_regclass(t) IS NOT NULL
  LIMIT 1;
  IF v_sentinel IS NOT NULL THEN
    RAISE EXCEPTION 'baseline must never run on an initialized AgentFlow database (sentinel found: %)', v_sentinel;
  END IF;
  -- profile-authorization sentinel (function-level partial initialization)
  IF to_regprocedure('public.enforce_profile_field_authorization()') IS NOT NULL THEN
    RAISE EXCEPTION 'baseline must never run on an initialized AgentFlow database (sentinel found: enforce_profile_field_authorization())';
  END IF;
  -- applied migration-history rows (safely detectable only when the CLI history table exists)
  IF to_regclass('supabase_migrations.schema_migrations') IS NOT NULL THEN
    EXECUTE 'SELECT count(*) FROM supabase_migrations.schema_migrations' INTO v_history_rows;
    IF v_history_rows > 0 THEN
      RAISE EXCEPTION 'baseline must never run on a database with % applied migration-history row(s)', v_history_rows;
    END IF;
  END IF;
END
$guard$;




