CREATE OR REPLACE FUNCTION "private"."close_stale_dialer_sessions"("p_organization_id" "uuid", "p_agent_id" "uuid", "p_stale_minutes" integer DEFAULT 3) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_closed integer;
BEGIN
  IF p_organization_id IS NULL OR p_agent_id IS NULL THEN
    RAISE EXCEPTION 'organization_id and agent_id are required';
  END IF;

  IF p_stale_minutes IS NULL OR p_stale_minutes < 1 THEN
    RAISE EXCEPTION 'stale_minutes must be >= 1';
  END IF;

  UPDATE public.dialer_sessions
  SET
    status = 'abandoned',
    ended_at = last_heartbeat_at,
    updated_at = now()
  WHERE organization_id = p_organization_id
    AND agent_id = p_agent_id
    AND status = 'active'
    AND last_heartbeat_at < now() - (p_stale_minutes || ' minutes')::interval;

  GET DIAGNOSTICS v_closed = ROW_COUNT;
  RETURN v_closed;
END;
$$;


ALTER FUNCTION "private"."close_stale_dialer_sessions"("p_organization_id" "uuid", "p_agent_id" "uuid", "p_stale_minutes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."workflow_dispatch_event"("p_org_id" "uuid", "p_trigger_type" "text", "p_trigger_key" "text", "p_contact_id" "uuid", "p_contact_type" "text" DEFAULT 'lead'::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_config private.workflow_engine_config%ROWTYPE;
  v_url text;
  v_payload jsonb;
BEGIN
  SELECT * INTO v_config FROM private.workflow_engine_config WHERE id = 1;
  
  IF v_config.supabase_url = '' OR v_config.workflow_internal_secret = '' THEN
    RETURN; -- Engine not configured yet, silently skip
  END IF;

  v_url := v_config.supabase_url || '/functions/v1/workflow-trigger-evaluator';
  
  v_payload := jsonb_build_object(
    'organization_id', p_org_id,
    'trigger_type', p_trigger_type,
    'trigger_key', p_trigger_key,
    'contact_id', p_contact_id,
    'contact_type', p_contact_type,
    'metadata', p_metadata
  );

  PERFORM net.http_post(
    url := v_url,
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'X-Workflow-Secret', v_config.workflow_internal_secret
    ),
    body := v_payload
  );
END;
$$;


ALTER FUNCTION "private"."workflow_dispatch_event"("p_org_id" "uuid", "p_trigger_type" "text", "p_trigger_key" "text", "p_contact_id" "uuid", "p_contact_type" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "profile_authz"."can_update_profile"("p_target_profile_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  actor_id uuid := auth.uid();
  a_role   text;
  a_org    uuid;
  a_super  boolean;
  t_org    uuid;
BEGIN
  IF actor_id IS NULL OR p_target_profile_id IS NULL THEN
    RETURN false;
  END IF;

  SELECT p.role, p.organization_id, COALESCE(p.is_super_admin, false)
    INTO a_role, a_org, a_super
  FROM public.profiles p
  WHERE p.id = actor_id;
  IF NOT FOUND THEN
    RETURN false;                       -- authenticated but no profile => no authority
  END IF;

  SELECT p.organization_id INTO t_org
  FROM public.profiles p
  WHERE p.id = p_target_profile_id;
  IF NOT FOUND THEN
    RETURN false;                       -- unknown target
  END IF;

  a_super := COALESCE(a_super, false);

  IF p_target_profile_id = actor_id THEN
    RETURN true;
  END IF;

  IF a_org IS NULL OR t_org IS NULL THEN
    RETURN false;
  END IF;
  IF COALESCE(a_org = t_org, false) IS NOT TRUE THEN
    RETURN false;
  END IF;

  IF a_super IS TRUE THEN
    RETURN true;
  END IF;

  IF a_role IN ('Admin', 'Super Admin') THEN
    RETURN true;
  END IF;

  IF a_role = 'Team Leader' THEN
    RETURN COALESCE(public.is_ancestor_of(actor_id, p_target_profile_id), false);
  END IF;

  RETURN false;                         -- Agent and any unrecognised role: self only
END;
$$;


ALTER FUNCTION "profile_authz"."can_update_profile"("p_target_profile_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "profile_authz"."can_update_profile"("p_target_profile_id" "uuid") IS 'P0 Layer 2: database-authoritative row authorization for UPDATE on public.profiles. Resolves actor and target from public.profiles; never reads JWT role/org/is_super_admin/platform_role or user_metadata. Returns a scalar boolean only.';



CREATE OR REPLACE FUNCTION "public"."_contacts_filtered_clients"("p_filters" "jsonb") RETURNS TABLE("id" "uuid", "ord" bigint)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  WITH base AS (
    SELECT
      c.id, c.created_at, c.first_name, c.last_name, c.phone, c.email, c.state,
      c.policy_type, c.carrier, c.premium, c.face_amount, c.issue_date,
      CASE WHEN pa.id IS NULL THEN NULL
           ELSE lower(btrim(coalesce(pa.first_name, '') || ' ' || coalesce(pa.last_name, ''))) END AS agent_sort
    FROM public.clients c
    LEFT JOIN public.profiles pa ON pa.id = c.assigned_agent_id
    WHERE
      (
        p_filters->'assigned_agent_ids' IS NULL
        OR jsonb_typeof(p_filters->'assigned_agent_ids') <> 'array'
        OR c.assigned_agent_id = ANY (ARRAY(SELECT (jsonb_array_elements_text(p_filters->'assigned_agent_ids'))::uuid))
      )
      AND (p_filters->>'state'       IS NULL OR c.state = p_filters->>'state')
      AND (p_filters->>'policy_type' IS NULL OR c.policy_type = p_filters->>'policy_type')
      AND (
        p_filters->>'search' IS NULL
        OR c.first_name ILIKE '%' || (p_filters->>'search') || '%'
        OR c.last_name  ILIKE '%' || (p_filters->>'search') || '%'
        OR c.phone      ILIKE '%' || (p_filters->>'search') || '%'
        OR c.email      ILIKE '%' || (p_filters->>'search') || '%'
      )
  ),
  keyed AS (
    SELECT
      b.id, b.created_at,
      (lower(coalesce(p_filters->>'sort_direction', 'desc')) IN ('asc', 'desc')) AS dir_ok,
      (lower(coalesce(p_filters->>'sort_direction', 'desc')) = 'asc')            AS asc_dir,
      CASE lower(coalesce(p_filters->>'sort_column', ''))
        WHEN 'name'           THEN lower(btrim(coalesce(b.last_name, '')) || ' ' || btrim(coalesce(b.first_name, '')))
        WHEN 'phone'          THEN b.phone
        WHEN 'email'          THEN lower(btrim(coalesce(b.email, '')))
        WHEN 'state'          THEN b.state
        WHEN 'policy_type'    THEN b.policy_type
        WHEN 'carrier'        THEN lower(btrim(coalesce(b.carrier, '')))
        WHEN 'issue_date'     THEN b.issue_date
        WHEN 'assigned_agent' THEN b.agent_sort
        ELSE NULL
      END AS text_key,
      CASE lower(coalesce(p_filters->>'sort_column', ''))
        WHEN 'premium'     THEN b.premium
        WHEN 'face_amount' THEN b.face_amount
        ELSE NULL
      END AS num_key,
      CASE WHEN lower(coalesce(p_filters->>'sort_column', '')) = 'created_at' THEN b.created_at ELSE NULL END AS ts_key
    FROM base b
  )
  SELECT
    k.id,
    row_number() OVER (
      ORDER BY
        CASE WHEN k.dir_ok AND k.asc_dir      THEN k.text_key END ASC  NULLS LAST,
        CASE WHEN k.dir_ok AND NOT k.asc_dir  THEN k.text_key END DESC NULLS LAST,
        CASE WHEN k.dir_ok AND k.asc_dir      THEN k.num_key  END ASC  NULLS LAST,
        CASE WHEN k.dir_ok AND NOT k.asc_dir  THEN k.num_key  END DESC NULLS LAST,
        CASE WHEN k.dir_ok AND k.asc_dir      THEN k.ts_key   END ASC  NULLS LAST,
        CASE WHEN k.dir_ok AND NOT k.asc_dir  THEN k.ts_key   END DESC NULLS LAST,
        k.created_at DESC, k.id DESC
    ) AS ord
  FROM keyed k;
$$;


ALTER FUNCTION "public"."_contacts_filtered_clients"("p_filters" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_contacts_filtered_leads"("p_filters" "jsonb") RETURNS TABLE("id" "uuid", "ord" bigint)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  WITH base AS (
    SELECT
      l.id,
      l.created_at,
      l.first_name, l.last_name, l.status, l.lead_source, l.state, l.phone, l.email,
      l.date_of_birth, l.best_time_to_call, l.last_contacted_at,
      CASE WHEN pa.id IS NULL THEN NULL
           ELSE lower(btrim(coalesce(pa.first_name, '') || ' ' || coalesce(pa.last_name, ''))) END AS agent_sort,
      (
        SELECT count(DISTINCT c.id)
        FROM public.calls c
        WHERE c.direction = 'outbound'
          AND (
            c.lead_id = l.id
            OR (c.lead_id IS NULL AND c.contact_id = l.id AND (c.contact_type = 'lead' OR c.contact_type IS NULL))
          )
      ) AS attempt_count,
      (
        SELECT NULLIF(btrim(c.disposition_name), '')
        FROM public.calls c
        WHERE (
            c.lead_id = l.id
            OR (c.lead_id IS NULL AND c.contact_id = l.id AND (c.contact_type = 'lead' OR c.contact_type IS NULL))
          )
          AND (c.disposition_id IS NOT NULL OR btrim(coalesce(c.disposition_name, '')) <> '')
        ORDER BY c.created_at DESC NULLS LAST, c.id DESC
        LIMIT 1
      ) AS last_disposition
    FROM public.leads l
    LEFT JOIN public.profiles pa ON pa.id = l.assigned_agent_id
    WHERE
      (
        (coalesce(p_filters->>'scope', 'mine') = 'mine'
          AND l.user_id = auth.uid())
        OR (p_filters->>'scope' = 'team'
          AND (l.user_id = auth.uid() OR public.is_ancestor_of(auth.uid(), l.user_id)))
        OR (p_filters->>'scope' = 'agency'
          AND l.organization_id = public.get_org_id())
        OR (p_filters->>'scope' = 'unassigned'
          AND l.organization_id = public.get_org_id()
          AND l.user_id IS NULL AND l.assigned_agent_id IS NULL
          AND (
            public.has_contacts_permission('contacts.leads.view_all')
            OR l.imported_by_user_id = auth.uid()
          ))
      )
      AND (
        p_filters->'agent_ids' IS NULL
        OR jsonb_typeof(p_filters->'agent_ids') <> 'array'
        OR l.user_id = ANY (ARRAY(SELECT (jsonb_array_elements_text(p_filters->'agent_ids'))::uuid))
      )
      AND (p_filters->>'status' IS NULL OR l.status = p_filters->>'status')
      AND (p_filters->>'source' IS NULL OR l.lead_source = p_filters->>'source')
      AND (p_filters->>'state'  IS NULL OR l.state = p_filters->>'state')
      AND (p_filters->>'created_start' IS NULL OR l.created_at >= (p_filters->>'created_start')::timestamptz)
      AND (p_filters->>'created_end'   IS NULL OR l.created_at <= (p_filters->>'created_end')::timestamptz)
      AND (
        p_filters->'timezone_states' IS NULL
        OR jsonb_typeof(p_filters->'timezone_states') <> 'array'
        OR l.state = ANY (ARRAY(SELECT jsonb_array_elements_text(p_filters->'timezone_states')))
      )
      AND (
        p_filters->'callable_states' IS NULL
        OR jsonb_typeof(p_filters->'callable_states') <> 'array'
        OR l.state = ANY (ARRAY(SELECT jsonb_array_elements_text(p_filters->'callable_states')))
      )
      AND (
        p_filters->>'search' IS NULL
        OR l.first_name ILIKE '%' || (p_filters->>'search') || '%'
        OR l.last_name  ILIKE '%' || (p_filters->>'search') || '%'
        OR l.phone      ILIKE '%' || (p_filters->>'search') || '%'
        OR l.email      ILIKE '%' || (p_filters->>'search') || '%'
      )
  ),
  filtered AS (
    SELECT * FROM base b
    WHERE
      (
        p_filters->'attempt_buckets' IS NULL
        OR jsonb_typeof(p_filters->'attempt_buckets') <> 'array'
        OR (
          ('0'   = ANY (ARRAY(SELECT jsonb_array_elements_text(p_filters->'attempt_buckets'))) AND b.attempt_count = 0)
          OR ('1-3' = ANY (ARRAY(SELECT jsonb_array_elements_text(p_filters->'attempt_buckets'))) AND b.attempt_count BETWEEN 1 AND 3)
          OR ('4+'  = ANY (ARRAY(SELECT jsonb_array_elements_text(p_filters->'attempt_buckets'))) AND b.attempt_count >= 4)
        )
      )
      AND (
        p_filters->>'last_disposition' IS NULL
        OR (p_filters->>'last_disposition' = '__none__' AND b.last_disposition IS NULL)
        OR (
          p_filters->>'last_disposition' <> '__none__'
          AND lower(btrim(coalesce(b.last_disposition, ''))) = lower(btrim(p_filters->>'last_disposition'))
        )
      )
  ),
  keyed AS (
    SELECT
      f.id, f.created_at,
      (lower(coalesce(p_filters->>'sort_direction', 'desc')) IN ('asc', 'desc')) AS dir_ok,
      (lower(coalesce(p_filters->>'sort_direction', 'desc')) = 'asc')            AS asc_dir,
      CASE lower(coalesce(p_filters->>'sort_column', ''))
        WHEN 'name'             THEN lower(btrim(coalesce(f.last_name, ''))) || ' ' || lower(btrim(coalesce(f.first_name, '')))
        WHEN 'status'           THEN f.status
        WHEN 'lead_source'      THEN lower(btrim(coalesce(f.lead_source, '')))
        WHEN 'state'            THEN f.state
        WHEN 'phone'            THEN f.phone
        WHEN 'email'            THEN lower(btrim(coalesce(f.email, '')))
        WHEN 'dob'              THEN f.date_of_birth::text
        WHEN 'best_time'        THEN f.best_time_to_call
        WHEN 'last_contacted'   THEN f.last_contacted_at::text
        WHEN 'assigned_agent'   THEN f.agent_sort
        WHEN 'last_disposition' THEN lower(btrim(f.last_disposition))
        ELSE NULL
      END AS text_key,
      CASE WHEN lower(coalesce(p_filters->>'sort_column', '')) = 'attempt_count' THEN f.attempt_count ELSE NULL END AS num_key,
      CASE WHEN lower(coalesce(p_filters->>'sort_column', '')) = 'created_at'     THEN f.created_at     ELSE NULL END AS ts_key
    FROM filtered f
  )
  SELECT
    k.id,
    row_number() OVER (
      ORDER BY
        CASE WHEN k.dir_ok AND k.asc_dir      THEN k.text_key END ASC  NULLS LAST,
        CASE WHEN k.dir_ok AND NOT k.asc_dir  THEN k.text_key END DESC NULLS LAST,
        CASE WHEN k.dir_ok AND k.asc_dir      THEN k.num_key  END ASC  NULLS LAST,
        CASE WHEN k.dir_ok AND NOT k.asc_dir  THEN k.num_key  END DESC NULLS LAST,
        CASE WHEN k.dir_ok AND k.asc_dir      THEN k.ts_key   END ASC  NULLS LAST,
        CASE WHEN k.dir_ok AND NOT k.asc_dir  THEN k.ts_key   END DESC NULLS LAST,
        k.created_at DESC, k.id DESC
    ) AS ord
  FROM keyed k;
$$;


ALTER FUNCTION "public"."_contacts_filtered_leads"("p_filters" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_contacts_filtered_recruits"("p_filters" "jsonb") RETURNS TABLE("id" "uuid", "ord" bigint)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  WITH base AS (
    SELECT
      r.id, r.created_at, r.first_name, r.last_name, r.phone, r.email, r.state, r.status,
      CASE WHEN pa.id IS NULL THEN NULL
           ELSE lower(btrim(coalesce(pa.first_name, '') || ' ' || coalesce(pa.last_name, ''))) END AS agent_sort
    FROM public.recruits r
    LEFT JOIN public.profiles pa ON pa.id = r.assigned_agent_id
    WHERE
      (
        p_filters->'assigned_agent_ids' IS NULL
        OR jsonb_typeof(p_filters->'assigned_agent_ids') <> 'array'
        OR r.assigned_agent_id = ANY (ARRAY(SELECT (jsonb_array_elements_text(p_filters->'assigned_agent_ids'))::uuid))
      )
      AND (p_filters->>'state' IS NULL OR r.state = p_filters->>'state')
      AND (
        p_filters->>'search' IS NULL
        OR r.first_name ILIKE '%' || (p_filters->>'search') || '%'
        OR r.last_name  ILIKE '%' || (p_filters->>'search') || '%'
        OR r.phone      ILIKE '%' || (p_filters->>'search') || '%'
        OR r.email      ILIKE '%' || (p_filters->>'search') || '%'
      )
  ),
  keyed AS (
    SELECT
      b.id, b.created_at,
      (lower(coalesce(p_filters->>'sort_direction', 'desc')) IN ('asc', 'desc')) AS dir_ok,
      (lower(coalesce(p_filters->>'sort_direction', 'desc')) = 'asc')            AS asc_dir,
      CASE lower(coalesce(p_filters->>'sort_column', ''))
        WHEN 'name'           THEN lower(btrim(coalesce(b.last_name, '')) || ' ' || btrim(coalesce(b.first_name, '')))
        WHEN 'phone'          THEN b.phone
        WHEN 'email'          THEN lower(btrim(coalesce(b.email, '')))
        WHEN 'state'          THEN b.state
        WHEN 'status'         THEN b.status
        WHEN 'assigned_agent' THEN b.agent_sort
        ELSE NULL
      END AS text_key,
      CASE WHEN lower(coalesce(p_filters->>'sort_column', '')) = 'created_at' THEN b.created_at ELSE NULL END AS ts_key
    FROM base b
  )
  SELECT
    k.id,
    row_number() OVER (
      ORDER BY
        CASE WHEN k.dir_ok AND k.asc_dir      THEN k.text_key END ASC  NULLS LAST,
        CASE WHEN k.dir_ok AND NOT k.asc_dir  THEN k.text_key END DESC NULLS LAST,
        CASE WHEN k.dir_ok AND k.asc_dir      THEN k.ts_key   END ASC  NULLS LAST,
        CASE WHEN k.dir_ok AND NOT k.asc_dir  THEN k.ts_key   END DESC NULLS LAST,
        k.created_at DESC, k.id DESC
    ) AS ord
  FROM keyed k;
$$;


ALTER FUNCTION "public"."_contacts_filtered_recruits"("p_filters" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_contacts_permission_default"("p_role" "text", "p_key" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT COALESCE(
    (SELECT CASE p_role WHEN 'Agent' THEN d.agent WHEN 'Team Leader' THEN d.team_leader ELSE false END
     FROM (VALUES
       ('contacts.leads.view_assigned',   true,  true),
       ('contacts.leads.view_unassigned', false, true),
       ('contacts.leads.view_all',        false, false),
       ('contacts.leads.create',          true,  true),
       ('contacts.leads.edit',            true,  true),
       ('contacts.leads.delete',          false, false),
       ('contacts.leads.import',          false, true),
       ('contacts.leads.undo_own_import', false, true),
       ('contacts.leads.undo_team_import',false, true),
       ('contacts.leads.assign',          false, true),
       ('contacts.leads.bulk_assign',     false, true),
       ('contacts.leads.bulk_status',     true,  true),
       ('contacts.leads.update_status',   true,  true),
       ('contacts.leads.add_to_campaign', false, true),
       ('contacts.clients.view',          true,  true),
       ('contacts.clients.edit',          true,  true),
       ('contacts.clients.delete',        false, false),
       ('contacts.recruits.view',         true,  true),
       ('contacts.recruits.create',       true,  true),
       ('contacts.recruits.edit',         true,  true),
       ('contacts.recruits.delete',       false, false),
       ('contacts.notes.manage',          true,  true),
       ('contacts.tasks.manage',          true,  true),
       ('contacts.appointments.manage',   true,  true),
       ('contacts.messages.manage',       true,  true)
     ) AS d(key, agent, team_leader)
     WHERE d.key = p_key),
    false
  );
$$;


ALTER FUNCTION "public"."_contacts_permission_default"("p_role" "text", "p_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_import_undo_blockers"("p_import_id" "uuid", "p_org" "uuid", "p_ids" "uuid"[]) RETURNS "text"[]
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  codes text[] := ARRAY[]::text[];
  v_existing int;
BEGIN
  SELECT count(*) INTO v_existing FROM public.leads WHERE id = ANY(p_ids) AND organization_id = p_org;
  IF v_existing < COALESCE(array_length(p_ids, 1), 0) THEN codes := array_append(codes, 'lead_missing'); END IF;

  IF EXISTS (
    SELECT 1 FROM public.calls c
    WHERE c.organization_id = p_org AND (
      c.lead_id = ANY(p_ids)
      OR (c.lead_id IS NULL AND c.contact_id = ANY(p_ids) AND (c.contact_type = 'lead' OR c.contact_type IS NULL))
    )
  ) THEN codes := array_append(codes, 'has_calls'); END IF;

  IF EXISTS (SELECT 1 FROM public.call_logs WHERE lead_id = ANY(p_ids)) THEN
    codes := array_append(codes, 'has_calls');
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.messages m
    WHERE m.lead_id = ANY(p_ids)
       OR (m.contact_id = ANY(p_ids) AND (m.contact_type = 'lead' OR m.contact_type IS NULL))
  ) THEN codes := array_append(codes, 'has_messages'); END IF;

  IF EXISTS (SELECT 1 FROM public.contact_emails WHERE organization_id = p_org AND contact_id = ANY(p_ids)) THEN
    codes := array_append(codes, 'has_emails');
  END IF;

  IF EXISTS (SELECT 1 FROM public.appointments WHERE organization_id = p_org AND contact_id = ANY(p_ids)) THEN
    codes := array_append(codes, 'has_appointments');
  END IF;

  IF EXISTS (SELECT 1 FROM public.tasks WHERE organization_id = p_org AND contact_id = ANY(p_ids)) THEN
    codes := array_append(codes, 'has_tasks');
  END IF;

  IF EXISTS (SELECT 1 FROM public.contact_notes WHERE contact_id = ANY(p_ids)) THEN
    codes := array_append(codes, 'has_notes');
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.contact_activities a
    WHERE a.contact_id = ANY(p_ids)
      AND COALESCE(a.activity_type, '') <> 'import'
      AND COALESCE(a.metadata->>'source', '') <> 'import'
  ) THEN codes := array_append(codes, 'has_activity'); END IF;

  IF EXISTS (
    SELECT 1 FROM public.workflow_executions
    WHERE organization_id = p_org AND contact_id = ANY(p_ids) AND status = 'running'
  ) THEN codes := array_append(codes, 'has_workflow'); END IF;

  IF EXISTS (SELECT 1 FROM public.wins WHERE contact_id = ANY(p_ids)) THEN
    codes := array_append(codes, 'has_win');
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.campaign_leads cl
    WHERE cl.lead_id = ANY(p_ids)
      AND (cl.import_history_id IS DISTINCT FROM p_import_id)
  ) THEN codes := array_append(codes, 'foreign_campaign_membership'); END IF;

  RETURN codes;
END;
$$;


ALTER FUNCTION "public"."_import_undo_blockers"("p_import_id" "uuid", "p_org" "uuid", "p_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_import_undo_context"("p_import_id" "uuid", OUT "reason" "text", OUT "authorized" boolean, OUT "org_id" "uuid", OUT "agent_id" "uuid", OUT "campaign_id" "uuid", OUT "validated_ids" "uuid"[], OUT "imported_count" integer, OUT "completion_status" "text", OUT "undo_status" "text", OUT "created_at" timestamp with time zone, OUT "expired" boolean, OUT "already_undone" boolean) RETURNS "record"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pg_temp'
    AS $_$
DECLARE
  v_uid    uuid := auth.uid();
  v_org    uuid := public.get_org_id();
  v_imp    public.import_history%ROWTYPE;
  v_prof   RECORD;
  v_texts  text[];
  v_uuid_re text := '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';
BEGIN
  reason := NULL; authorized := false; expired := false; already_undone := false; imported_count := 0;

  IF v_uid IS NULL THEN reason := 'not_authenticated'; RETURN; END IF;
  IF v_org IS NULL THEN reason := 'no_org'; RETURN; END IF;

  SELECT * INTO v_imp FROM public.import_history WHERE id = p_import_id;
  IF NOT FOUND THEN reason := 'not_found'; RETURN; END IF;

  org_id            := v_imp.organization_id;
  agent_id          := v_imp.agent_id;
  campaign_id       := v_imp.campaign_id;
  completion_status := v_imp.import_completion_status;
  undo_status       := v_imp.undo_status;
  created_at        := v_imp.created_at;
  already_undone    := (v_imp.undo_status = 'undone');
  expired           := (v_imp.created_at < now() - interval '24 hours');

  IF v_imp.organization_id IS DISTINCT FROM v_org THEN reason := 'cross_org'; RETURN; END IF;

  SELECT p.role, p.organization_id, p.is_super_admin
    INTO v_prof
    FROM public.profiles p WHERE p.id = v_uid;
  IF NOT FOUND OR v_prof.organization_id IS DISTINCT FROM v_org THEN
    reason := 'not_authorized'; RETURN;
  END IF;

  authorized :=
       (v_imp.agent_id = v_uid)
    OR (v_prof.role = 'Admin')
    OR (COALESCE(v_prof.is_super_admin, false) AND v_prof.organization_id = v_org)
    OR (v_prof.role IN ('Team Leader','Team Lead')
          AND v_imp.agent_id IS NOT NULL
          AND public.is_ancestor_of(v_uid, v_imp.agent_id));

  IF v_imp.agent_id IS NULL
     AND NOT (v_prof.role = 'Admin' OR (COALESCE(v_prof.is_super_admin, false) AND v_prof.organization_id = v_org)) THEN
    authorized := false;
  END IF;

  IF NOT authorized THEN reason := 'not_authorized'; RETURN; END IF;

  IF v_imp.imported_lead_ids IS NULL
     OR jsonb_typeof(v_imp.imported_lead_ids) <> 'array'
     OR jsonb_array_length(v_imp.imported_lead_ids) = 0 THEN
    reason := 'legacy_no_ids'; RETURN;
  END IF;

  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(v_imp.imported_lead_ids) e
    WHERE jsonb_typeof(e) <> 'string' OR (e #>> '{}') !~ v_uuid_re
  ) THEN
    reason := 'invalid_import_provenance'; RETURN;
  END IF;

  SELECT array_agg(e #>> '{}') INTO v_texts FROM jsonb_array_elements(v_imp.imported_lead_ids) e;

  IF (SELECT count(DISTINCT t) FROM unnest(v_texts) t) <> COALESCE(array_length(v_texts, 1), 0) THEN
    reason := 'invalid_import_provenance'; RETURN;
  END IF;

  validated_ids  := v_texts::uuid[];
  imported_count := COALESCE(array_length(validated_ids, 1), 0);

  IF EXISTS (
    SELECT 1 FROM public.leads l
    WHERE l.id = ANY(validated_ids) AND l.organization_id IS DISTINCT FROM v_imp.organization_id
  ) THEN
    reason := 'invalid_import_provenance'; validated_ids := NULL; imported_count := 0; RETURN;
  END IF;
END;
$_$;


ALTER FUNCTION "public"."_import_undo_context"("p_import_id" "uuid", OUT "reason" "text", OUT "authorized" boolean, OUT "org_id" "uuid", OUT "agent_id" "uuid", OUT "campaign_id" "uuid", OUT "validated_ids" "uuid"[], OUT "imported_count" integer, OUT "completion_status" "text", OUT "undo_status" "text", OUT "created_at" timestamp with time zone, OUT "expired" boolean, OUT "already_undone" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_leads_to_campaign"("p_campaign_id" "uuid", "p_lead_ids" "uuid"[], "p_import_history_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  v_campaign RECORD;
  v_campaign_type TEXT;
  v_campaign_user_id UUID;
  v_lead RECORD;
  v_lead_id UUID;
  v_valid_leads JSONB := '[]'::JSONB;
  v_skipped_ids UUID[] := ARRAY[]::UUID[];
  v_added INT := 0;
  v_skipped INT := 0;
  v_attempted INT := COALESCE(array_length(p_lead_ids, 1), 0);
  v_already_exists BOOLEAN;
  v_ctx RECORD;
BEGIN
  IF p_import_history_id IS NOT NULL THEN
    SELECT * INTO v_ctx FROM public._import_undo_context(p_import_history_id);
    IF v_ctx.reason IS NOT NULL THEN
      RAISE EXCEPTION 'import provenance rejected: %', v_ctx.reason USING ERRCODE = '42501';
    END IF;
    IF NOT v_ctx.authorized THEN
      RAISE EXCEPTION 'not authorized for import %', p_import_history_id USING ERRCODE = '42501';
    END IF;
    IF v_ctx.already_undone THEN
      RAISE EXCEPTION 'import % already undone', p_import_history_id USING ERRCODE = '22023';
    END IF;
    IF v_ctx.campaign_id IS DISTINCT FROM p_campaign_id THEN
      RAISE EXCEPTION 'import % campaign mismatch', p_import_history_id USING ERRCODE = '22023';
    END IF;
    IF v_ctx.completion_status IS NOT NULL AND v_ctx.completion_status <> 'pending_campaign' THEN
      RAISE EXCEPTION 'import % already finalized (%)', p_import_history_id, v_ctx.completion_status USING ERRCODE = '22023';
    END IF;
    IF EXISTS (SELECT 1 FROM unnest(p_lead_ids) x WHERE x <> ALL (v_ctx.validated_ids)) THEN
      RAISE EXCEPTION 'lead id outside import % set', p_import_history_id USING ERRCODE = '22023';
    END IF;
  END IF;

  SELECT * INTO v_campaign
  FROM public.campaigns
  WHERE id = p_campaign_id
    AND organization_id = public.get_org_id();

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Campaign not found';
  END IF;

  v_campaign_type := v_campaign.type;
  v_campaign_user_id := v_campaign.user_id;

  FOREACH v_lead_id IN ARRAY p_lead_ids
  LOOP
    SELECT * INTO v_lead
    FROM public.leads
    WHERE id = v_lead_id
      AND organization_id = public.get_org_id();

    IF NOT FOUND THEN
      v_skipped_ids := array_append(v_skipped_ids, v_lead_id);
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;

    SELECT EXISTS (
      SELECT 1 FROM public.campaign_leads
      WHERE campaign_id = p_campaign_id
        AND lead_id = v_lead_id
    ) INTO v_already_exists;

    IF v_already_exists THEN
      v_skipped_ids := array_append(v_skipped_ids, v_lead_id);
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;

    IF v_campaign_type = 'Personal' THEN
      IF v_lead.assigned_agent_id IS DISTINCT FROM v_campaign_user_id THEN
        v_skipped_ids := array_append(v_skipped_ids, v_lead_id);
        v_skipped := v_skipped + 1;
        CONTINUE;
      END IF;

    ELSIF v_campaign_type = 'Team' THEN
      IF NOT (
        v_lead.assigned_agent_id = v_campaign_user_id
        OR public.is_ancestor_of(v_campaign_user_id, v_lead.assigned_agent_id)
      ) THEN
        v_skipped_ids := array_append(v_skipped_ids, v_lead_id);
        v_skipped := v_skipped + 1;
        CONTINUE;
      END IF;

    ELSIF v_campaign_type IN ('Open', 'Open Pool') THEN
      NULL;
    END IF;

    v_valid_leads := v_valid_leads || jsonb_build_object(
      'campaign_id', p_campaign_id,
      'lead_id', v_lead_id,
      'first_name', v_lead.first_name,
      'last_name', v_lead.last_name,
      'phone', v_lead.phone,
      'email', v_lead.email,
      'state', public.normalize_us_state(v_lead.state),
      'age', v_lead.age,
      'status', 'Queued',
      'organization_id', public.get_org_id()
    );
    v_added := v_added + 1;
  END LOOP;

  IF v_added > 0 THEN
    INSERT INTO public.campaign_leads (
      campaign_id, lead_id, first_name, last_name,
      phone, email, state, age, status, organization_id, import_history_id
    )
    SELECT
      (el->>'campaign_id')::UUID,
      (el->>'lead_id')::UUID,
      el->>'first_name',
      el->>'last_name',
      el->>'phone',
      el->>'email',
      el->>'state',
      NULLIF(el->>'age', '')::INTEGER,
      el->>'status',
      (el->>'organization_id')::UUID,
      p_import_history_id
    FROM jsonb_array_elements(v_valid_leads) AS el;
  END IF;

  IF p_import_history_id IS NOT NULL THEN
    UPDATE public.import_history
       SET import_completion_metadata = jsonb_build_object(
             'attempted', COALESCE((import_completion_metadata->>'attempted')::int, 0) + v_attempted,
             'added',     COALESCE((import_completion_metadata->>'added')::int, 0) + v_added,
             'skipped',   COALESCE((import_completion_metadata->>'skipped')::int, 0) + v_skipped,
             'batches',   COALESCE((import_completion_metadata->>'batches')::int, 0) + 1,
             'last_attempt_at', to_jsonb(now())
           )
     WHERE id = p_import_history_id;
  END IF;

  RETURN jsonb_build_object(
    'added', v_added,
    'skipped', v_skipped,
    'skipped_ids', to_jsonb(v_skipped_ids)
  );
END;
$$;


ALTER FUNCTION "public"."add_leads_to_campaign"("p_campaign_id" "uuid", "p_lead_ids" "uuid"[], "p_import_history_id" "uuid") OWNER TO "postgres";

SET default_tablespace = '';

SET default_table_access_method = "heap";


CREATE TABLE IF NOT EXISTS "public"."campaign_leads" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "campaign_id" "uuid" NOT NULL,
    "lead_id" "uuid",
    "first_name" "text" DEFAULT ''::"text",
    "last_name" "text" DEFAULT ''::"text",
    "phone" "text" DEFAULT ''::"text",
    "email" "text" DEFAULT ''::"text",
    "state" "text" DEFAULT ''::"text",
    "age" integer,
    "source" "text" DEFAULT ''::"text",
    "status" "text" DEFAULT 'Queued'::"text",
    "locked_by" "uuid",
    "locked_at" timestamp with time zone,
    "claimed_by" "uuid",
    "claimed_at" timestamp with time zone,
    "call_attempts" integer DEFAULT 0,
    "last_called_at" timestamp with time zone,
    "disposition" "text",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "sort_order" integer DEFAULT 0,
    "organization_id" "uuid",
    "user_id" "uuid" DEFAULT "auth"."uid"(),
    "scheduled_callback_at" timestamp with time zone,
    "callback_due_at" timestamp with time zone,
    "retry_eligible_at" timestamp with time zone,
    "callback_agent_id" "uuid",
    "callback_note" "text",
    "last_advance_call_id" "uuid",
    "import_history_id" "uuid",
    CONSTRAINT "campaign_leads_status_check" CHECK (("status" = ANY (ARRAY['Queued'::"text", 'Locked'::"text", 'Claimed'::"text", 'Called'::"text", 'Skipped'::"text", 'Completed'::"text", 'Failed'::"text", 'Removed'::"text", 'DNC'::"text"])))
);


ALTER TABLE "public"."campaign_leads" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."advance_campaign_lead"("p_campaign_lead_id" "uuid", "p_call_id" "uuid" DEFAULT NULL::"uuid", "p_disposition_id" "uuid" DEFAULT NULL::"uuid", "p_callback_due_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_callback_note" "text" DEFAULT NULL::"text", "p_release_lock" boolean DEFAULT true) RETURNS "public"."campaign_leads"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_org           uuid := public.get_org_id();
  v_uid           uuid := auth.uid();
  v_cl            public.campaign_leads;
  v_max_attempts  integer;
  v_retry_minutes integer;
  v_campaign_action text;
  v_dnc_auto_add    boolean := false;
  v_callback_sched  boolean := false;
  v_appt_sched      boolean := false;
  v_is_convert      boolean := false;
  v_already       boolean;
  v_new_attempts  integer;
  v_status        text;
  v_retry_at      timestamptz;
  v_cb_due        timestamptz := NULL;
  v_cb_sched      timestamptz := NULL;
  v_cb_agent      uuid := NULL;
  v_cb_note       text := NULL;
  v_result        public.campaign_leads;
BEGIN
  IF v_org IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT * INTO v_cl
  FROM public.campaign_leads
  WHERE id = p_campaign_lead_id
    AND organization_id = v_org
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  SELECT c.max_attempts,
         COALESCE(NULLIF(c.retry_interval_minutes, 0),
                  NULLIF(c.retry_interval_hours, 0) * 60,
                  1440)
  INTO v_max_attempts, v_retry_minutes
  FROM public.campaigns c
  WHERE c.id = v_cl.campaign_id
    AND c.organization_id = v_org;

  IF v_retry_minutes IS NULL OR v_retry_minutes <= 0 THEN
    v_retry_minutes := 1440;
  END IF;

  IF p_disposition_id IS NOT NULL THEN
    SELECT d.campaign_action,
           COALESCE(d.dnc_auto_add, false),
           COALESCE(d.callback_scheduler, false),
           COALESCE(d.appointment_scheduler, false),
           COALESCE(ps.convert_to_client, false)
    INTO v_campaign_action, v_dnc_auto_add, v_callback_sched, v_appt_sched, v_is_convert
    FROM public.dispositions d
    LEFT JOIN public.pipeline_stages ps ON ps.id = d.pipeline_stage_id
    WHERE d.id = p_disposition_id
      AND d.organization_id = v_org;
  END IF;

  v_already := (p_call_id IS NOT NULL
                AND v_cl.last_advance_call_id IS NOT DISTINCT FROM p_call_id);
  v_new_attempts := COALESCE(v_cl.call_attempts, 0) + (CASE WHEN v_already THEN 0 ELSE 1 END);

  IF v_is_convert THEN
    v_status := 'Completed';  v_retry_at := NULL;
  ELSIF v_dnc_auto_add THEN
    v_status := 'DNC';        v_retry_at := NULL;
  ELSIF v_campaign_action = 'remove_from_campaign' THEN
    v_status := 'Removed';    v_retry_at := NULL;
  ELSIF v_callback_sched THEN
    v_status := 'Called';     v_retry_at := NULL;
    v_cb_due := p_callback_due_at;  v_cb_sched := p_callback_due_at;  v_cb_agent := v_uid;
    v_cb_note := NULLIF(btrim(COALESCE(p_callback_note, '')), '');
  ELSIF v_appt_sched THEN
    v_status := 'Called';     v_retry_at := NULL;
  ELSE
    v_retry_at := now() + make_interval(mins => v_retry_minutes);
    IF v_max_attempts IS NOT NULL AND v_new_attempts >= v_max_attempts THEN
      v_status := 'Completed';
    ELSE
      v_status := 'Called';
    END IF;
  END IF;

  UPDATE public.campaign_leads
  SET call_attempts       = v_new_attempts,
      last_called_at      = now(),
      retry_eligible_at   = v_retry_at,
      status              = v_status,
      callback_due_at     = v_cb_due,
      scheduled_callback_at = v_cb_sched,
      callback_agent_id   = v_cb_agent,
      callback_note       = v_cb_note,
      last_advance_call_id = COALESCE(p_call_id, last_advance_call_id),
      updated_at          = now()
  WHERE id = p_campaign_lead_id
    AND organization_id = v_org
  RETURNING * INTO v_result;

  IF p_release_lock THEN
    PERFORM public.release_lead_lock(p_campaign_lead_id);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."advance_campaign_lead"("p_campaign_lead_id" "uuid", "p_call_id" "uuid", "p_disposition_id" "uuid", "p_callback_due_at" timestamp with time zone, "p_callback_note" "text", "p_release_lock" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analyze_system_db"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  result jsonb;
  v_tables jsonb;
  v_rls_disabled jsonb;
  v_rls_no_policy jsonb;
  v_rls_always_true jsonb;
  v_sec_def_public jsonb;
  v_sec_def_authenticated jsonb;
  v_mutable_search_path jsonb;
  v_public_buckets jsonb;
  v_public_extensions jsonb;
  v_system_status jsonb;
BEGIN
  -- Check platform_admin
  IF NOT public.is_platform_admin() THEN
    RAISE EXCEPTION 'Access denied. Platform Admin only.';
  END IF;

  -- 1. List of public tables
  SELECT jsonb_agg(tablename) INTO v_tables
  FROM pg_tables WHERE schemaname = 'public';

  -- 2. RLS Disabled in Public
  SELECT jsonb_agg(tablename) INTO v_rls_disabled
  FROM pg_tables WHERE schemaname = 'public' AND rowsecurity = false;

  -- 3. RLS Enabled No Policy
  SELECT jsonb_agg(t.tablename) INTO v_rls_no_policy
  FROM pg_tables t
  WHERE t.schemaname = 'public'
    AND t.rowsecurity = true
    AND NOT EXISTS (
      SELECT 1 FROM pg_policies p
      WHERE p.schemaname = 'public'
        AND p.tablename = t.tablename
    );

  -- 4. RLS Policy Always True (open to public or authenticated)
  SELECT jsonb_agg(jsonb_build_object('table', tablename, 'policy', policyname)) INTO v_rls_always_true
  FROM pg_policies
  WHERE schemaname = 'public'
    AND (qual = 'true' OR with_check = 'true')
    AND roles && ARRAY['public'::name, 'authenticated'::name];

  -- 5. Public Can Execute SECURITY DEFINER Function
  SELECT jsonb_agg(p.proname) INTO v_sec_def_public
  FROM pg_proc p
  JOIN pg_namespace n ON p.pronamespace = n.oid
  WHERE n.nspname = 'public'
    AND p.prosecdef = true
    AND has_function_privilege('public', p.oid, 'execute');

  -- 6. Signed-In Users Can Execute SECURITY DEFINER Function
  SELECT jsonb_agg(p.proname) INTO v_sec_def_authenticated
  FROM pg_proc p
  JOIN pg_namespace n ON p.pronamespace = n.oid
  WHERE n.nspname = 'public'
    AND p.prosecdef = true
    AND has_function_privilege('authenticated', p.oid, 'execute');

  -- 7. Function Search Path Mutable
  SELECT jsonb_agg(p.proname) INTO v_mutable_search_path
  FROM pg_proc p
  JOIN pg_namespace n ON p.pronamespace = n.oid
  WHERE n.nspname = 'public'
    AND p.prosecdef = true
    AND (p.proconfig IS NULL OR NOT (p.proconfig::text LIKE '%search_path=%'));

  -- 8. Public Bucket Allows Listing (using public = true as proxy)
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'storage' AND table_name = 'buckets') THEN
    EXECUTE 'SELECT jsonb_agg(name) FROM storage.buckets WHERE public = true' INTO v_public_buckets;
  ELSE
    v_public_buckets := '[]'::jsonb;
  END IF;

  -- 9. Extension in Public
  SELECT jsonb_agg(extname) INTO v_public_extensions
  FROM pg_extension e
  JOIN pg_namespace n ON e.extnamespace = n.oid
  WHERE n.nspname = 'public';

  -- 10. Existing public.system_status
  SELECT jsonb_agg(jsonb_build_object(
    'component_name', component_name,
    'status', status,
    'description', description,
    'notes', notes
  )) INTO v_system_status
  FROM public.system_status;

  -- Construct final JSON
  result := jsonb_build_object(
    'tables', COALESCE(v_tables, '[]'::jsonb),
    'rls_disabled', COALESCE(v_rls_disabled, '[]'::jsonb),
    'rls_no_policy', COALESCE(v_rls_no_policy, '[]'::jsonb),
    'rls_always_true', COALESCE(v_rls_always_true, '[]'::jsonb),
    'sec_def_public', COALESCE(v_sec_def_public, '[]'::jsonb),
    'sec_def_authenticated', COALESCE(v_sec_def_authenticated, '[]'::jsonb),
    'mutable_search_path', COALESCE(v_mutable_search_path, '[]'::jsonb),
    'public_buckets', COALESCE(v_public_buckets, '[]'::jsonb),
    'public_extensions', COALESCE(v_public_extensions, '[]'::jsonb),
    'system_status', COALESCE(v_system_status, '[]'::jsonb)
  );

  RETURN result;
END;
$$;


ALTER FUNCTION "public"."analyze_system_db"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calls_expired_recording_batch"("p_organization_id" "uuid", "p_cutoff" timestamp with time zone, "p_limit" integer DEFAULT 200) RETURNS TABLE("id" "uuid", "recording_storage_path" "text")
    LANGUAGE "sql" STABLE
    AS $$
  SELECT c.id, c.recording_storage_path
  FROM public.calls c
  WHERE c.organization_id = p_organization_id
    AND c.recording_storage_path IS NOT NULL
    AND btrim(c.recording_storage_path) <> ''
    AND COALESCE(c.ended_at, c.started_at, c.created_at) < p_cutoff
  ORDER BY COALESCE(c.ended_at, c.started_at, c.created_at) ASC
  LIMIT LEAST(GREATEST(COALESCE(p_limit, 200), 1), 500);
$$;


ALTER FUNCTION "public"."calls_expired_recording_batch"("p_organization_id" "uuid", "p_cutoff" timestamp with time zone, "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."calls_expired_recording_batch"("p_organization_id" "uuid", "p_cutoff" timestamp with time zone, "p_limit" integer) IS 'Returns up to p_limit calls for an org whose recording_storage_path should be purged (call ended/started before p_cutoff). Used by recording-retention-purge Edge Function.';



CREATE OR REPLACE FUNCTION "public"."can_edit_campaign_settings"("p_campaign_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_org    uuid;
  v_owner  uuid;
  v_policy text;
  v_role   text;
BEGIN
  SELECT organization_id, user_id, settings_edit_policy
    INTO v_org, v_owner, v_policy
  FROM public.campaigns
  WHERE id = p_campaign_id;

  IF NOT FOUND THEN
    RETURN false;
  END IF;

  -- Super admin scoped to their own org (matches campaign policies).
  IF public.super_admin_own_org(v_org) THEN
    RETURN true;
  END IF;

  -- Hard org isolation (null-safe: NULL org -> blocked).
  IF v_org IS DISTINCT FROM public.get_org_id() THEN
    RETURN false;
  END IF;

  v_role := public.get_user_role();

  -- Admins always — creators cannot lock admins out.
  IF v_role = 'Admin' THEN
    RETURN true;
  END IF;

  -- Creator/owner — allowed unless the policy is admins_only.
  IF v_owner = auth.uid()
     AND v_policy IN ('creator_and_admins', 'team_leaders', 'specific_users') THEN
    RETURN true;
  END IF;

  -- Team Leaders when the policy opens to them ('Team Lead' = defensive alias).
  IF v_policy = 'team_leaders' AND v_role IN ('Team Leader', 'Team Lead') THEN
    RETURN true;
  END IF;

  -- Explicit per-user grant (team_leaders or specific_users).
  IF v_policy IN ('team_leaders', 'specific_users')
     AND EXISTS (
       SELECT 1
       FROM public.campaign_settings_permissions g
       WHERE g.campaign_id = p_campaign_id
         AND g.user_id = auth.uid()
         AND g.permission = 'edit_settings'
     ) THEN
    RETURN true;
  END IF;

  -- admins_only (admins already returned true above) and everything else.
  RETURN false;
END;
$$;


ALTER FUNCTION "public"."can_edit_campaign_settings"("p_campaign_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."can_edit_campaign_settings"("p_campaign_id" "uuid") IS 'True if the current user may edit the campaign''s calling settings (super admin own-org, Admin, owner unless admins_only, Team Leader under team_leaders, or an explicit edit_settings grant). Boolean only; org-isolated.';



CREATE OR REPLACE FUNCTION "public"."cascade_hierarchy_update"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  descendant RECORD;
BEGIN
  -- Find all profiles whose upline_id points to the changed user
  -- and recursively update their hierarchy paths
  FOR descendant IN
    SELECT id FROM public.profiles
    WHERE upline_id = NEW.id AND id != NEW.id
  LOOP
    UPDATE public.profiles
    SET hierarchy_path = compute_hierarchy_path(descendant.id)
    WHERE id = descendant.id;
  END LOOP;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."cascade_hierarchy_update"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_lead"("p_campaign_lead_id" "uuid", "p_lead_id" "uuid", "p_campaign_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_id uuid;
BEGIN
  v_org_id := public.get_org_id();

  IF NOT EXISTS (
    SELECT 1 FROM public.campaigns
    WHERE id = p_campaign_id AND organization_id = v_org_id
  ) THEN
    RAISE EXCEPTION 'claim_lead: campaign not found or org mismatch';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.campaign_leads
    WHERE id = p_campaign_lead_id
      AND campaign_id = p_campaign_id
      AND organization_id = v_org_id
  ) THEN
    RAISE EXCEPTION 'claim_lead: campaign_lead not found or org mismatch';
  END IF;

  UPDATE public.leads
  SET assigned_agent_id = auth.uid(),
      updated_at        = now()
  WHERE id              = p_lead_id
    AND organization_id = v_org_id;
END;
$$;


ALTER FUNCTION "public"."claim_lead"("p_campaign_lead_id" "uuid", "p_lead_id" "uuid", "p_campaign_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."compute_hierarchy_path"("target_user_id" "uuid") RETURNS "public"."ltree"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  path_parts TEXT[] := ARRAY[]::TEXT[];
  current_id UUID := target_user_id;
  current_upline UUID;
  max_depth INT := 20; -- Safety valve against circular references
  depth INT := 0;
BEGIN
  LOOP
    -- Prepend current user to path (replace hyphens with underscores for ltree)
    path_parts := ARRAY[REPLACE(current_id::TEXT, '-', '_')] || path_parts;

    -- Get the upline of the current user
    SELECT upline_id INTO current_upline
    FROM public.profiles WHERE id = current_id;

    -- Stop if no upline, self-reference, or max depth reached
    EXIT WHEN current_upline IS NULL OR current_upline = current_id;

    current_id := current_upline;
    depth := depth + 1;
    EXIT WHEN depth >= max_depth;
  END LOOP;

  RETURN text2ltree(array_to_string(path_parts, '.'));
END;
$$;


ALTER FUNCTION "public"."compute_hierarchy_path"("target_user_id" "uuid") OWNER TO "postgres";


