CREATE OR REPLACE FUNCTION "public"."convert_lead_to_client_atomic"("p_lead_id" "uuid", "p_client" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  v_uid    uuid := auth.uid();
  v_org    uuid := public.get_org_id();
  v_lead   public.leads%ROWTYPE;
  v_prof   RECORD;
  v_existing uuid;
  v_client uuid;
  v_authorized boolean;
  v_cf jsonb;
  v_notes int := 0; v_acts int := 0; v_appts int := 0; v_tasks int := 0;
  v_calls int := 0; v_msgs int := 0; v_msgs2 int := 0; v_emails int := 0; v_wf int := 0;
  v_campaign_rows int := 0;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000'; END IF;
  IF v_org IS NULL THEN RAISE EXCEPTION 'no_org' USING ERRCODE = '28000'; END IF;

  SELECT id INTO v_existing FROM public.clients
   WHERE lead_id = p_lead_id AND organization_id = v_org LIMIT 1;
  IF v_existing IS NOT NULL THEN
    RETURN jsonb_build_object('client_id', v_existing, 'idempotent', true);
  END IF;

  SELECT * INTO v_lead FROM public.leads WHERE id = p_lead_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'lead_not_found' USING ERRCODE = 'P0002'; END IF;
  IF v_lead.organization_id IS DISTINCT FROM v_org THEN
    RAISE EXCEPTION 'cross_org' USING ERRCODE = '42501';
  END IF;

  SELECT p.role, p.organization_id, p.is_super_admin
    INTO v_prof FROM public.profiles p WHERE p.id = v_uid;
  IF NOT FOUND OR v_prof.organization_id IS DISTINCT FROM v_org THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  v_authorized :=
       (v_lead.user_id = v_uid)
    OR (v_lead.assigned_agent_id = v_uid)
    OR (v_lead.user_id IS NULL AND v_lead.assigned_agent_id IS NULL)
    OR (v_prof.role = 'Admin')
    OR (COALESCE(v_prof.is_super_admin, false) AND v_prof.organization_id = v_org)
    OR (v_prof.role IN ('Team Leader','Team Lead') AND (
          public.is_ancestor_of(v_uid, v_lead.user_id)
       OR public.is_ancestor_of(v_uid, v_lead.assigned_agent_id)));
  IF NOT v_authorized THEN RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501'; END IF;

  SELECT id INTO v_existing FROM public.clients
   WHERE lead_id = p_lead_id AND organization_id = v_org LIMIT 1;
  IF v_existing IS NOT NULL THEN
    RETURN jsonb_build_object('client_id', v_existing, 'idempotent', true);
  END IF;

  v_cf := CASE WHEN p_client ? 'custom_fields' AND jsonb_typeof(p_client->'custom_fields') = 'object'
               THEN p_client->'custom_fields' ELSE NULL END;

  INSERT INTO public.clients (
    first_name, last_name, phone, email,
    policy_type, carrier, policy_number, premium, face_amount, issue_date, effective_date,
    beneficiary_name, beneficiary_relationship, beneficiary_phone, notes,
    assigned_agent_id, organization_id, custom_fields, lead_id
  ) VALUES (
    v_lead.first_name, v_lead.last_name, v_lead.phone, v_lead.email,
    COALESCE(NULLIF(p_client->>'policy_type', ''), 'Term'),
    COALESCE(p_client->>'carrier', ''),
    COALESCE(p_client->>'policy_number', ''),
    COALESCE((p_client->>'premium')::numeric, 0),
    COALESCE((p_client->>'face_amount')::numeric, 0),
    NULLIF(p_client->>'issue_date', ''),
    NULLIF(p_client->>'effective_date', ''),
    NULLIF(p_client->>'beneficiary_name', ''),
    NULLIF(p_client->>'beneficiary_relationship', ''),
    NULLIF(p_client->>'beneficiary_phone', ''),
    COALESCE(NULLIF(p_client->>'notes', ''), v_lead.notes),
    v_lead.assigned_agent_id,
    v_org,
    v_cf,
    p_lead_id
  ) RETURNING id INTO v_client;

  UPDATE public.contact_notes SET contact_id = v_client, contact_type = 'client'
   WHERE contact_id = p_lead_id AND contact_type = 'lead';
  GET DIAGNOSTICS v_notes = ROW_COUNT;

  UPDATE public.contact_activities SET contact_id = v_client, contact_type = 'client'
   WHERE contact_id = p_lead_id AND contact_type = 'lead';
  GET DIAGNOSTICS v_acts = ROW_COUNT;

  UPDATE public.appointments SET contact_id = v_client WHERE contact_id = p_lead_id;
  GET DIAGNOSTICS v_appts = ROW_COUNT;

  UPDATE public.tasks SET contact_id = v_client, contact_type = 'client'
   WHERE contact_id = p_lead_id AND contact_type = 'lead';
  GET DIAGNOSTICS v_tasks = ROW_COUNT;

  UPDATE public.calls SET contact_id = v_client, contact_type = 'client'
   WHERE contact_id = p_lead_id AND (contact_type = 'lead' OR contact_type IS NULL);
  GET DIAGNOSTICS v_calls = ROW_COUNT;

  UPDATE public.messages SET contact_id = v_client, contact_type = 'client'
   WHERE contact_id = p_lead_id AND (contact_type = 'lead' OR contact_type IS NULL);
  GET DIAGNOSTICS v_msgs = ROW_COUNT;
  UPDATE public.messages SET contact_id = v_client, contact_type = 'client'
   WHERE lead_id = p_lead_id AND contact_id IS NULL;
  GET DIAGNOSTICS v_msgs2 = ROW_COUNT;

  UPDATE public.contact_emails SET contact_id = v_client WHERE contact_id = p_lead_id;
  GET DIAGNOSTICS v_emails = ROW_COUNT;

  UPDATE public.workflow_executions SET contact_id = v_client, contact_type = 'client'
   WHERE contact_id = p_lead_id AND contact_type = 'lead';
  GET DIAGNOSTICS v_wf = ROW_COUNT;

  SELECT count(*) INTO v_campaign_rows FROM public.campaign_leads WHERE lead_id = p_lead_id;

  DELETE FROM public.leads WHERE id = p_lead_id;

  RETURN jsonb_build_object(
    'client_id', v_client,
    'idempotent', false,
    'transferred', jsonb_build_object(
      'notes', v_notes, 'activities', v_acts, 'appointments', v_appts, 'tasks', v_tasks,
      'calls', v_calls, 'messages', v_msgs + v_msgs2, 'contact_emails', v_emails,
      'workflow_executions', v_wf),
    'campaign_outcome', jsonb_build_object('campaign_leads_preserved', v_campaign_rows)
  );
END;
$$;


ALTER FUNCTION "public"."convert_lead_to_client_atomic"("p_lead_id" "uuid", "p_client" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_agency_group"("p_name" "text") RETURNS TABLE("id" "uuid", "name" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_org uuid;
  v_role text;
  v_is_super boolean;
  v_clean text;
  v_existing int;
  v_new_id uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT organization_id, role, is_super_admin
    INTO v_org, v_role, v_is_super
  FROM public.profiles
  WHERE id = v_uid;

  IF v_org IS NULL THEN
    RAISE EXCEPTION 'Caller has no organization' USING ERRCODE = '42501';
  END IF;

  IF NOT (v_is_super = true OR v_role = 'Admin') THEN
    RAISE EXCEPTION 'Only Admins can create an Agency Group' USING ERRCODE = '42501';
  END IF;

  v_clean := btrim(coalesce(p_name, ''));
  IF char_length(v_clean) < 2 OR char_length(v_clean) > 80 THEN
    RAISE EXCEPTION 'Group name must be between 2 and 80 characters'
      USING ERRCODE = '22023';
  END IF;

  SELECT count(*) INTO v_existing
  FROM public.agency_group_members
  WHERE organization_id = v_org
    AND status IN ('active', 'invited');

  IF v_existing > 0 THEN
    RAISE EXCEPTION 'Your organization already has an Agency Group membership or pending invite'
      USING ERRCODE = '23505';
  END IF;

  INSERT INTO public.agency_groups (name, master_organization_id, created_by)
  VALUES (v_clean, v_org, v_uid)
  RETURNING agency_groups.id INTO v_new_id;

  INSERT INTO public.agency_group_members (
    agency_group_id, organization_id, role, status, joined_at, invited_by
  ) VALUES (
    v_new_id, v_org, 'leader', 'active', now(), v_uid
  );

  RETURN QUERY SELECT v_new_id AS id, v_clean AS name;
END;
$$;


ALTER FUNCTION "public"."create_agency_group"("p_name" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_agency_group"("p_name" "text") IS 'Atomically creates an agency_groups row and its leader agency_group_members row in a single SECURITY DEFINER transaction. Replaces the broken two-step frontend insert that could deadlock on the agency_groups SELECT RLS predicate (which requires a matching agency_group_members row) and could leave orphan groups if the second insert failed. Re-checks role/org server-side because SECURITY DEFINER bypasses RLS; does not trust any frontend-provided organization id.';



CREATE OR REPLACE FUNCTION "public"."custom_access_token_hook"("event" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  claims JSONB;
  user_org_id UUID;
  user_role TEXT;
  user_is_super BOOLEAN;
BEGIN
  -- Extract current claims from the event
  claims := event->'claims';

  -- Fetch the user's org, role, and super admin status from profiles
  SELECT organization_id, role, COALESCE(is_super_admin, false)
  INTO user_org_id, user_role, user_is_super
  FROM public.profiles
  WHERE id = (event->>'user_id')::UUID;

  -- Inject custom claims into the JWT
  claims := jsonb_set(claims, '{org_id}', COALESCE(to_jsonb(user_org_id), 'null'::jsonb));
  claims := jsonb_set(claims, '{user_role}', COALESCE(to_jsonb(user_role), '"Agent"'::jsonb));
  claims := jsonb_set(claims, '{is_super_admin}', to_jsonb(COALESCE(user_is_super, false)));

  -- Return modified event with the enriched claims
  event := jsonb_set(event, '{claims}', claims);
  RETURN event;
END;
$$;


ALTER FUNCTION "public"."custom_access_token_hook"("event" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_contact"("p_contact_type" "text", "p_contact_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_org uuid := public.get_org_id();
  v_role text;
  v_is_super boolean;
  v_type text := lower(btrim(coalesce(p_contact_type, '')));
  v_perm_key text;
  v_owner uuid;
  v_row_org uuid;
  v_deleted int := 0;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000'; END IF;
  IF v_org IS NULL THEN RAISE EXCEPTION 'no_org' USING ERRCODE = '28000'; END IF;
  IF v_type NOT IN ('lead','client','recruit') THEN
    RAISE EXCEPTION 'invalid_contact_type:%', p_contact_type USING ERRCODE = '22023';
  END IF;
  SELECT p.role, COALESCE(p.is_super_admin, false) INTO v_role, v_is_super
  FROM public.profiles p WHERE p.id = v_uid AND p.organization_id = v_org;
  IF NOT FOUND OR v_role IS NULL THEN RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501'; END IF;
  v_perm_key := 'contacts.' || CASE v_type WHEN 'lead' THEN 'leads' WHEN 'client' THEN 'clients' ELSE 'recruits' END || '.delete';
  IF NOT public.has_contacts_permission(v_perm_key) THEN
    RAISE EXCEPTION 'permission_denied:%', v_perm_key USING ERRCODE = '42501';
  END IF;
  IF v_type = 'lead' THEN
    SELECT organization_id, user_id          INTO v_row_org, v_owner FROM public.leads    WHERE id = p_contact_id FOR UPDATE;
  ELSIF v_type = 'client' THEN
    SELECT organization_id, assigned_agent_id INTO v_row_org, v_owner FROM public.clients  WHERE id = p_contact_id FOR UPDATE;
  ELSE
    SELECT organization_id, assigned_agent_id INTO v_row_org, v_owner FROM public.recruits WHERE id = p_contact_id FOR UPDATE;
  END IF;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('deleted', false, 'reason', 'not_found');
  END IF;
  IF v_row_org IS DISTINCT FROM v_org THEN
    RAISE EXCEPTION 'cross_org' USING ERRCODE = '42501';
  END IF;
  IF NOT (
       v_role = 'Admin'
    OR v_is_super
    OR v_owner = v_uid
    OR (v_role IN ('Team Leader','Team Lead') AND v_owner IS NOT NULL AND public.is_ancestor_of(v_uid, v_owner))
  ) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;
  IF v_type = 'lead' THEN
    DELETE FROM public.campaign_leads WHERE lead_id = p_contact_id AND organization_id = v_org;
    DELETE FROM public.leads    WHERE id = p_contact_id AND organization_id = v_org;
  ELSIF v_type = 'client' THEN
    DELETE FROM public.clients  WHERE id = p_contact_id AND organization_id = v_org;
  ELSE
    DELETE FROM public.recruits WHERE id = p_contact_id AND organization_id = v_org;
  END IF;
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN jsonb_build_object('deleted', v_deleted > 0, 'contact_type', v_type, 'id', p_contact_id);
END;
$$;


ALTER FUNCTION "public"."delete_contact"("p_contact_type" "text", "p_contact_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."end_dialer_session"("p_session_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
  v_org uuid;
  v_agent uuid;
  v_session public.dialer_sessions%ROWTYPE;
BEGIN
  v_org := public.get_org_id();
  v_agent := auth.uid();

  IF v_org IS NULL THEN
    RAISE EXCEPTION 'organization context required';
  END IF;

  IF v_agent IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;

  SELECT *
  INTO v_session
  FROM public.dialer_sessions
  WHERE id = p_session_id
    AND organization_id = v_org
    AND agent_id = v_agent;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'dialer session not found or not owned by caller';
  END IF;

  IF v_session.status IN ('ended', 'abandoned') THEN
    RETURN jsonb_build_object(
      'id', v_session.id,
      'organization_id', v_session.organization_id,
      'agent_id', v_session.agent_id,
      'campaign_id', v_session.campaign_id,
      'started_at', v_session.started_at,
      'last_heartbeat_at', v_session.last_heartbeat_at,
      'ended_at', v_session.ended_at,
      'status', v_session.status
    );
  END IF;

  UPDATE public.dialer_sessions
  SET
    status = 'ended',
    ended_at = now(),
    updated_at = now()
  WHERE id = p_session_id
    AND organization_id = v_org
    AND agent_id = v_agent
    AND status = 'active'
  RETURNING * INTO v_session;

  RETURN jsonb_build_object(
    'id', v_session.id,
    'organization_id', v_session.organization_id,
    'agent_id', v_session.agent_id,
    'campaign_id', v_session.campaign_id,
    'started_at', v_session.started_at,
    'last_heartbeat_at', v_session.last_heartbeat_at,
    'ended_at', v_session.ended_at,
    'status', v_session.status
  );
END;
$$;


ALTER FUNCTION "public"."end_dialer_session"("p_session_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_campaign_settings_edit_permission"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_changed boolean;
BEGIN
  v_changed :=
       NEW.max_attempts            IS DISTINCT FROM OLD.max_attempts
    OR NEW.calling_hours_start     IS DISTINCT FROM OLD.calling_hours_start
    OR NEW.calling_hours_end       IS DISTINCT FROM OLD.calling_hours_end
    OR NEW.retry_interval_hours    IS DISTINCT FROM OLD.retry_interval_hours
    OR NEW.retry_interval_minutes  IS DISTINCT FROM OLD.retry_interval_minutes
    OR NEW.ring_timeout_seconds    IS DISTINCT FROM OLD.ring_timeout_seconds
    OR NEW.auto_dial_enabled       IS DISTINCT FROM OLD.auto_dial_enabled
    OR NEW.local_presence_enabled  IS DISTINCT FROM OLD.local_presence_enabled
    OR NEW.number_group_id         IS DISTINCT FROM OLD.number_group_id
    OR NEW.settings_edit_policy    IS DISTINCT FROM OLD.settings_edit_policy
    OR NEW.require_licensed_state_access IS DISTINCT FROM OLD.require_licensed_state_access;

  IF v_changed
     AND auth.uid() IS NOT NULL
     AND NOT public.can_edit_campaign_settings(NEW.id) THEN
    RAISE EXCEPTION 'You don''t have permission to edit this campaign''s settings.'
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_campaign_settings_edit_permission"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_profile_field_authorization"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  actor_id             uuid := auth.uid();
  actor_role           text;
  actor_org            uuid;
  actor_is_super       boolean := false;
  actor_platform_role  text;
  actor_is_platform    boolean := false;
  is_self              boolean;
  has_welcome_col      boolean := (to_jsonb(NEW) ? 'welcome_email_sent_at');
BEGIN
  -- System callers (service role, SECURITY DEFINER triggers, cron) have no
  -- auth.uid() and are trusted.
  IF actor_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Trusted source: the actor's OWN row, read directly. Never the JWT.
  SELECT p.role, p.organization_id, COALESCE(p.is_super_admin, false), p.platform_role
    INTO actor_role, actor_org, actor_is_super, actor_platform_role
  FROM public.profiles p
  WHERE p.id = actor_id;

  -- FAIL CLOSED.
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Authenticated actor profile not found'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  actor_is_super    := COALESCE(actor_is_super, false);
  actor_is_platform := COALESCE(actor_platform_role = 'platform_admin', false);
  is_self           := COALESCE(actor_id = NEW.id, false);

  IF TG_OP = 'INSERT' THEN
    RAISE EXCEPTION 'Profile rows may only be created by the system'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF NEW.id IS DISTINCT FROM OLD.id THEN
    RAISE EXCEPTION 'profiles.id is immutable'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF NEW.organization_id IS DISTINCT FROM OLD.organization_id THEN
    RAISE EXCEPTION 'profiles.organization_id may only be changed by the system (tenancy is not user-editable)'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- Compare against compute_hierarchy_path() so the legitimate cascade passes
  -- while any forged ltree does not.
  IF NEW.hierarchy_path IS DISTINCT FROM OLD.hierarchy_path
     AND NEW.hierarchy_path IS DISTINCT FROM public.compute_hierarchy_path(NEW.id) THEN
    RAISE EXCEPTION 'profiles.hierarchy_path is database-derived; change upline_id instead'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF NEW.twilio_client_identity IS DISTINCT FROM OLD.twilio_client_identity THEN
    RAISE EXCEPTION 'profiles.twilio_client_identity is system-managed'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF NEW.created_at IS DISTINCT FROM OLD.created_at
     OR NEW.last_login_at IS DISTINCT FROM OLD.last_login_at THEN
    RAISE EXCEPTION 'profiles system timestamps are not user-editable'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF has_welcome_col
     AND (to_jsonb(NEW) -> 'welcome_email_sent_at') IS DISTINCT FROM (to_jsonb(OLD) -> 'welcome_email_sent_at') THEN
    RAISE EXCEPTION 'profiles.welcome_email_sent_at is system-managed'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF COALESCE(NEW.is_super_admin, false) IS DISTINCT FROM COALESCE(OLD.is_super_admin, false) THEN
    IF actor_is_super IS NOT TRUE THEN
      RAISE EXCEPTION 'Only a platform super admin may change is_super_admin'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
    IF is_self IS TRUE THEN
      RAISE EXCEPTION 'is_super_admin may not be changed on your own profile'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
  END IF;

  IF NEW.platform_role IS DISTINCT FROM OLD.platform_role THEN
    IF actor_is_platform IS NOT TRUE THEN
      RAISE EXCEPTION 'Only a platform admin may change platform_role'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
    IF is_self IS TRUE THEN
      RAISE EXCEPTION 'platform_role may not be changed on your own profile'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
  END IF;

  IF NEW.role IS DISTINCT FROM OLD.role THEN
    IF is_self IS TRUE THEN
      RAISE EXCEPTION 'You may not change your own role'
        USING ERRCODE = 'insufficient_privilege';
    END IF;

    IF (
      actor_is_super
      OR (actor_role IN ('Admin', 'Super Admin') AND actor_org IS NOT NULL AND actor_org = OLD.organization_id)
    ) IS NOT TRUE THEN
      RAISE EXCEPTION 'Only an Admin of this organization may change a member role'
        USING ERRCODE = 'insufficient_privilege';
    END IF;

    IF NEW.role NOT IN ('Agent', 'Team Leader', 'Admin', 'Super Admin') THEN
      RAISE EXCEPTION 'Role % is not an allowed role', NEW.role
        USING ERRCODE = 'insufficient_privilege';
    END IF;

    IF NEW.role = 'Super Admin' AND actor_is_super IS NOT TRUE THEN
      RAISE EXCEPTION 'Only a platform super admin may grant the Super Admin role'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
  END IF;

  IF NEW.status IS DISTINCT FROM OLD.status
     OR NEW.team_id IS DISTINCT FROM OLD.team_id
     OR NEW.upline_id IS DISTINCT FROM OLD.upline_id
     OR NEW.billing_type IS DISTINCT FROM OLD.billing_type THEN
    IF (
      actor_is_super
      OR (actor_role IN ('Admin', 'Super Admin') AND actor_org IS NOT NULL AND actor_org = OLD.organization_id)
    ) IS NOT TRUE THEN
      RAISE EXCEPTION 'Only an Admin of this organization may change account-control fields (status, team, upline, billing)'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_profile_field_authorization"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."enforce_profile_field_authorization"() IS 'P0: per-column authorization guard for public.profiles. Resolves the actor from public.profiles (never the JWT, never user_metadata) because the JWT claims are derived from the protected columns themselves. Trigger-invoked only; EXECUTE revoked from PUBLIC/anon/authenticated.';



