CREATE OR REPLACE FUNCTION "public"."finalize_contact_import"("p_import_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  c          RECORD;
  v_meta     jsonb;
  v_tagged   int := 0;
  v_attempted int := 0;
  v_added    int := 0;
  v_skipped  int := 0;
  v_status   text;
BEGIN
  SELECT * INTO c FROM public._import_undo_context(p_import_id);
  IF c.reason IS NOT NULL THEN
    RETURN jsonb_build_object('finalized', false, 'reason', c.reason);
  END IF;

  IF c.undo_status = 'undone'
     OR (c.completion_status IS NOT NULL AND c.completion_status <> 'pending_campaign') THEN
    RETURN jsonb_build_object('finalized', true, 'status', c.completion_status, 'idempotent', true);
  END IF;

  IF c.campaign_id IS NULL THEN
    v_status := 'completed';
  ELSE
    SELECT import_completion_metadata INTO v_meta FROM public.import_history WHERE id = p_import_id;
    SELECT count(*) INTO v_tagged FROM public.campaign_leads WHERE import_history_id = p_import_id;
    v_attempted := COALESCE((v_meta->>'attempted')::int, 0);
    v_added     := COALESCE((v_meta->>'added')::int, 0);
    v_skipped   := COALESCE((v_meta->>'skipped')::int, 0);

    IF v_meta IS NULL OR v_attempted = 0 THEN
      v_status := 'campaign_failed';
    ELSIF v_attempted < c.imported_count THEN
      v_status := 'campaign_partial';
    ELSIF v_tagged = v_added AND (v_added + v_skipped) = v_attempted THEN
      v_status := CASE WHEN v_skipped = 0 THEN 'completed' ELSE 'completed_with_skips' END;
    ELSE
      v_status := 'campaign_partial';
    END IF;
  END IF;

  UPDATE public.import_history
     SET import_completion_status   = v_status,
         import_completion_metadata = COALESCE(import_completion_metadata, '{}'::jsonb)
           || jsonb_build_object('finalized_at', to_jsonb(now()), 'tagged', v_tagged)
   WHERE id = p_import_id
     AND (import_completion_status IS NULL OR import_completion_status = 'pending_campaign');

  RETURN jsonb_build_object(
    'finalized', true,
    'status', v_status,
    'idempotent', false,
    'imported_count', c.imported_count,
    'attempted', v_attempted,
    'added', v_added,
    'skipped', v_skipped,
    'tagged_count', v_tagged
  );
END;
$$;


ALTER FUNCTION "public"."finalize_contact_import"("p_import_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."workflows" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "description" "text",
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "trigger_type" "text" NOT NULL,
    "trigger_config" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "folder_id" "uuid",
    CONSTRAINT "workflows_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'active'::"text", 'paused'::"text", 'archived'::"text"]))),
    CONSTRAINT "workflows_trigger_type_check" CHECK (("trigger_type" = ANY (ARRAY['disposition'::"text", 'stage_change'::"text", 'lead_created'::"text", 'time_based'::"text", 'manual'::"text", 'tag_added'::"text", 'tag_removed'::"text", 'call_completed'::"text", 'call_missed'::"text", 'appointment_booked'::"text", 'appointment_cancelled'::"text", 'appointment_no_show'::"text", 'sms_received'::"text", 'email_replied'::"text", 'lead_converted'::"text", 'contact_field_changed'::"text", 'contact_dnc'::"text", 'birthday_approaching'::"text", 'custom_date_approaching'::"text", 'stale_lead'::"text", 'task_completed'::"text", 'task_overdue'::"text"])))
);


ALTER TABLE "public"."workflows" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_active_workflows_for_trigger"("p_org_id" "uuid", "p_trigger_type" "text", "p_trigger_key" "text" DEFAULT NULL::"text") RETURNS SETOF "public"."workflows"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  SELECT w.*
  FROM public.workflows w
  WHERE w.organization_id = p_org_id
    AND w.status = 'active'
    AND w.trigger_type = p_trigger_type
    AND (
      p_trigger_key IS NULL
      OR (w.trigger_config ->> 'disposition_id')   = p_trigger_key
      OR (w.trigger_config ->> 'to_stage_id')      = p_trigger_key
      OR (w.trigger_config ->> 'tag')              = p_trigger_key
      OR (w.trigger_config ->> 'field_name')       = p_trigger_key
      OR (w.trigger_config ->> 'appointment_type') = p_trigger_key
      OR (
        p_trigger_type = 'sms_received'
        AND COALESCE(w.trigger_config ->> 'keyword_filter', '') = ''
      )
      OR (
        p_trigger_type = 'sms_received'
        AND COALESCE(w.trigger_config ->> 'keyword_filter', '') <> ''
        AND p_trigger_key ILIKE '%' || (w.trigger_config ->> 'keyword_filter') || '%'
      )
    );
END;
$$;


ALTER FUNCTION "public"."get_active_workflows_for_trigger"("p_org_id" "uuid", "p_trigger_type" "text", "p_trigger_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_agency_group_leaderboard"("p_group_id" "uuid", "p_period" "text" DEFAULT 'month'::"text") RETURNS TABLE("organization_id" "uuid", "organization_name" "text", "agent_id" "uuid", "agent_first_name" "text", "agent_last_name" "text", "agent_avatar_url" "text", "calls_made" bigint, "appointments_set" bigint, "policies_sold" bigint, "talk_time_seconds" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_caller_org UUID;
  v_period_start TIMESTAMPTZ;
  v_is_member BOOLEAN;
  v_tz TEXT;
BEGIN
  v_caller_org := public.get_org_id();

  SELECT EXISTS (
    SELECT 1 FROM public.agency_group_members
    WHERE agency_group_id = p_group_id
      AND organization_id = v_caller_org
      AND status = 'active'
  ) INTO v_is_member;

  IF NOT v_is_member THEN
    RAISE EXCEPTION 'Access denied: your organization is not an active member of this group';
  END IF;

  SELECT COALESCE(cs.timezone, 'UTC')
  INTO v_tz
  FROM public.company_settings cs
  WHERE cs.organization_id = v_caller_org
  LIMIT 1;

  v_period_start := CASE lower(COALESCE(p_period, 'month'))
    WHEN 'today' THEN (date_trunc('day', now() AT TIME ZONE v_tz) AT TIME ZONE v_tz)
    WHEN 'week' THEN date_trunc('week', now() AT TIME ZONE v_tz) AT TIME ZONE v_tz
    WHEN 'month' THEN date_trunc('month', now() AT TIME ZONE v_tz) AT TIME ZONE v_tz
    WHEN 'quarter' THEN date_trunc('quarter', now() AT TIME ZONE v_tz) AT TIME ZONE v_tz
    WHEN 'year' THEN date_trunc('year', now() AT TIME ZONE v_tz) AT TIME ZONE v_tz
    ELSE date_trunc('month', now() AT TIME ZONE v_tz) AT TIME ZONE v_tz
  END;

  RETURN QUERY
  SELECT
    p.organization_id,
    o.name AS organization_name,
    p.id AS agent_id,
    p.first_name AS agent_first_name,
    p.last_name AS agent_last_name,
    p.avatar_url AS agent_avatar_url,
    COALESCE(c.calls_made, 0)::BIGINT AS calls_made,
    COALESCE(a.appointments_set, 0)::BIGINT AS appointments_set,
    COALESCE(cl.policies_sold, 0)::BIGINT AS policies_sold,
    COALESCE(c.talk_time_seconds, 0)::BIGINT AS talk_time_seconds
  FROM public.profiles p
  INNER JOIN public.organizations o ON o.id = p.organization_id
  INNER JOIN public.agency_group_members agm
    ON agm.organization_id = p.organization_id
    AND agm.agency_group_id = p_group_id
    AND agm.status = 'active'
  LEFT JOIN LATERAL (
    SELECT
      COUNT(*)::BIGINT AS calls_made,
      COALESCE(SUM(cc.duration), 0)::BIGINT AS talk_time_seconds
    FROM public.calls cc
    WHERE cc.agent_id = p.id
      AND cc.created_at >= v_period_start
  ) c ON TRUE
  LEFT JOIN LATERAL (
    SELECT COUNT(*)::BIGINT AS appointments_set
    FROM public.appointments ap
    WHERE ap.user_id = p.id
      AND ap.created_at >= v_period_start
  ) a ON TRUE
  LEFT JOIN LATERAL (
    SELECT COUNT(*)::BIGINT AS policies_sold
    FROM public.clients cli
    WHERE cli.assigned_agent_id = p.id
      AND cli.created_at >= v_period_start
  ) cl ON TRUE
  WHERE p.role IN ('Agent', 'Team Leader', 'Team Lead', 'Admin')
    AND p.status = 'Active'
  ORDER BY policies_sold DESC, calls_made DESC;
END;
$$;


ALTER FUNCTION "public"."get_agency_group_leaderboard"("p_group_id" "uuid", "p_period" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_campaign_card_stats"("p_campaign_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS TABLE("campaign_id" "uuid", "total_leads" integer, "called_leads" integer, "contacted_leads" integer, "converted_leads" integer, "policies_sold" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  -- Resolve caller identity / org / view-all ONCE (single evaluation).
  WITH me AS (
    SELECT
      public.get_org_id() AS org_id,
      auth.uid()          AS uid,
      (
        public.get_user_role() = ANY (ARRAY['Admin', 'Team Leader', 'Team Lead'])
        OR public.is_super_admin()
      )                   AS view_all
  ),
  -- Campaigns the caller may see: org-scoped AND access-scoped to the frontend
  -- `canUserAccessCampaign` rules. `p_campaign_ids` can only narrow this set.
  camp AS (
    SELECT c.id, c.organization_id
    FROM public.campaigns c
    CROSS JOIN me
    WHERE me.org_id IS NOT NULL
      AND c.organization_id = me.org_id
      AND (p_campaign_ids IS NULL OR c.id = ANY (p_campaign_ids))
      AND (
            upper(btrim(c.type)) = ANY (ARRAY['OPEN POOL', 'OPEN'])
         OR (upper(btrim(c.type)) = 'PERSONAL' AND c.user_id = me.uid)
         OR (upper(btrim(c.type)) = 'TEAM'
             AND me.uid::text = ANY (
               ARRAY(SELECT jsonb_array_elements_text(coalesce(c.assigned_agent_ids, '[]'::jsonb)))
             ))
         OR (me.view_all AND upper(btrim(c.type)) = 'TEAM')
      )
  ),
  -- One row per (campaign_lead, OUTBOUND call) with resolved disposition flags.
  call_facts AS (
    SELECT
      cl.campaign_id            AS campaign_id,
      cl.id                     AS campaign_lead_id,
      CASE
        WHEN lower(coalesce(di.name, dn.name, ca.disposition_name, '')) = 'no answer'
          THEN false
        WHEN coalesce(ca.duration, 0) > 45
          THEN true
        WHEN coalesce(di.counts_as_contacted, false)
          THEN true
        WHEN ca.disposition_id IS NULL AND coalesce(dn.counts_as_contacted, false)
          THEN true
        ELSE false
      END AS is_contacted,
      CASE
        WHEN coalesce(psi.convert_to_client, false)
          THEN true
        WHEN ca.disposition_id IS NULL AND coalesce(psn.convert_to_client, false)
          THEN true
        ELSE false
      END AS is_converting
    FROM camp
    JOIN public.campaign_leads cl ON cl.campaign_id = camp.id
    JOIN public.calls ca
      ON ca.campaign_lead_id = cl.id
     AND lower(coalesce(ca.direction, '')) = ANY (ARRAY['outbound', 'outgoing'])
    LEFT JOIN public.dispositions di     ON di.id = ca.disposition_id
    LEFT JOIN public.pipeline_stages psi ON psi.id = di.pipeline_stage_id
    LEFT JOIN public.dispositions dn
      ON ca.disposition_id IS NULL
     AND lower(dn.name) = lower(ca.disposition_name)
     AND dn.organization_id = camp.organization_id
    LEFT JOIN public.pipeline_stages psn ON psn.id = dn.pipeline_stage_id
  )
  SELECT
    camp.id AS campaign_id,
    (SELECT count(*)::int
       FROM public.campaign_leads cl
      WHERE cl.campaign_id = camp.id)                                    AS total_leads,
    (SELECT count(*)::int
       FROM public.campaign_leads cl
      WHERE cl.campaign_id = camp.id
        AND coalesce(cl.call_attempts, 0) > 0)                          AS called_leads,
    (SELECT count(DISTINCT cf.campaign_lead_id)::int
       FROM call_facts cf
      WHERE cf.campaign_id = camp.id
        AND cf.is_contacted)                                            AS contacted_leads,
    (SELECT count(DISTINCT cf.campaign_lead_id)::int
       FROM call_facts cf
      WHERE cf.campaign_id = camp.id
        AND cf.is_converting)                                           AS converted_leads,
    (SELECT count(*)::int
       FROM public.wins w
      WHERE w.campaign_id = camp.id
        AND w.organization_id = camp.organization_id)                  AS policies_sold
  FROM camp;
$$;


ALTER FUNCTION "public"."get_campaign_card_stats"("p_campaign_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_campaign_last_dialed"() RETURNS TABLE("campaign_id" "uuid", "last_dialed_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT
    c.campaign_id,
    MAX(c.created_at) AS last_dialed_at
  FROM public.calls c
  WHERE c.organization_id = public.get_org_id()
    AND c.campaign_id IS NOT NULL
  GROUP BY c.campaign_id;
$$;


ALTER FUNCTION "public"."get_campaign_last_dialed"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_contact_scope_agents"() RETURNS TABLE("id" "uuid", "first_name" "text", "last_name" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT p.id, p.first_name, p.last_name
  FROM public.profiles p
  WHERE p.organization_id = public.get_org_id()
    AND coalesce(p.status, '') IS DISTINCT FROM 'Deleted'
    AND (p.id = auth.uid() OR public.is_ancestor_of(auth.uid(), p.id))
  ORDER BY p.first_name, p.last_name;
$$;


ALTER FUNCTION "public"."get_contact_scope_agents"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_contacts_lead_kanban"("p_filters" "jsonb", "p_per_column" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  WITH lim AS (
    SELECT LEAST(GREATEST(COALESCE(p_per_column, 50), 1), 200) AS n
  ),
  -- Kanban ignores any single-status filter (columns ARE the statuses).
  f AS (
    SELECT * FROM public._contacts_filtered_leads(COALESCE(p_filters, '{}'::jsonb) - 'status')
  ),
  joined AS (
    SELECT f.id, f.ord, l.status
    FROM f JOIN public.leads l ON l.id = f.id
  ),
  counts AS (
    SELECT status, count(*) AS total
    FROM joined
    GROUP BY status
  ),
  ranked AS (
    SELECT j.id, j.ord, j.status,
           row_number() OVER (PARTITION BY j.status ORDER BY j.ord) AS rn
    FROM joined j
  ),
  sliced AS (
    SELECT r.id, r.ord, r.status
    FROM ranked r CROSS JOIN lim
    WHERE r.rn <= lim.n
  ),
  cards AS (
    SELECT s.status,
           jsonb_agg(
             to_jsonb(l)
             || jsonb_build_object(
                  'attempt_count',
                    (
                      SELECT count(DISTINCT c.id)
                      FROM public.calls c
                      WHERE c.direction = 'outbound'
                        AND (
                          c.lead_id = l.id
                          OR (c.lead_id IS NULL AND c.contact_id = l.id AND (c.contact_type = 'lead' OR c.contact_type IS NULL))
                        )
                    ),
                  'last_disposition',
                    (
                      SELECT NULLIF(btrim(c.disposition_name), '')
                      FROM public.calls c
                      WHERE (
                          c.lead_id = l.id
                          OR (c.lead_id IS NULL AND c.contact_id = l.id AND (c.contact_type = 'lead' OR c.contact_type IS NULL))
                        )
                        AND (c.disposition_id IS NOT NULL OR btrim(coalesce(c.disposition_name, '')) <> '')
                      ORDER BY c.created_at DESC NULLS LAST, c.id DESC
                      LIMIT 1
                    )
                )
             ORDER BY s.ord
           ) AS cards
    FROM sliced s JOIN public.leads l ON l.id = s.id
    GROUP BY s.status
  )
  SELECT jsonb_build_object(
    'grand_total', COALESCE((SELECT sum(total) FROM counts), 0),
    'per_column_limit', (SELECT n FROM lim),
    'stages', COALESCE(
      (
        SELECT jsonb_agg(
            jsonb_build_object(
              'status', co.status,
              'total',  co.total,
              'cards',  COALESCE(ca.cards, '[]'::jsonb)
            )
            ORDER BY co.status NULLS LAST
          )
        FROM counts co
        LEFT JOIN cards ca ON ca.status IS NOT DISTINCT FROM co.status
      ),
      '[]'::jsonb
    )
  );
$$;


ALTER FUNCTION "public"."get_contacts_lead_kanban"("p_filters" "jsonb", "p_per_column" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_contacts_recruit_kanban"("p_filters" "jsonb", "p_per_column" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  WITH lim AS (
    SELECT LEAST(GREATEST(COALESCE(p_per_column, 50), 1), 200) AS n
  ),
  f AS (
    SELECT * FROM public._contacts_filtered_recruits(COALESCE(p_filters, '{}'::jsonb) - 'status')
  ),
  joined AS (
    SELECT f.id, f.ord, r.status
    FROM f JOIN public.recruits r ON r.id = f.id
  ),
  counts AS (
    SELECT status, count(*) AS total
    FROM joined
    GROUP BY status
  ),
  ranked AS (
    SELECT j.id, j.ord, j.status,
           row_number() OVER (PARTITION BY j.status ORDER BY j.ord) AS rn
    FROM joined j
  ),
  sliced AS (
    SELECT r.id, r.ord, r.status
    FROM ranked r CROSS JOIN lim
    WHERE r.rn <= lim.n
  ),
  cards AS (
    SELECT s.status,
           jsonb_agg(to_jsonb(r) ORDER BY s.ord) AS cards
    FROM sliced s JOIN public.recruits r ON r.id = s.id
    GROUP BY s.status
  )
  SELECT jsonb_build_object(
    'grand_total', COALESCE((SELECT sum(total) FROM counts), 0),
    'per_column_limit', (SELECT n FROM lim),
    'stages', COALESCE(
      (
        SELECT jsonb_agg(
            jsonb_build_object(
              'status', co.status,
              'total',  co.total,
              'cards',  COALESCE(ca.cards, '[]'::jsonb)
            )
            ORDER BY co.status NULLS LAST
          )
        FROM counts co
        LEFT JOIN cards ca ON ca.status IS NOT DISTINCT FROM co.status
      ),
      '[]'::jsonb
    )
  );
$$;


ALTER FUNCTION "public"."get_contacts_recruit_kanban"("p_filters" "jsonb", "p_per_column" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_enterprise_queue_leads"("p_campaign_id" "uuid", "p_limit" integer, "p_offset" integer, "p_org_id" "uuid") RETURNS SETOF "public"."campaign_leads"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_max_att       INTEGER;
  v_retry_hrs     INTEGER;
  v_hours_start   TIME;
  v_hours_end     TIME;
  v_uid           uuid := auth.uid();
  v_org           uuid;
  v_require_licensed boolean := false;
  v_licensed_states  text[]  := '{}';
BEGIN
  SELECT
    max_attempts,
    COALESCE(retry_interval_hours, 0),
    COALESCE(calling_hours_start, '00:00:00')::TIME,
    COALESCE(calling_hours_end, '23:59:59')::TIME,
    organization_id,
    COALESCE(require_licensed_state_access, false)
  INTO v_max_att, v_retry_hrs, v_hours_start, v_hours_end, v_org, v_require_licensed
  FROM public.campaigns
  WHERE id = p_campaign_id;

  IF v_require_licensed THEN
    SELECT COALESCE(array_agg(DISTINCT x.s), '{}')
    INTO v_licensed_states
    FROM (
      SELECT upper(public.normalize_us_state(asl.state)) AS s
      FROM public.agent_state_licenses asl
      WHERE asl.agent_id = v_uid
        AND asl.organization_id = v_org
    ) x
    WHERE x.s ~ '^[A-Z]{2}$';
  END IF;

  RETURN QUERY
  WITH timezone_mapping AS (
    SELECT * FROM (VALUES
      ('AL', 'America/Chicago'), ('AK', 'America/Anchorage'), ('AZ', 'America/Phoenix'),
      ('AR', 'America/Chicago'), ('CA', 'America/Los_Angeles'), ('CO', 'America/Denver'),
      ('CT', 'America/New_York'), ('DE', 'America/New_York'), ('DC', 'America/New_York'),
      ('FL', 'America/New_York'), ('GA', 'America/New_York'), ('HI', 'Pacific/Honolulu'),
      ('ID', 'America/Denver'), ('IL', 'America/Chicago'), ('IN', 'America/New_York'),
      ('IA', 'America/Chicago'), ('KS', 'America/Chicago'), ('KY', 'America/Chicago'),
      ('LA', 'America/Chicago'), ('ME', 'America/New_York'), ('MD', 'America/New_York'),
      ('MA', 'America/New_York'), ('MI', 'America/New_York'), ('MN', 'America/Chicago'),
      ('MS', 'America/Chicago'), ('MO', 'America/Chicago'), ('MT', 'America/Denver'),
      ('NE', 'America/Chicago'), ('NV', 'America/Los_Angeles'), ('NH', 'America/New_York'),
      ('NJ', 'America/New_York'), ('NM', 'America/Denver'), ('NY', 'America/New_York'),
      ('NC', 'America/New_York'), ('ND', 'America/Chicago'), ('OH', 'America/New_York'),
      ('OK', 'America/Chicago'), ('OR', 'America/Los_Angeles'), ('PA', 'America/New_York'),
      ('RI', 'America/New_York'), ('SC', 'America/New_York'), ('SD', 'America/Chicago'),
      ('TN', 'America/Chicago'), ('TX', 'America/Chicago'), ('UT', 'America/Denver'),
      ('VT', 'America/New_York'), ('VA', 'America/New_York'), ('WA', 'America/Los_Angeles'),
      ('WV', 'America/New_York'), ('WI', 'America/Chicago'), ('WY', 'America/Denver')
    ) AS t(state_code, tz_name)
  ),
  eligible_leads AS (
    SELECT
      cl.id,
      COALESCE(tm.tz_name, 'America/New_York') as lead_tz
    FROM public.campaign_leads cl
    LEFT JOIN timezone_mapping tm ON UPPER(cl.state) = tm.state_code
    WHERE cl.campaign_id = p_campaign_id
      AND (p_org_id IS NULL OR cl.organization_id = p_org_id)
      AND COALESCE(cl.status, 'Queued') NOT IN ('DNC', 'Completed', 'Removed', 'removed')
  )
  SELECT cl.*
  FROM public.campaign_leads cl
  JOIN eligible_leads l ON cl.id = l.id
  WHERE
    COALESCE(cl.call_attempts, 0) < COALESCE(v_max_att, 9999)
    AND (
      (cl.scheduled_callback_at IS NOT NULL AND cl.scheduled_callback_at <= now())
      OR COALESCE(cl.status, 'Queued') = 'Queued'
      OR (
        cl.status = 'Called'
        AND (
          v_retry_hrs = 0
          OR cl.last_called_at IS NULL
          OR (cl.last_called_at + (v_retry_hrs * interval '1 hour')) <= now()
        )
      )
    )
    AND (
      (now() AT TIME ZONE 'UTC' AT TIME ZONE l.lead_tz)::TIME >= v_hours_start
      AND (now() AT TIME ZONE 'UTC' AT TIME ZONE l.lead_tz)::TIME < v_hours_end
    )
    AND (
      NOT v_require_licensed
      OR NULLIF(btrim(public.normalize_us_state(cl.state)), '') IS NULL
      OR upper(public.normalize_us_state(cl.state)) = ANY (v_licensed_states)
    )
  ORDER BY
    (CASE WHEN cl.scheduled_callback_at IS NOT NULL AND cl.scheduled_callback_at <= now() THEN 0 ELSE 1 END) ASC,
    cl.scheduled_callback_at ASC NULLS LAST,
    cl.created_at ASC
  LIMIT p_limit
  OFFSET p_offset;
END;
$_$;


ALTER FUNCTION "public"."get_enterprise_queue_leads"("p_campaign_id" "uuid", "p_limit" integer, "p_offset" integer, "p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_invitation_by_token_rpc"("invite_token" "text") RETURNS TABLE("id" "uuid", "email" "text", "organization_id" "uuid", "role" "text", "upline_id" "uuid", "first_name" "text", "last_name" "text", "licensed_states" "jsonb", "commission_level" "text", "token" "text", "expires_at" timestamp with time zone, "created_at" timestamp with time zone, "status" "text", "org_name" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    i.id,
    CASE WHEN u.usable THEN i.email ELSE NULL END,
    CASE WHEN u.usable THEN i.organization_id ELSE NULL END,
    CASE WHEN u.usable THEN i.role ELSE NULL END,
    CASE WHEN u.usable THEN i.upline_id ELSE NULL END,
    CASE WHEN u.usable THEN i.first_name ELSE NULL END,
    CASE WHEN u.usable THEN i.last_name ELSE NULL END,
    CASE WHEN u.usable THEN i.licensed_states ELSE NULL END,
    CASE WHEN u.usable THEN i.commission_level ELSE NULL END,
    i.token::TEXT,
    i.expires_at,
    i.created_at,
    i.status,
    CASE WHEN u.usable THEN o.name ELSE NULL END
  FROM public.invitations i
  LEFT JOIN public.organizations o ON i.organization_id = o.id
  CROSS JOIN LATERAL (SELECT (i.status = 'Pending' AND i.expires_at > now()) AS usable) u
  WHERE i.token::TEXT = invite_token
  LIMIT 1;
END;
$$;


ALTER FUNCTION "public"."get_invitation_by_token_rpc"("invite_token" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_invitation_by_token_rpc"("invite_token" "text") IS 'P0: still returns the row (status/expires_at drive the AcceptInvitePage messaging) but nulls organization, role, upline, commission, licensed_states, email and org_name unless the invitation is Pending and unexpired — a dead token no longer discloses tenant data to an anonymous caller.';



CREATE OR REPLACE FUNCTION "public"."get_lead_sources_with_usage"() RETURNS TABLE("id" "uuid", "organization_id" "uuid", "name" "text", "color" "text", "active" boolean, "sort_order" integer, "usage_count" integer, "real_usage_count" bigint, "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    ls.id,
    ls.organization_id,
    ls.name,
    ls.color,
    ls.active,
    ls.sort_order,
    ls.usage_count,
    COALESCE(u.cnt, 0)::bigint AS real_usage_count,
    ls.created_at,
    ls.updated_at
  FROM public.lead_sources ls
  LEFT JOIN LATERAL (
    SELECT count(*)::bigint AS cnt
    FROM public.leads l
    WHERE l.organization_id = ls.organization_id
      AND l.lead_source = ls.name
  ) u ON true
  WHERE ls.organization_id = public.get_org_id()
  ORDER BY ls.sort_order ASC, ls.created_at ASC;
$$;


ALTER FUNCTION "public"."get_lead_sources_with_usage"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_next_queue_lead"("p_campaign_id" "uuid", "p_filters" "jsonb" DEFAULT '{}'::"jsonb") RETURNS SETOF "public"."campaign_leads"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_org            uuid := public.get_org_id();
  v_uid            uuid := auth.uid();
  v_campaign       RECORD;
  v_ctype          text;
  v_locked_id      uuid;
  v_result         public.campaign_leads;
  v_filter_state   text;
  v_filter_source  text;
  v_filter_status  text;
  v_filter_max_att integer;
  v_require_licensed boolean := false;
  v_licensed_states  text[]  := '{}';
BEGIN
  DELETE FROM public.dialer_lead_locks
  WHERE campaign_id = p_campaign_id
    AND expires_at <= now();

  SELECT c.id,
         upper(trim(c.type)) AS ctype,
         c.assigned_agent_ids,
         c.organization_id,
         c.max_attempts,
         c.require_licensed_state_access
  INTO v_campaign
  FROM public.campaigns c
  WHERE c.id = p_campaign_id
    AND c.organization_id = v_org;

  IF NOT FOUND THEN
    RETURN;
  END IF;
  v_ctype := v_campaign.ctype;

  IF v_ctype = 'TEAM' THEN
    IF NOT (
      v_uid::text = ANY (
        ARRAY(SELECT jsonb_array_elements_text(v_campaign.assigned_agent_ids))
      )
    ) THEN
      RETURN;
    END IF;
  END IF;

  v_require_licensed := COALESCE(v_campaign.require_licensed_state_access, false);
  IF v_require_licensed THEN
    SELECT COALESCE(array_agg(DISTINCT x.s), '{}')
    INTO v_licensed_states
    FROM (
      SELECT upper(public.normalize_us_state(asl.state)) AS s
      FROM public.agent_state_licenses asl
      WHERE asl.agent_id = v_uid
        AND asl.organization_id = v_org
    ) x
    WHERE x.s ~ '^[A-Z]{2}$';
  END IF;

  v_filter_state   := NULLIF(p_filters->>'state', '');
  v_filter_source  := NULLIF(p_filters->>'lead_source', '');
  v_filter_status  := NULLIF(p_filters->>'status', '');
  v_filter_max_att := NULLIF(p_filters->>'max_attempts', '')::integer;

  SELECT cl.id
  INTO v_locked_id
  FROM public.campaign_leads cl
  JOIN public.leads l ON l.id = cl.lead_id
  WHERE cl.campaign_id = p_campaign_id
    AND cl.organization_id = v_org
    AND cl.status NOT IN ('DNC', 'Completed', 'Removed', 'Failed')
    AND (v_campaign.max_attempts IS NULL
         OR COALESCE(cl.call_attempts, 0) < v_campaign.max_attempts)
    AND (cl.retry_eligible_at IS NULL OR cl.retry_eligible_at <= now())
    AND (cl.callback_agent_id IS NULL OR cl.callback_agent_id = v_uid)
    AND (l.assigned_agent_id IS NULL OR l.assigned_agent_id = v_uid)
    AND NOT EXISTS (
      SELECT 1 FROM public.dialer_lead_locks dll
      WHERE dll.campaign_lead_id = cl.id
        AND dll.expires_at > now()
        AND dll.locked_by <> v_uid
    )
    AND NOT EXISTS (
      SELECT 1 FROM public.campaign_lead_agent_suppressions s
      WHERE s.campaign_lead_id = cl.id
        AND s.agent_id = v_uid
        AND s.suppressed_until > now()
    )
    AND (v_filter_status IS NULL OR cl.status = v_filter_status)
    AND (v_filter_state  IS NULL
         OR cl.state = v_filter_state
         OR (cl.state IS NULL AND l.state = v_filter_state))
    AND (v_filter_source IS NULL OR l.lead_source = v_filter_source)
    AND (v_filter_max_att IS NULL OR COALESCE(cl.call_attempts, 0) <= v_filter_max_att)
    AND (
      NOT v_require_licensed
      OR NULLIF(btrim(public.normalize_us_state(cl.state)), '') IS NULL
      OR upper(public.normalize_us_state(cl.state)) = ANY (v_licensed_states)
    )
  ORDER BY
    CASE
      WHEN COALESCE(cl.callback_due_at, cl.scheduled_callback_at) IS NOT NULL
           AND cl.callback_agent_id = v_uid
           AND COALESCE(cl.callback_due_at, cl.scheduled_callback_at) <= now() + interval '5 minutes'
        THEN 0
      WHEN COALESCE(cl.call_attempts, 0) = 0 THEN 1
      ELSE 2
    END,
    COALESCE(cl.callback_due_at, cl.scheduled_callback_at) ASC NULLS LAST,
    cl.last_called_at ASC NULLS FIRST,
    cl.created_at ASC
  LIMIT 1
  FOR UPDATE OF cl SKIP LOCKED;

  IF v_locked_id IS NULL THEN
    RETURN;
  END IF;

  INSERT INTO public.dialer_lead_locks
    (campaign_lead_id, locked_by, campaign_id, organization_id, expires_at)
  VALUES
    (v_locked_id, v_uid, p_campaign_id, v_org, now() + interval '5 minutes')
  ON CONFLICT (campaign_lead_id) DO NOTHING;

  SELECT * INTO v_result FROM public.campaign_leads WHERE id = v_locked_id;
  RETURN NEXT v_result;
  RETURN;
END;
$_$;


ALTER FUNCTION "public"."get_next_queue_lead"("p_campaign_id" "uuid", "p_filters" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_org_id"() RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid;
BEGIN
  -- Primary: JWT claim (fast path — no table access)
  v_org := NULLIF(
    current_setting('request.jwt.claims', true)::json
      ->'app_metadata'->>'organization_id',
    ''
  )::uuid;

  IF v_org IS NOT NULL THEN
    RETURN v_org;
  END IF;

  -- Fallback: profile table lookup (handles stale/missing JWT claims)
  SELECT organization_id INTO v_org
  FROM public.profiles
  WHERE id = auth.uid();

  RETURN v_org;
END;
$$;


ALTER FUNCTION "public"."get_org_id"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_org_leaderboard_stats"("p_start" timestamp with time zone, "p_end" timestamp with time zone) RETURNS TABLE("agent_id" "uuid", "first_name" "text", "last_name" "text", "avatar_url" "text", "calls_made" bigint, "appointments_set" bigint, "policies_sold" bigint, "annualized_premium" numeric, "talk_time_seconds" bigint, "recent_wins_7d" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid;
  v_org uuid;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'get_org_leaderboard_stats: not authenticated';
  END IF;

  SELECT pr.organization_id INTO v_org
  FROM public.profiles pr
  WHERE pr.id = v_uid;

  IF v_org IS NULL THEN
    RAISE EXCEPTION 'get_org_leaderboard_stats: no organization for caller';
  END IF;

  IF p_start IS NULL OR p_end IS NULL OR p_end <= p_start THEN
    RAISE EXCEPTION 'get_org_leaderboard_stats: invalid date bounds';
  END IF;

  IF (p_end - p_start) > interval '35 days' THEN
    RAISE EXCEPTION 'get_org_leaderboard_stats: unreasonable date window';
  END IF;

  -- Each source table is scanned ONCE for the whole organization/window and
  -- grouped by agent — never rescanned per profile (the LATERAL formulation
  -- this replaced re-ran every subquery once per roster row).
  RETURN QUERY
  WITH call_stats AS (
    SELECT
      cc.agent_id AS stats_agent_id,
      COUNT(*)::bigint AS calls_made,
      COALESCE(SUM(GREATEST(COALESCE(cc.duration, 0), 0)), 0)::bigint AS talk_time_seconds
    FROM public.calls cc
    WHERE cc.organization_id = v_org
      AND cc.created_at >= p_start
      AND cc.created_at <  p_end
      AND lower(COALESCE(cc.direction, '')) = ANY (ARRAY['outbound', 'outgoing'])
    GROUP BY cc.agent_id
  ),
  appt_stats AS (
    SELECT
      COALESCE(ap.created_by, ap.user_id) AS stats_agent_id,
      COUNT(*)::bigint AS appointments_set
    FROM public.appointments ap
    WHERE ap.organization_id = v_org
      AND ap.created_at >= p_start
      AND ap.created_at <  p_end
      AND COALESCE(ap.created_by, ap.user_id) IS NOT NULL
    GROUP BY COALESCE(ap.created_by, ap.user_id)
  ),
  win_stats AS (
    SELECT
      ww.agent_id AS stats_agent_id,
      COUNT(*)::bigint AS policies_sold,
      COALESCE(SUM(
        12 * CASE
          WHEN COALESCE(ww.premium_amount, 0) <> 0 THEN ww.premium_amount
          ELSE COALESCE(cl.premium, 0)
        END
      ), 0)::numeric AS annualized_premium
    FROM public.wins ww
    LEFT JOIN public.clients cl
      ON cl.id = ww.contact_id
     AND cl.organization_id = ww.organization_id
    WHERE ww.organization_id = v_org
      AND ww.created_at >= p_start
      AND ww.created_at <  p_end
    GROUP BY ww.agent_id
  ),
  recent_win_stats AS (
    SELECT
      wr.agent_id AS stats_agent_id,
      COUNT(*)::bigint AS recent_wins_7d
    FROM public.wins wr
    WHERE wr.organization_id = v_org
      AND wr.created_at >= now() - interval '7 days'
    GROUP BY wr.agent_id
  )
  SELECT
    p.id,
    p.first_name,
    p.last_name,
    p.avatar_url,
    COALESCE(c.calls_made, 0)::bigint,
    COALESCE(a.appointments_set, 0)::bigint,
    COALESCE(w.policies_sold, 0)::bigint,
    COALESCE(w.annualized_premium, 0)::numeric,
    COALESCE(c.talk_time_seconds, 0)::bigint,
    COALESCE(r.recent_wins_7d, 0)::bigint
  FROM public.profiles p
  LEFT JOIN call_stats c ON c.stats_agent_id = p.id
  LEFT JOIN appt_stats a ON a.stats_agent_id = p.id
  LEFT JOIN win_stats w ON w.stats_agent_id = p.id
  LEFT JOIN recent_win_stats r ON r.stats_agent_id = p.id
  WHERE p.organization_id = v_org
    AND p.status = 'Active'
  ORDER BY p.last_name ASC, p.first_name ASC, p.id ASC;
END;
$$;


ALTER FUNCTION "public"."get_org_leaderboard_stats"("p_start" timestamp with time zone, "p_end" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_queue_metrics"("p_campaign_id" "uuid") RETURNS TABLE("total_leads" integer, "eligible_leads" integer, "locked_leads" integer, "active_agents" integer, "available_leads" integer, "suppressed_for_current_agent" integer, "retry_blocked_leads" integer, "callback_waiting_leads" integer, "next_eligible_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_org            uuid := public.get_org_id();
  v_uid            uuid := auth.uid();
  v_campaign       RECORD;
  v_ctype          text;
  -- Manager queue_filters (same supported keys as get_next_queue_lead).
  v_filter_state   text;
  v_filter_source  text;
  v_filter_status  text;
  v_filter_max_att integer;
BEGIN
  -- Load campaign, org-scoped (incl. queue_filters so metrics match the claim path).
  SELECT c.id,
         upper(trim(c.type))    AS ctype,
         c.assigned_agent_ids,
         c.organization_id,
         c.max_attempts,
         c.queue_filters
  INTO v_campaign
  FROM public.campaigns c
  WHERE c.id = p_campaign_id
    AND c.organization_id = v_org;

  IF NOT FOUND THEN
    RETURN QUERY SELECT 0, 0, 0, 0, 0, 0, 0, 0, NULL::timestamptz;
    RETURN;
  END IF;
  v_ctype := v_campaign.ctype;

  -- Parse the stored manager filters (tolerant; absent/empty key = no filter).
  -- Mirrors get_next_queue_lead exactly. min_score/max_score are intentionally
  -- NOT applied here because the canonical claim RPC does not apply them either.
  v_filter_state   := NULLIF(v_campaign.queue_filters->>'state', '');
  v_filter_source  := NULLIF(v_campaign.queue_filters->>'lead_source', '');
  v_filter_status  := NULLIF(v_campaign.queue_filters->>'status', '');
  v_filter_max_att := NULLIF(v_campaign.queue_filters->>'max_attempts', '')::integer;

  -- TEAM eligibility gate: caller must be assigned. Return only the non-
  -- agent-specific total so the panel can still say "N total / 0 available".
  IF v_ctype = 'TEAM'
     AND NOT (
       v_uid::text = ANY (
         ARRAY(SELECT jsonb_array_elements_text(v_campaign.assigned_agent_ids))
       )
     ) THEN
    RETURN QUERY
      SELECT (SELECT count(*)::int
                FROM public.campaign_leads cl
               WHERE cl.campaign_id = p_campaign_id
                 AND cl.organization_id = v_org),
             0, 0, 0, 0, 0, 0, 0, NULL::timestamptz;
    RETURN;
  END IF;

  RETURN QUERY
  WITH base AS (
    SELECT cl.id,
           cl.status,
           cl.call_attempts,
           cl.retry_eligible_at,
           cl.callback_agent_id,
           cl.callback_due_at,
           cl.scheduled_callback_at,
           cl.state           AS cl_state,
           l.state            AS lead_state,
           l.lead_source      AS lead_source,
           l.assigned_agent_id AS lead_assigned_agent_id
    FROM public.campaign_leads cl
    JOIN public.leads l ON l.id = cl.lead_id
    WHERE cl.campaign_id = p_campaign_id
      AND cl.organization_id = v_org
  ),
  locks AS (
    SELECT dll.campaign_lead_id, dll.locked_by, dll.expires_at
    FROM public.dialer_lead_locks dll
    WHERE dll.campaign_id = p_campaign_id
      AND dll.expires_at > now()
  ),
  supp AS (
    SELECT s.campaign_lead_id, s.suppressed_until
    FROM public.campaign_lead_agent_suppressions s
    WHERE s.campaign_id = p_campaign_id
      AND s.agent_id = v_uid
      AND s.suppressed_until > now()
  ),
  enriched AS (
    SELECT b.*,
      (b.status NOT IN ('DNC','Completed','Removed','Failed')
        AND (v_campaign.max_attempts IS NULL
             OR COALESCE(b.call_attempts, 0) < v_campaign.max_attempts)
        -- manager queue_filters — same supported keys as get_next_queue_lead
        AND (v_filter_status IS NULL OR b.status = v_filter_status)
        AND (v_filter_state  IS NULL
             OR b.cl_state = v_filter_state
             OR (b.cl_state IS NULL AND b.lead_state = v_filter_state))
        AND (v_filter_source IS NULL OR b.lead_source = v_filter_source)
        AND (v_filter_max_att IS NULL
             OR COALESCE(b.call_attempts, 0) <= v_filter_max_att)
      )                                                            AS is_eligible_universe,
      (b.callback_agent_id IS NULL OR b.callback_agent_id = v_uid) AS callback_ok,
      (b.lead_assigned_agent_id IS NULL
        OR b.lead_assigned_agent_id = v_uid)                       AS lead_ok,
      EXISTS (SELECT 1 FROM locks lk
               WHERE lk.campaign_lead_id = b.id
                 AND lk.locked_by <> v_uid)                        AS locked_by_other,
      EXISTS (SELECT 1 FROM supp sp
               WHERE sp.campaign_lead_id = b.id)                   AS suppressed_me
    FROM base b
  )
  SELECT
    (SELECT count(*)::int FROM base)                                AS total_leads,
    (SELECT count(*)::int FROM enriched
       WHERE is_eligible_universe)                                  AS eligible_leads,
    (SELECT count(*)::int FROM locks)                               AS locked_leads,
    (SELECT count(DISTINCT locked_by)::int FROM locks)             AS active_agents,
    (SELECT count(*)::int FROM enriched
       WHERE is_eligible_universe
         AND callback_ok AND lead_ok
         AND NOT locked_by_other AND NOT suppressed_me
         AND (retry_eligible_at IS NULL OR retry_eligible_at <= now())
    )                                                              AS available_leads,
    (SELECT count(*)::int FROM supp)                               AS suppressed_for_current_agent,
    (SELECT count(*)::int FROM enriched
       WHERE is_eligible_universe
         AND callback_ok AND lead_ok
         AND NOT locked_by_other AND NOT suppressed_me
         AND retry_eligible_at IS NOT NULL AND retry_eligible_at > now()
    )                                                              AS retry_blocked_leads,
    (SELECT count(*)::int FROM enriched
       WHERE is_eligible_universe
         AND callback_agent_id = v_uid
         AND COALESCE(callback_due_at, scheduled_callback_at) IS NOT NULL
         AND COALESCE(callback_due_at, scheduled_callback_at) > now()
    )                                                              AS callback_waiting_leads,
    (SELECT min(t) FROM (
        SELECT retry_eligible_at AS t FROM enriched
          WHERE is_eligible_universe AND callback_ok AND lead_ok
            AND NOT locked_by_other AND NOT suppressed_me
            AND retry_eligible_at IS NOT NULL AND retry_eligible_at > now()
        UNION ALL
        SELECT COALESCE(callback_due_at, scheduled_callback_at) FROM enriched
          WHERE is_eligible_universe AND callback_agent_id = v_uid
            AND COALESCE(callback_due_at, scheduled_callback_at) > now()
        UNION ALL
        SELECT suppressed_until FROM supp
        UNION ALL
        SELECT lk.expires_at FROM locks lk
          JOIN enriched e ON e.id = lk.campaign_lead_id
          WHERE lk.locked_by <> v_uid
            AND e.is_eligible_universe AND e.callback_ok AND e.lead_ok
            AND NOT e.suppressed_me
            AND (e.retry_eligible_at IS NULL OR e.retry_eligible_at <= now())
    ) future_times WHERE t > now())                                AS next_eligible_at;
END;
$$;


ALTER FUNCTION "public"."get_queue_metrics"("p_campaign_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_trusted_today_dialer_stats"("p_campaign_id" "uuid", "p_start" timestamp with time zone, "p_end" timestamp with time zone) RETURNS TABLE("calls_made" integer, "contacted_calls" integer, "total_talk_seconds" integer, "policies_sold" integer, "session_duration_seconds" integer, "closed_session_duration_seconds" integer, "active_session_id" "uuid", "active_session_started_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  WITH me AS (
    SELECT public.get_org_id() AS org_id, auth.uid() AS uid
  ),
  call_facts AS (
    SELECT
      coalesce(ca.duration, 0) AS duration,
      CASE
        WHEN lower(coalesce(di.name, dn.name, ca.disposition_name, '')) = 'no answer'
          THEN false
        WHEN coalesce(ca.duration, 0) > 45
          THEN true
        WHEN coalesce(di.counts_as_contacted, false)
          THEN true
        WHEN ca.disposition_id IS NULL AND coalesce(dn.counts_as_contacted, false)
          THEN true
        ELSE false
      END AS is_contacted
    FROM me
    JOIN public.calls ca
      ON ca.agent_id = me.uid
     AND ca.organization_id = me.org_id
     AND ca.campaign_id = p_campaign_id
     AND ca.created_at >= p_start
     AND ca.created_at <  p_end
     AND lower(coalesce(ca.direction, '')) = ANY (ARRAY['outbound', 'outgoing'])
    LEFT JOIN public.dispositions di ON di.id = ca.disposition_id
    LEFT JOIN public.dispositions dn
      ON ca.disposition_id IS NULL
     AND lower(dn.name) = lower(ca.disposition_name)
     AND dn.organization_id = me.org_id
    WHERE me.org_id IS NOT NULL AND me.uid IS NOT NULL
  ),
  sess AS (
    SELECT
      s.id,
      s.started_at,
      (s.status = 'active' AND s.ended_at IS NULL) AS is_active,
      GREATEST(0, floor(extract(epoch FROM (
        coalesce(
          s.ended_at,
          CASE
            WHEN s.status = 'active' AND s.ended_at IS NULL THEN now()
            ELSE coalesce(s.last_heartbeat_at, s.started_at)
          END
        ) - s.started_at
      )))::int) AS span
    FROM me
    JOIN public.dialer_sessions s
      ON s.agent_id = me.uid
     AND s.organization_id = me.org_id
     AND s.campaign_id = p_campaign_id
     AND s.started_at >= p_start
     AND s.started_at <  p_end
    WHERE me.org_id IS NOT NULL AND me.uid IS NOT NULL
  ),
  active_sess AS (
    SELECT id, started_at FROM sess WHERE is_active ORDER BY started_at LIMIT 1
  )
  SELECT
    (SELECT count(*)::int FROM call_facts)                                  AS calls_made,
    (SELECT count(*)::int FROM call_facts WHERE is_contacted)               AS contacted_calls,
    (SELECT coalesce(sum(duration), 0)::int FROM call_facts)                AS total_talk_seconds,
    (SELECT count(*)::int
       FROM public.wins w, me
      WHERE w.agent_id = me.uid
        AND w.organization_id = me.org_id
        AND w.campaign_id = p_campaign_id
        AND w.created_at >= p_start
        AND w.created_at <  p_end)                                          AS policies_sold,
    (SELECT coalesce(sum(span), 0)::int FROM sess)                          AS session_duration_seconds,
    (SELECT coalesce(sum(span), 0)::int FROM sess WHERE NOT is_active)      AS closed_session_duration_seconds,
    (SELECT id FROM active_sess)                                            AS active_session_id,
    (SELECT started_at FROM active_sess)                                    AS active_session_started_at;
$$;


ALTER FUNCTION "public"."get_trusted_today_dialer_stats"("p_campaign_id" "uuid", "p_start" timestamp with time zone, "p_end" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_twilio_subaccount_token"("p_org_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'vault', 'pg_temp'
    AS $$
DECLARE
  v_name  text := 'twilio_subaccount_token_' || p_org_id::text;
  v_token text;
BEGIN
  IF p_org_id IS NULL THEN
    RAISE EXCEPTION 'get_twilio_subaccount_token: org id is required';
  END IF;

  SELECT decrypted_secret
  INTO v_token
  FROM vault.decrypted_secrets
  WHERE name = v_name
  LIMIT 1;

  RETURN v_token;
END;
$$;


