CREATE OR REPLACE FUNCTION "public"."global_search"("search_query" "text") RETURNS TABLE("result_type" "text", "id" "uuid", "title" "text", "subtitle" "text", "match_field" "text", "relevance" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with q as (
    select
      case
        when search_query is null or length(trim(search_query)) < 2
          then null
        else '%' || trim(search_query) || '%'
      end as pattern,
      public.get_org_id() as org_id
  ),
  lead_hits (result_type, id, title, subtitle, match_field, relevance) as (
    select
      'lead'::text,
      l.id,
      (l.first_name || ' ' || l.last_name)::text,
      coalesce(nullif(l.phone, ''), nullif(l.email, ''), 'Lead')::text,
      case
        when (l.first_name || ' ' || l.last_name) ilike (select pattern from q) then 'name'
        when l.phone ilike (select pattern from q) then 'phone'
        else 'email'
      end::text,
      100::int
    from public.leads l, q
    where q.pattern is not null
      and l.organization_id = q.org_id
      and (
        (l.first_name || ' ' || l.last_name) ilike q.pattern
        or l.phone ilike q.pattern
        or l.email ilike q.pattern
      )
    limit 5
  ),
  client_hits (result_type, id, title, subtitle, match_field, relevance) as (
    select
      'client'::text,
      c.id,
      (c.first_name || ' ' || c.last_name)::text,
      coalesce(nullif(c.phone, ''), nullif(c.email, ''), 'Client')::text,
      case
        when (c.first_name || ' ' || c.last_name) ilike (select pattern from q) then 'name'
        when c.phone ilike (select pattern from q) then 'phone'
        else 'email'
      end::text,
      90::int
    from public.clients c, q
    where q.pattern is not null
      and c.organization_id = q.org_id
      and (
        (c.first_name || ' ' || c.last_name) ilike q.pattern
        or c.phone ilike q.pattern
        or c.email ilike q.pattern
      )
    limit 5
  ),
  recruit_hits (result_type, id, title, subtitle, match_field, relevance) as (
    select
      'recruit'::text,
      r.id,
      (r.first_name || ' ' || r.last_name)::text,
      coalesce(nullif(r.phone, ''), nullif(r.email, ''), 'Recruit')::text,
      case
        when (r.first_name || ' ' || r.last_name) ilike (select pattern from q) then 'name'
        when r.phone ilike (select pattern from q) then 'phone'
        else 'email'
      end::text,
      80::int
    from public.recruits r, q
    where q.pattern is not null
      and r.organization_id = q.org_id
      and (
        (r.first_name || ' ' || r.last_name) ilike q.pattern
        or r.phone ilike q.pattern
        or r.email ilike q.pattern
      )
    limit 5
  ),
  campaign_hits (result_type, id, title, subtitle, match_field, relevance) as (
    select
      'campaign'::text,
      ca.id,
      ca.name::text,
      coalesce(ca.status, 'campaign')::text,
      case
        when ca.name ilike (select pattern from q) then 'name'
        else 'description'
      end::text,
      70::int
    from public.campaigns ca, q
    where q.pattern is not null
      and ca.organization_id = q.org_id
      and (
        ca.name ilike q.pattern
        or ca.description ilike q.pattern
      )
    limit 5
  ),
  conv_hits (result_type, id, title, subtitle, match_field, relevance) as (
    select
      'conversation'::text,
      cv.id,
      coalesce(cv.contact_name, cv.contact_phone, 'Call')::text,
      coalesce(cv.disposition_name, cv.status, '')::text,
      case
        when cv.contact_name ilike (select pattern from q) then 'contact'
        when cv.contact_phone ilike (select pattern from q) then 'phone'
        else 'disposition'
      end::text,
      60::int
    from public.calls cv, q
    where q.pattern is not null
      and cv.organization_id = q.org_id
      and (
        cv.contact_name ilike q.pattern
        or cv.contact_phone ilike q.pattern
        or cv.disposition_name ilike q.pattern
      )
    order by cv.created_at desc
    limit 5
  )
  select * from lead_hits
  union all select * from client_hits
  union all select * from recruit_hits
  union all select * from campaign_hits
  union all select * from conv_hits
  order by relevance desc, title asc;
$$;


ALTER FUNCTION "public"."global_search"("search_query" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_appointment_workflow_events"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_org_id       uuid;
  v_contact_id   uuid;
  v_appt_type    text;
  v_status_new   text;
  v_status_old   text;
  v_status_lc    text;
BEGIN
  v_org_id     := NULLIF(to_jsonb(NEW) ->> 'organization_id', '')::uuid;
  v_contact_id := NULLIF(to_jsonb(NEW) ->> 'contact_id', '')::uuid;
  v_appt_type  := to_jsonb(NEW) ->> 'type';
  v_status_new := COALESCE(to_jsonb(NEW) ->> 'status', '');

  IF v_org_id IS NULL OR v_contact_id IS NULL THEN
    RETURN NEW;
  END IF;

  BEGIN
    IF TG_OP = 'INSERT' THEN
      PERFORM public.workflow_dispatch_event(
        v_org_id, 'appointment_booked', v_appt_type, v_contact_id, 'lead',
        jsonb_build_object('appointment_id', NEW.id, 'appointment_type', v_appt_type, 'start_time', to_jsonb(NEW) ->> 'start_time')
      );
    ELSIF TG_OP = 'UPDATE' THEN
      v_status_old := COALESCE(to_jsonb(OLD) ->> 'status', '');
      IF v_status_new IS DISTINCT FROM v_status_old THEN
        v_status_lc := lower(v_status_new);
        IF v_status_lc IN ('cancelled', 'canceled') THEN
          PERFORM public.workflow_dispatch_event(
            v_org_id, 'appointment_cancelled', v_appt_type, v_contact_id, 'lead',
            jsonb_build_object('appointment_id', NEW.id, 'appointment_type', v_appt_type)
          );
        ELSIF v_status_lc IN ('no_show', 'no-show', 'noshow') THEN
          PERFORM public.workflow_dispatch_event(
            v_org_id, 'appointment_no_show', v_appt_type, v_contact_id, 'lead',
            jsonb_build_object('appointment_id', NEW.id, 'appointment_type', v_appt_type)
          );
        END IF;
      END IF;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'handle_appointment_workflow_events dispatch failed (appt %): %', NEW.id, SQLERRM;
  END;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_appointment_workflow_events"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_call_workflow_events"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_org_id      uuid;
  v_contact_id  uuid;
  v_disp        text;
  v_disp_name   text;
  v_status      text;
  v_duration    int;
  v_is_missed   boolean;
BEGIN
  v_org_id     := NULLIF(to_jsonb(NEW) ->> 'organization_id', '')::uuid;
  v_contact_id := NULLIF(to_jsonb(NEW) ->> 'contact_id', '')::uuid;
  IF v_contact_id IS NULL THEN
    v_contact_id := NULLIF(to_jsonb(NEW) ->> 'lead_id', '')::uuid;
  END IF;
  v_disp       := NULLIF(to_jsonb(NEW) ->> 'disposition_id', '');
  v_disp_name  := to_jsonb(NEW) ->> 'disposition_name';
  v_status     := COALESCE(to_jsonb(NEW) ->> 'status', '');
  v_duration   := COALESCE((to_jsonb(NEW) ->> 'duration')::int, 0);
  v_is_missed  := COALESCE((to_jsonb(NEW) ->> 'is_missed')::boolean, false);

  IF v_org_id IS NULL OR v_contact_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF v_disp IS NOT NULL THEN
    PERFORM public.workflow_dispatch_event(
      v_org_id, 'disposition', v_disp, v_contact_id, 'lead',
      jsonb_build_object('disposition_id', v_disp, 'disposition_name', v_disp_name)
    );
  END IF;

  PERFORM public.workflow_dispatch_event(
    v_org_id, 'call_completed', NULL, v_contact_id, 'lead',
    jsonb_build_object('duration', v_duration, 'status', v_status, 'is_missed', v_is_missed, 'disposition_id', v_disp)
  );

  IF v_is_missed
     OR v_status IN ('no-answer', 'no_answer', 'missed')
     OR v_duration = 0 THEN
    PERFORM public.workflow_dispatch_event(
      v_org_id, 'call_missed', NULL, v_contact_id, 'lead',
      jsonb_build_object('status', v_status, 'duration', v_duration, 'is_missed', v_is_missed)
    );
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_call_workflow_events"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_client_workflow_events"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_org_id    uuid;
  v_lead_id   uuid;
BEGIN
  v_org_id  := NULLIF(to_jsonb(NEW) ->> 'organization_id', '')::uuid;
  v_lead_id := NULLIF(to_jsonb(NEW) ->> 'lead_id', '')::uuid;

  IF v_org_id IS NULL OR v_lead_id IS NULL THEN
    RETURN NEW;
  END IF;

  BEGIN
    PERFORM public.workflow_dispatch_event(
      v_org_id, 'lead_converted', NULL, v_lead_id, 'lead',
      jsonb_build_object('client_id', NEW.id, 'policy_type', to_jsonb(NEW) ->> 'policy_type')
    );
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'handle_client_workflow_events dispatch failed (client %): %', NEW.id, SQLERRM;
  END;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_client_workflow_events"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_dnc_workflow_events"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_org_id     uuid;
  v_phone      text;
  v_contact_id uuid;
BEGIN
  v_org_id := NULLIF(to_jsonb(NEW) ->> 'organization_id', '')::uuid;
  v_phone  := NULLIF(to_jsonb(NEW) ->> 'phone_number', '');

  IF v_org_id IS NULL OR v_phone IS NULL THEN
    RETURN NEW;
  END IF;

  BEGIN
    SELECT id INTO v_contact_id
    FROM public.leads
    WHERE organization_id = v_org_id AND phone = v_phone
    LIMIT 1;

    IF v_contact_id IS NOT NULL THEN
      PERFORM public.workflow_dispatch_event(
        v_org_id, 'contact_dnc', NULL, v_contact_id, 'lead',
        jsonb_build_object('phone_number', v_phone, 'reason', to_jsonb(NEW) ->> 'reason')
      );
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'handle_dnc_workflow_events dispatch failed (phone %): %', v_phone, SQLERRM;
  END;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_dnc_workflow_events"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_lead_workflow_events"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_old_tags    text[];
  v_new_tags    text[];
  v_added_tag   text;
  v_removed_tag text;
  v_has_tags    boolean;
  v_field       text;
  v_old_val     text;
  v_new_val     text;
  v_tracked_fields text[] := ARRAY[
    'first_name', 'last_name', 'email', 'phone', 'state',
    'lead_source', 'assigned_agent_id'
  ];
BEGIN
  IF TG_OP = 'INSERT' THEN
    PERFORM public.workflow_dispatch_event(
      NEW.organization_id, 'lead_created', NULL, NEW.id, 'lead',
      jsonb_build_object('source', NEW.lead_source)
    );
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    IF NEW.pipeline_stage_id IS DISTINCT FROM OLD.pipeline_stage_id
       AND NEW.pipeline_stage_id IS NOT NULL THEN
      PERFORM public.workflow_dispatch_event(
        NEW.organization_id, 'stage_change', NEW.pipeline_stage_id::text, NEW.id, 'lead',
        jsonb_build_object('old_stage_id', OLD.pipeline_stage_id, 'new_stage_id', NEW.pipeline_stage_id)
      );
    END IF;

    FOREACH v_field IN ARRAY v_tracked_fields LOOP
      v_old_val := to_jsonb(OLD) ->> v_field;
      v_new_val := to_jsonb(NEW) ->> v_field;
      IF v_old_val IS DISTINCT FROM v_new_val THEN
        PERFORM public.workflow_dispatch_event(
          NEW.organization_id, 'contact_field_changed', v_field, NEW.id, 'lead',
          jsonb_build_object('field', v_field, 'old_value', v_old_val, 'new_value', v_new_val)
        );
      END IF;
    END LOOP;

    v_has_tags := (to_jsonb(NEW) ? 'tags');
    IF v_has_tags THEN
      BEGIN
        v_old_tags := COALESCE(ARRAY(SELECT jsonb_array_elements_text(to_jsonb(OLD) -> 'tags')), ARRAY[]::text[]);
        v_new_tags := COALESCE(ARRAY(SELECT jsonb_array_elements_text(to_jsonb(NEW) -> 'tags')), ARRAY[]::text[]);
      EXCEPTION WHEN OTHERS THEN
        v_old_tags := ARRAY[]::text[]; v_new_tags := ARRAY[]::text[];
      END;

      FOREACH v_added_tag IN ARRAY v_new_tags LOOP
        IF NOT (v_added_tag = ANY (v_old_tags)) THEN
          PERFORM public.workflow_dispatch_event(
            NEW.organization_id, 'tag_added', v_added_tag, NEW.id, 'lead',
            jsonb_build_object('tag', v_added_tag)
          );
        END IF;
      END LOOP;

      FOREACH v_removed_tag IN ARRAY v_old_tags LOOP
        IF NOT (v_removed_tag = ANY (v_new_tags)) THEN
          PERFORM public.workflow_dispatch_event(
            NEW.organization_id, 'tag_removed', v_removed_tag, NEW.id, 'lead',
            jsonb_build_object('tag', v_removed_tag)
          );
        END IF;
      END LOOP;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_lead_workflow_events"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_message_workflow_events"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_org_id      uuid;
  v_contact_id  uuid;
  v_direction   text;
  v_body        text;
BEGIN
  v_direction := COALESCE(to_jsonb(NEW) ->> 'direction', '');
  IF v_direction <> 'inbound' THEN
    RETURN NEW;
  END IF;

  v_org_id := NULLIF(to_jsonb(NEW) ->> 'organization_id', '')::uuid;
  v_contact_id := NULLIF(to_jsonb(NEW) ->> 'lead_id', '')::uuid;
  IF v_contact_id IS NULL THEN
    v_contact_id := NULLIF(to_jsonb(NEW) ->> 'contact_id', '')::uuid;
  END IF;
  v_body := COALESCE(to_jsonb(NEW) ->> 'body', '');

  IF v_org_id IS NULL OR v_contact_id IS NULL THEN
    RETURN NEW;
  END IF;

  BEGIN
    PERFORM public.workflow_dispatch_event(
      v_org_id, 'sms_received', v_body, v_contact_id, 'lead',
      jsonb_build_object('message_id', NEW.id, 'body', v_body)
    );
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'handle_message_workflow_events dispatch failed (msg %): %', NEW.id, SQLERRM;
  END;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_message_workflow_events"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_new_organization_provisioning"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
  v_url      text;
  v_key      text;
  v_endpoint text;
BEGIN
  IF NEW.twilio_subaccount_sid IS NOT NULL THEN
    RETURN NEW;
  END IF;

  SELECT supabase_url, service_role_key
  INTO v_url, v_key
  FROM private.twilio_provisioning_config
  WHERE id = 1;

  IF v_url IS NULL OR v_url = '' OR v_key IS NULL OR v_key = '' THEN
    RAISE WARNING 'Twilio subaccount provisioning skipped for org %: private.twilio_provisioning_config not populated', NEW.id;
    RETURN NEW;
  END IF;

  v_endpoint := rtrim(v_url, '/') || '/functions/v1/provision-twilio-subaccount';

  BEGIN
    PERFORM
      net.http_post(
        url := v_endpoint,
        headers := jsonb_build_object(
          'Content-Type', 'application/json',
          'Authorization', 'Bearer ' || v_key
        ),
        body := jsonb_build_object('organization_id', NEW.id),
        timeout_milliseconds := 5000
      );
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'Twilio subaccount provisioning trigger failed for org %: %', NEW.id, SQLERRM;
  END;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_new_organization_provisioning"() OWNER TO "postgres";


