CREATE OR REPLACE FUNCTION "public"."has_contacts_permission"("p_key" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_org uuid := public.get_org_id();
  v_role text;
  v_is_super boolean;
  v_val jsonb;
BEGIN
  IF v_uid IS NULL OR v_org IS NULL THEN
    RETURN false;
  END IF;
  SELECT p.role, COALESCE(p.is_super_admin, false)
    INTO v_role, v_is_super
  FROM public.profiles p
  WHERE p.id = v_uid AND p.organization_id = v_org;
  IF NOT FOUND OR v_role IS NULL THEN
    RETURN false;
  END IF;
  IF v_role = 'Admin' OR v_is_super THEN
    RETURN true;
  END IF;
  SELECT rp.permissions -> 'contacts' -> p_key
    INTO v_val
  FROM public.role_permissions rp
  WHERE rp.organization_id = v_org AND rp.role = v_role;
  IF v_val IS NOT NULL AND jsonb_typeof(v_val) = 'boolean' THEN
    RETURN v_val::boolean;
  END IF;
  RETURN public._contacts_permission_default(v_role, p_key);
END;
$$;


ALTER FUNCTION "public"."has_contacts_permission"("p_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."heartbeat_dialer_session"("p_session_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
  v_org uuid;
  v_agent uuid;
  v_session public.dialer_sessions%ROWTYPE;
BEGIN
  v_org := public.get_org_id();
  v_agent := auth.uid();

  IF v_org IS NULL THEN
    RAISE EXCEPTION 'organization context required';
  END IF;

  IF v_agent IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;

  PERFORM private.close_stale_dialer_sessions(v_org, v_agent, 3);

  UPDATE public.dialer_sessions
  SET
    last_heartbeat_at = now(),
    updated_at = now()
  WHERE id = p_session_id
    AND organization_id = v_org
    AND agent_id = v_agent
    AND status = 'active'
  RETURNING * INTO v_session;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'active dialer session not found or not owned by caller';
  END IF;

  RETURN jsonb_build_object(
    'id', v_session.id,
    'organization_id', v_session.organization_id,
    'agent_id', v_session.agent_id,
    'campaign_id', v_session.campaign_id,
    'started_at', v_session.started_at,
    'last_heartbeat_at', v_session.last_heartbeat_at,
    'ended_at', v_session.ended_at,
    'status', v_session.status
  );
END;
$$;


ALTER FUNCTION "public"."heartbeat_dialer_session"("p_session_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."increment_dialer_stats"("p_agent_id" "uuid", "p_calls_made" integer DEFAULT 0, "p_calls_connected" integer DEFAULT 0, "p_total_talk_seconds" integer DEFAULT 0, "p_policies_sold" integer DEFAULT 0, "p_session_started_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_amd_skipped" integer DEFAULT 0, "p_session_duration_seconds" integer DEFAULT 0) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_org uuid;
BEGIN
  -- Legacy/display compatibility RPC — browser-derived increments only.
  -- Trusted talk time: calls.duration (twilio-voice-status).
  -- Trusted session duration: dialer_sessions server timestamps (Build 2 frontend).

  v_org := public.get_org_id();
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'organization context required';
  END IF;

  IF p_agent_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'agents may only increment their own dialer stats';
  END IF;

  INSERT INTO public.dialer_daily_stats (
    organization_id,
    agent_id,
    stat_date,
    calls_made,
    calls_connected,
    total_talk_seconds,
    policies_sold,
    session_started_at,
    amd_skipped,
    session_duration_seconds,
    last_updated_at
  )
  VALUES (
    v_org,
    p_agent_id,
    CURRENT_DATE,
    p_calls_made,
    p_calls_connected,
    p_total_talk_seconds,
    p_policies_sold,
    p_session_started_at,
    p_amd_skipped,
    p_session_duration_seconds,
    now()
  )
  ON CONFLICT (agent_id, stat_date)
  DO UPDATE SET
    organization_id = EXCLUDED.organization_id,
    calls_made = dialer_daily_stats.calls_made + EXCLUDED.calls_made,
    calls_connected = dialer_daily_stats.calls_connected + EXCLUDED.calls_connected,
    total_talk_seconds = dialer_daily_stats.total_talk_seconds + EXCLUDED.total_talk_seconds,
    policies_sold = dialer_daily_stats.policies_sold + EXCLUDED.policies_sold,
    session_started_at = COALESCE(dialer_daily_stats.session_started_at, EXCLUDED.session_started_at),
    amd_skipped = dialer_daily_stats.amd_skipped + EXCLUDED.amd_skipped,
    session_duration_seconds = dialer_daily_stats.session_duration_seconds + EXCLUDED.session_duration_seconds,
    last_updated_at = now();
END;
$$;


ALTER FUNCTION "public"."increment_dialer_stats"("p_agent_id" "uuid", "p_calls_made" integer, "p_calls_connected" integer, "p_total_talk_seconds" integer, "p_policies_sold" integer, "p_session_started_at" timestamp with time zone, "p_amd_skipped" integer, "p_session_duration_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."increment_phone_number_daily_usage"("p_phone_e164" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_today date;
BEGIN
  IF p_phone_e164 IS NULL OR btrim(p_phone_e164) = '' THEN
    RETURN;
  END IF;

  v_org := public.get_org_id();
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'increment_phone_number_daily_usage: no organization context';
  END IF;

  v_today := (timezone('utc', now()))::date;

  UPDATE public.phone_numbers pn
  SET
    daily_call_count = CASE
      WHEN pn.limit_reset_at IS NULL
        OR (pn.limit_reset_at AT TIME ZONE 'UTC')::date < v_today
      THEN 1
      ELSE COALESCE(pn.daily_call_count, 0) + 1
    END,
    limit_reset_at = CASE
      WHEN pn.limit_reset_at IS NULL
        OR (pn.limit_reset_at AT TIME ZONE 'UTC')::date < v_today
      THEN (v_today::timestamp AT TIME ZONE 'UTC')
      ELSE pn.limit_reset_at
    END,
    updated_at = now()
  WHERE pn.phone_number = p_phone_e164
    AND pn.organization_id = v_org;

  IF NOT FOUND THEN
    -- Number not in org — silent no-op (stale UI / manual entry mismatch)
    RETURN;
  END IF;
END;
$$;


ALTER FUNCTION "public"."increment_phone_number_daily_usage"("p_phone_e164" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."increment_phone_number_daily_usage"("p_phone_e164" "text") IS 'Increments daily_call_count for an org-owned DID; resets count when UTC calendar day changes (limit_reset_at).';



