CREATE TABLE IF NOT EXISTS "public"."profiles" (
    "id" "uuid" NOT NULL,
    "first_name" "text" DEFAULT ''::"text" NOT NULL,
    "last_name" "text" DEFAULT ''::"text" NOT NULL,
    "email" "text" DEFAULT ''::"text" NOT NULL,
    "phone" "text" DEFAULT ''::"text",
    "role" "text" DEFAULT 'Agent'::"text" NOT NULL,
    "status" "text" DEFAULT 'Active'::"text" NOT NULL,
    "availability_status" "text" DEFAULT 'Available'::"text" NOT NULL,
    "avatar_url" "text" DEFAULT ''::"text",
    "theme_preference" "text" DEFAULT 'light'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "resident_state" "text",
    "commission_level" "text" DEFAULT '0%'::"text",
    "npn" "text",
    "timezone" "text" DEFAULT 'Eastern Time (US & Canada)'::"text",
    "win_sound_enabled" boolean DEFAULT true,
    "email_notifications_enabled" boolean DEFAULT true,
    "sms_notifications_enabled" boolean DEFAULT false,
    "push_notifications_enabled" boolean DEFAULT true,
    "licensed_states" "jsonb" DEFAULT '[]'::"jsonb",
    "carriers" "jsonb" DEFAULT '[]'::"jsonb",
    "auto_dial_preference" boolean DEFAULT true,
    "local_presence_enabled" boolean DEFAULT true,
    "upline_id" "uuid",
    "monthly_call_goal" integer DEFAULT 0,
    "monthly_policies_goal" integer DEFAULT 0,
    "weekly_appointments_goal" integer DEFAULT 0,
    "monthly_talk_time_goal" integer DEFAULT 0,
    "monthly_premium_goal" integer DEFAULT 0,
    "weekly_appointment_goal" integer DEFAULT 0,
    "last_login_at" timestamp with time zone,
    "organization_id" "uuid",
    "team_id" "uuid",
    "is_super_admin" boolean DEFAULT false,
    "twilio_client_identity" "text",
    "hierarchy_path" "public"."ltree",
    "onboarding_complete" boolean DEFAULT false NOT NULL,
    "monthly_appointment_goal" integer DEFAULT 0,
    "billing_type" "text" DEFAULT 'agency_covered'::"text",
    "platform_role" "text",
    "welcome_email_sent_at" timestamp with time zone,
    CONSTRAINT "profiles_billing_type_check" CHECK (("billing_type" = ANY (ARRAY['agency_covered'::"text", 'self_pay'::"text"]))),
    CONSTRAINT "profiles_platform_role_check" CHECK ((("platform_role" IS NULL) OR ("platform_role" = 'platform_admin'::"text"))),
    CONSTRAINT "profiles_role_check" CHECK (("role" = ANY (ARRAY['Agent'::"text", 'Team Leader'::"text", 'Admin'::"text", 'Super Admin'::"text"])))
);


