CREATE OR REPLACE FUNCTION "public"."log_control_center_runtime_event"("p_event_type" "text", "p_severity" "text", "p_source" "text", "p_title" "text", "p_message" "text", "p_stack" "text", "p_route" "text", "p_component_name" "text", "p_metadata" "jsonb", "p_event_key" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  v_org_id uuid;
  v_user_id uuid;
  v_event_id uuid;
  v_scoped_key text;
BEGIN
  -- Ensure caller is authenticated
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Resolve organization_id from profiles to prevent tenant spoofing
  SELECT organization_id INTO v_org_id
  FROM public.profiles
  WHERE id = v_user_id;

  -- Prepend the organization ID (or 'global') to the event key to ensure tenant isolation
  v_scoped_key := COALESCE(v_org_id::text, 'global') || ':' || p_event_key;

  -- Perform the upsert
  INSERT INTO public.control_center_runtime_events (
    organization_id,
    user_id,
    event_key,
    event_type,
    severity,
    source,
    route,
    component_name,
    title,
    message,
    stack,
    metadata,
    first_seen_at,
    last_seen_at,
    occurrence_count,
    status
  ) VALUES (
    v_org_id,
    v_user_id,
    v_scoped_key,
    p_event_type,
    p_severity,
    p_source,
    p_route,
    p_component_name,
    p_title,
    p_message,
    p_stack,
    p_metadata,
    now(),
    now(),
    1,
    'open'
  )
  ON CONFLICT (event_key)
  DO UPDATE SET
    occurrence_count = control_center_runtime_events.occurrence_count + 1,
    last_seen_at = now(),
    updated_at = now(),
    status = CASE
      WHEN control_center_runtime_events.status = 'resolved' THEN 'open'
      ELSE control_center_runtime_events.status
    END,
    message = EXCLUDED.message,
    stack = EXCLUDED.stack,
    metadata = EXCLUDED.metadata
  RETURNING id INTO v_event_id;

  RETURN v_event_id;
END;
$$;


ALTER FUNCTION "public"."log_control_center_runtime_event"("p_event_type" "text", "p_severity" "text", "p_source" "text", "p_title" "text", "p_message" "text", "p_stack" "text", "p_route" "text", "p_component_name" "text", "p_metadata" "jsonb", "p_event_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_us_state"("p_raw" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  v_trim  text;
  v_upper text;
  v_code  text;
BEGIN
  IF p_raw IS NULL OR btrim(p_raw) = '' THEN
    RETURN p_raw;
  END IF;

  v_trim  := btrim(p_raw);
  v_upper := upper(v_trim);

  IF v_upper IN (
    'AL','AK','AZ','AR','CA','CO','CT','DE','FL','GA','HI','ID','IL','IN','IA',
    'KS','KY','LA','ME','MD','MA','MI','MN','MS','MO','MT','NE','NV','NH','NJ',
    'NM','NY','NC','ND','OH','OK','OR','PA','RI','SC','SD','TN','TX','UT','VT',
    'VA','WA','WV','WI','WY','DC'
  ) THEN
    RETURN v_upper;
  END IF;

  v_code := CASE lower(v_trim)
    WHEN 'alabama'              THEN 'AL'
    WHEN 'alaska'              THEN 'AK'
    WHEN 'arizona'             THEN 'AZ'
    WHEN 'arkansas'            THEN 'AR'
    WHEN 'california'          THEN 'CA'
    WHEN 'colorado'            THEN 'CO'
    WHEN 'connecticut'         THEN 'CT'
    WHEN 'delaware'            THEN 'DE'
    WHEN 'florida'             THEN 'FL'
    WHEN 'georgia'             THEN 'GA'
    WHEN 'hawaii'              THEN 'HI'
    WHEN 'idaho'               THEN 'ID'
    WHEN 'illinois'            THEN 'IL'
    WHEN 'indiana'             THEN 'IN'
    WHEN 'iowa'                THEN 'IA'
    WHEN 'kansas'              THEN 'KS'
    WHEN 'kentucky'            THEN 'KY'
    WHEN 'louisiana'           THEN 'LA'
    WHEN 'maine'               THEN 'ME'
    WHEN 'maryland'            THEN 'MD'
    WHEN 'massachusetts'       THEN 'MA'
    WHEN 'michigan'            THEN 'MI'
    WHEN 'minnesota'           THEN 'MN'
    WHEN 'mississippi'         THEN 'MS'
    WHEN 'missouri'            THEN 'MO'
    WHEN 'montana'             THEN 'MT'
    WHEN 'nebraska'            THEN 'NE'
    WHEN 'nevada'              THEN 'NV'
    WHEN 'new hampshire'       THEN 'NH'
    WHEN 'new jersey'          THEN 'NJ'
    WHEN 'new mexico'          THEN 'NM'
    WHEN 'new york'            THEN 'NY'
    WHEN 'north carolina'      THEN 'NC'
    WHEN 'north dakota'        THEN 'ND'
    WHEN 'ohio'                THEN 'OH'
    WHEN 'oklahoma'            THEN 'OK'
    WHEN 'oregon'              THEN 'OR'
    WHEN 'pennsylvania'        THEN 'PA'
    WHEN 'rhode island'        THEN 'RI'
    WHEN 'south carolina'      THEN 'SC'
    WHEN 'south dakota'        THEN 'SD'
    WHEN 'tennessee'           THEN 'TN'
    WHEN 'texas'               THEN 'TX'
    WHEN 'utah'                THEN 'UT'
    WHEN 'vermont'             THEN 'VT'
    WHEN 'virginia'            THEN 'VA'
    WHEN 'washington'          THEN 'WA'
    WHEN 'west virginia'       THEN 'WV'
    WHEN 'wisconsin'           THEN 'WI'
    WHEN 'wyoming'             THEN 'WY'
    WHEN 'district of columbia' THEN 'DC'
    ELSE NULL
  END;

  IF v_code IS NOT NULL THEN
    RETURN v_code;
  END IF;

  RETURN p_raw;
END;
$$;


ALTER FUNCTION "public"."normalize_us_state"("p_raw" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."normalize_us_state"("p_raw" "text") IS 'Canonical US state normalizer -> 2-letter USPS code (50 states + DC). Trim + case-insensitive; valid 2-letter -> uppercase; full name -> code; blanks/unrecognized returned unchanged. Mirror of TS/Deno normalizeUsState (Build 2b).';



CREATE OR REPLACE FUNCTION "public"."notify_lead_assigned"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.assigned_agent_id IS NOT NULL
     AND NEW.assigned_agent_id IS DISTINCT FROM OLD.assigned_agent_id THEN
    INSERT INTO public.notifications (
      user_id, type, title, body, action_url, action_label, metadata, organization_id
    )
    VALUES (
      NEW.assigned_agent_id,
      'lead_claimed',
      'New Lead Assigned',
      'A new lead has been assigned to you: '
        || COALESCE(NEW.first_name, '') || ' ' || COALESCE(NEW.last_name, ''),
      '/contacts?id=' || NEW.id::text,
      'View Contact',
      jsonb_build_object('lead_id', NEW.id),
      NEW.organization_id
    );
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."notify_lead_assigned"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."on_profile_update"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  IF NEW.organization_id IS NOT NULL THEN
    PERFORM public.set_claim(NEW.id, 'organization_id', to_jsonb(NEW.organization_id));
  END IF;
  
  IF NEW.role IS NOT NULL THEN
    PERFORM public.set_claim(NEW.id, 'role', to_jsonb(NEW.role));
  END IF;
  
  RETURN NEW;
END;
$$;


