CREATE OR REPLACE FUNCTION "public"."peek_inbound_call_identity"("p_provider_session_id" "text" DEFAULT NULL::"text", "p_twilio_call_sid" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid;
  sid text := nullif(trim(both from coalesce(p_provider_session_id, '')), '');
  cc text := nullif(trim(both from coalesce(p_twilio_call_sid, '')), '');
  cc_norm text;
  r record;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN NULL;
  END IF;

  IF sid IS NULL AND cc IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT p.organization_id INTO v_org
  FROM public.profiles p
  WHERE p.id = auth.uid()
  LIMIT 1;

  IF v_org IS NULL THEN
    RETURN NULL;
  END IF;

  -- Strip Twilio vN: prefix if present (mirrors prior Telnyx prefix-tolerance)
  cc_norm := regexp_replace(cc, '^v[0-9]+:', '');

  SELECT
    c.id,
    c.caller_id_used,
    c.contact_phone,
    c.contact_name,
    c.contact_id,
    c.contact_type
  INTO r
  FROM public.calls c
  WHERE c.organization_id = v_org
    AND c.direction IN ('inbound', 'incoming')
    AND (
      (sid IS NOT NULL AND c.provider_session_id = sid)
      OR (
        cc IS NOT NULL
        AND c.twilio_call_sid IS NOT NULL
        AND (
          c.twilio_call_sid = cc
          OR regexp_replace(c.twilio_call_sid, '^v[0-9]+:', '') = cc_norm
        )
      )
    )
  ORDER BY c.created_at DESC NULLS LAST
  LIMIT 1;

  -- Fallback: latest ringing inbound for this org in the last 6 minutes.
  -- Handles bridged WebRTC legs whose IDs differ from the PSTN row.
  IF NOT FOUND THEN
    SELECT
      c.id,
      c.caller_id_used,
      c.contact_phone,
      c.contact_name,
      c.contact_id,
      c.contact_type
    INTO r
    FROM public.calls c
    WHERE c.organization_id = v_org
      AND c.direction IN ('inbound', 'incoming')
      AND c.status = 'ringing'
      AND c.created_at > now() - interval '6 minutes'
    ORDER BY c.created_at DESC NULLS LAST
    LIMIT 1;
  END IF;

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  RETURN jsonb_build_object(
    'calls_row_id', r.id,
    'caller_id_used', r.caller_id_used,
    'contact_phone', r.contact_phone,
    'contact_name', r.contact_name,
    'contact_id', r.contact_id,
    'contact_type', r.contact_type
  );
END;
$$;


ALTER FUNCTION "public"."peek_inbound_call_identity"("p_provider_session_id" "text", "p_twilio_call_sid" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."peek_inbound_call_identity"("p_provider_session_id" "text", "p_twilio_call_sid" "text") IS 'Inbound ANI/CRM snapshot for caller org. Matches provider_session_id or twilio_call_sid (prefix-tolerant); if no match, falls back to latest ringing inbound in last 6 min (Twilio bridge leg ids may differ from PSTN row).';



CREATE OR REPLACE FUNCTION "public"."preview_contact_import_undo"("p_import_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  c           RECORD;
  v_codes     text[] := ARRAY[]::text[];
  v_existing  int := 0;
  v_tagged    int := 0;
  v_foreign   int := 0;
  v_eligible  boolean;
BEGIN
  SELECT * INTO c FROM public._import_undo_context(p_import_id);

  IF c.reason IS NOT NULL THEN
    RETURN jsonb_build_object(
      'eligible', false,
      'blocked_reason_codes', to_jsonb(ARRAY[c.reason]),
      'import_completion_status', c.completion_status,
      'undo_status', c.undo_status,
      'imported_id_count', COALESCE(c.imported_count, 0)
    );
  END IF;

  IF c.already_undone THEN v_codes := array_append(v_codes, 'already_undone'); END IF;
  IF c.expired       THEN v_codes := array_append(v_codes, 'expired');        END IF;

  v_codes := v_codes || public._import_undo_blockers(p_import_id, c.org_id, c.validated_ids);

  SELECT count(*) INTO v_existing FROM public.leads WHERE id = ANY(c.validated_ids) AND organization_id = c.org_id;
  SELECT count(*) INTO v_tagged   FROM public.campaign_leads WHERE import_history_id = p_import_id;
  SELECT count(*) INTO v_foreign  FROM public.campaign_leads
    WHERE lead_id = ANY(c.validated_ids) AND (import_history_id IS DISTINCT FROM p_import_id);

  SELECT COALESCE(array_agg(DISTINCT x), ARRAY[]::text[]) INTO v_codes FROM unnest(v_codes) x;
  v_eligible := (array_length(v_codes, 1) IS NULL);

  RETURN jsonb_build_object(
    'eligible', v_eligible,
    'imported_id_count', c.imported_count,
    'existing_lead_count', v_existing,
    'campaign_membership_count', v_tagged,
    'foreign_campaign_membership_count', v_foreign,
    'changed_or_missing_count', GREATEST(c.imported_count - v_existing, 0),
    'blocked_reason_codes', to_jsonb(v_codes),
    'import_completion_status', c.completion_status,
    'undo_status', c.undo_status,
    'summary', CASE WHEN v_eligible
                    THEN format('%s leads can be safely removed', c.imported_count)
                    ELSE 'Undo blocked' END
  );
END;
$$;


ALTER FUNCTION "public"."preview_contact_import_undo"("p_import_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."provision_organization"("p_name" "text", "p_slug" "text", "p_owner_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  new_org_id uuid;
  attached   int;
BEGIN
  IF p_name IS NULL OR btrim(p_name) = '' THEN
    RAISE EXCEPTION 'Organization name is required';
  END IF;

  INSERT INTO public.organizations (name, slug)
  VALUES (btrim(p_name), p_slug)
  RETURNING id INTO new_org_id;

  -- Default dispositions. Pipeline stages and appointment types are seeded by
  -- existing AFTER INSERT triggers on public.organizations — do NOT add them.
  INSERT INTO public.dispositions
    (name, color, is_locked, campaign_action, dnc_auto_add, appointment_scheduler, callback_scheduler, organization_id, sort_order)
  VALUES
    ('No Answer',       '#3B82F6', true,  'none',                  false, false, false, new_org_id, 0),
    ('Appointment Set', '#10B981', true,  'remove_from_queue',     false, true,  false, new_org_id, 1),
    ('Call Back',       '#F59E0B', false, 'none',                  false, false, true,  new_org_id, 2),
    ('Not Interested',  '#EF4444', false, 'remove_from_campaign',  false, false, false, new_org_id, 3),
    ('DNC',             '#000000', true,  'remove_from_campaign',  true,  false, false, new_org_id, 4),
    ('Sold',            '#059669', false, 'remove_from_queue',     false, false, false, new_org_id, 5);

  IF p_owner_user_id IS NOT NULL THEN
    UPDATE public.profiles
       SET organization_id = new_org_id,
           role            = 'Admin'
     WHERE id = p_owner_user_id;
    GET DIAGNOSTICS attached = ROW_COUNT;
    IF attached <> 1 THEN
      RAISE EXCEPTION 'Founder profile % not found; rolling back organization', p_owner_user_id;
    END IF;
  END IF;

  RETURN new_org_id;
END;
$$;


ALTER FUNCTION "public"."provision_organization"("p_name" "text", "p_slug" "text", "p_owner_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."provision_organization"("p_name" "text", "p_slug" "text", "p_owner_user_id" "uuid") IS 'P0: atomic organization provisioning (org + default dispositions + optional founder attach). Used by create-user self-serve signup and create-organization. Service-role only.';



CREATE OR REPLACE FUNCTION "public"."reassign_and_delete_lead_source"("p_source_id" "uuid", "p_new_source_id" "uuid") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_id    uuid := public.get_org_id();
  v_role      text := public.get_user_role();
  v_is_super  boolean := public.is_super_admin();
  v_old       public.lead_sources%ROWTYPE;
  v_new       public.lead_sources%ROWTYPE;
  v_reassigned bigint := 0;
BEGIN
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'reassign_and_delete_lead_source: no organization context';
  END IF;
  IF NOT (v_role = 'Admin' OR v_is_super) THEN
    RAISE EXCEPTION 'reassign_and_delete_lead_source: insufficient permissions';
  END IF;
  IF p_source_id IS NULL OR p_new_source_id IS NULL THEN
    RAISE EXCEPTION 'reassign_and_delete_lead_source: both source ids required';
  END IF;
  IF p_source_id = p_new_source_id THEN
    RAISE EXCEPTION 'reassign_and_delete_lead_source: source and replacement must differ';
  END IF;

  SELECT * INTO v_old
  FROM public.lead_sources
  WHERE id = p_source_id AND organization_id = v_org_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'reassign_and_delete_lead_source: source not found in current org';
  END IF;

  SELECT * INTO v_new
  FROM public.lead_sources
  WHERE id = p_new_source_id AND organization_id = v_org_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'reassign_and_delete_lead_source: replacement not found in current org';
  END IF;
  IF v_new.active IS NOT TRUE THEN
    RAISE EXCEPTION 'reassign_and_delete_lead_source: replacement must be active';
  END IF;

  UPDATE public.leads
  SET lead_source = v_new.name
  WHERE organization_id = v_org_id
    AND lead_source = v_old.name;
  GET DIAGNOSTICS v_reassigned = ROW_COUNT;

  DELETE FROM public.lead_sources
  WHERE id = p_source_id AND organization_id = v_org_id;

  RETURN v_reassigned;
END
$$;


ALTER FUNCTION "public"."reassign_and_delete_lead_source"("p_source_id" "uuid", "p_new_source_id" "uuid") OWNER TO "postgres";


