CREATE OR REPLACE FUNCTION "public"."rename_lead_source"("p_source_id" "uuid", "p_new_name" "text", "p_color" "text" DEFAULT NULL::"text") RETURNS TABLE("source_id" "uuid", "new_name" "text", "color" "text", "reassigned_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_id      uuid := public.get_org_id();
  v_role        text := public.get_user_role();
  v_is_super    boolean := public.is_super_admin();
  v_source      public.lead_sources%ROWTYPE;
  v_old_name    text;
  v_new_name    text := btrim(p_new_name);
  v_new_color   text;
  v_dupes       integer;
  v_affected    bigint := 0;
BEGIN
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'rename_lead_source: no organization context';
  END IF;
  IF NOT (v_role = 'Admin' OR v_is_super) THEN
    RAISE EXCEPTION 'rename_lead_source: insufficient permissions';
  END IF;
  IF p_source_id IS NULL THEN
    RAISE EXCEPTION 'rename_lead_source: source id required';
  END IF;
  IF v_new_name IS NULL OR length(v_new_name) = 0 THEN
    RAISE EXCEPTION 'rename_lead_source: name required';
  END IF;
  IF length(v_new_name) > 30 THEN
    RAISE EXCEPTION 'rename_lead_source: name must be 30 characters or less';
  END IF;

  SELECT * INTO v_source
  FROM public.lead_sources
  WHERE id = p_source_id AND organization_id = v_org_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'rename_lead_source: source not found in current org';
  END IF;

  v_old_name := v_source.name;

  SELECT count(*) INTO v_dupes
  FROM public.lead_sources
  WHERE organization_id = v_org_id
    AND id <> p_source_id
    AND active = true
    AND lower(btrim(name)) = lower(v_new_name);
  IF v_dupes > 0 THEN
    RAISE EXCEPTION 'rename_lead_source: a source with this name already exists'
      USING ERRCODE = 'unique_violation';
  END IF;

  v_new_color := COALESCE(NULLIF(btrim(p_color), ''), v_source.color);

  UPDATE public.lead_sources
  SET name = v_new_name,
      color = v_new_color
  WHERE id = p_source_id AND organization_id = v_org_id;

  IF v_old_name IS DISTINCT FROM v_new_name THEN
    UPDATE public.leads
    SET lead_source = v_new_name
    WHERE organization_id = v_org_id
      AND lead_source = v_old_name;
    GET DIAGNOSTICS v_affected = ROW_COUNT;
  END IF;

  source_id := p_source_id;
  new_name  := v_new_name;
  color     := v_new_color;
  reassigned_count := v_affected;
  RETURN NEXT;
END
$$;


ALTER FUNCTION "public"."rename_lead_source"("p_source_id" "uuid", "p_new_name" "text", "p_color" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."renew_lead_lock"("p_campaign_lead_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_rows integer;
BEGIN
  UPDATE public.dialer_lead_locks
  SET expires_at = now() + interval '5 minutes'
  WHERE campaign_lead_id = p_campaign_lead_id
    AND locked_by = auth.uid()
    AND organization_id = public.get_org_id();

  GET DIAGNOSTICS v_rows = ROW_COUNT;
  RETURN v_rows > 0;
END;
$$;


ALTER FUNCTION "public"."renew_lead_lock"("p_campaign_lead_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_inbound_caller_display_name"("p_caller_phone" "text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_last10 text;
  v_fn text;
  v_ln text;
  v_d text;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN NULL;
  END IF;

  v_org := public.get_org_id();
  IF v_org IS NULL THEN
    RETURN NULL;
  END IF;

  v_d := regexp_replace(coalesce(p_caller_phone, ''), '[^0-9]', '', 'g');
  IF v_d IS NULL OR length(v_d) < 10 THEN
    RETURN NULL;
  END IF;

  v_last10 := right(v_d, 10);

  SELECT l.first_name, l.last_name INTO v_fn, v_ln
  FROM public.leads l
  WHERE l.organization_id = v_org
    AND l.phone IS NOT NULL
    AND length(regexp_replace(l.phone, '[^0-9]', '', 'g')) >= 10
    AND (
      right(regexp_replace(l.phone, '[^0-9]', '', 'g'), 10) = v_last10
      OR regexp_replace(l.phone, '[^0-9]', '', 'g') IN ('1' || v_last10, v_last10)
    )
  ORDER BY l.updated_at DESC NULLS LAST
  LIMIT 1;

  IF v_fn IS NOT NULL OR v_ln IS NOT NULL THEN
    RETURN trim(
      both ' '
      from concat_ws(
        ' ',
        nullif(trim(both ' ' from coalesce(v_fn, '')), ''),
        nullif(trim(both ' ' from coalesce(v_ln, '')), '')
      )
    );
  END IF;

  SELECT cl.first_name, cl.last_name INTO v_fn, v_ln
  FROM public.campaign_leads cl
  WHERE cl.organization_id = v_org
    AND cl.phone IS NOT NULL
    AND length(regexp_replace(cl.phone, '[^0-9]', '', 'g')) >= 10
    AND (
      right(regexp_replace(cl.phone, '[^0-9]', '', 'g'), 10) = v_last10
      OR regexp_replace(cl.phone, '[^0-9]', '', 'g') IN ('1' || v_last10, v_last10)
    )
  ORDER BY cl.updated_at DESC NULLS LAST
  LIMIT 1;

  IF v_fn IS NOT NULL OR v_ln IS NOT NULL THEN
    RETURN trim(
      both ' '
      from concat_ws(
        ' ',
        nullif(trim(both ' ' from coalesce(v_fn, '')), ''),
        nullif(trim(both ' ' from coalesce(v_ln, '')), '')
      )
    );
  END IF;

  SELECT c.first_name, c.last_name INTO v_fn, v_ln
  FROM public.clients c
  WHERE c.organization_id = v_org
    AND c.phone IS NOT NULL
    AND length(regexp_replace(c.phone, '[^0-9]', '', 'g')) >= 10
    AND (
      right(regexp_replace(c.phone, '[^0-9]', '', 'g'), 10) = v_last10
      OR regexp_replace(c.phone, '[^0-9]', '', 'g') IN ('1' || v_last10, v_last10)
    )
  ORDER BY c.updated_at DESC NULLS LAST
  LIMIT 1;

  IF v_fn IS NOT NULL OR v_ln IS NOT NULL THEN
    RETURN trim(
      both ' '
      from concat_ws(
        ' ',
        nullif(trim(both ' ' from coalesce(v_fn, '')), ''),
        nullif(trim(both ' ' from coalesce(v_ln, '')), '')
      )
    );
  END IF;

  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."resolve_inbound_caller_display_name"("p_caller_phone" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resolve_inbound_caller_display_name"("p_caller_phone" "text") IS 'Org-scoped inbound CID: leads, campaign_leads, clients by last-10 or exact 10/11-digit NANP variants (SECURITY DEFINER).';



CREATE OR REPLACE FUNCTION "public"."rpc_report_call_summary"("p_org_id" "uuid", "p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone, "p_agent_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_result jsonb;
BEGIN
    WITH base_calls AS (
        SELECT c.*,
               (c.duration > 45 OR EXISTS (
                   SELECT 1 FROM dispositions d
                   WHERE d.id = c.disposition_id
                   AND d.dnc_auto_add = true
               )) as is_contacted,
               EXISTS (
                   SELECT 1 FROM dispositions d
                   JOIN pipeline_stages ps ON ps.id = d.pipeline_stage_id
                   WHERE d.id = c.disposition_id AND ps.convert_to_client = true
               ) as is_converted
        FROM calls c
        WHERE c.organization_id = p_org_id
          AND c.started_at >= p_start_date
          AND c.started_at <= p_end_date
          AND (p_agent_id IS NULL OR c.agent_id = p_agent_id)
    ),
    totals AS (
        SELECT
            COUNT(*) as total_calls,
            COUNT(*) FILTER (WHERE direction != 'inbound') as outbound_calls,
            COUNT(*) FILTER (WHERE direction = 'inbound') as inbound_calls,
            COUNT(*) FILTER (WHERE is_contacted) as contacted_calls,
            COUNT(*) FILTER (WHERE is_converted) as converted_calls,
            COALESCE(SUM(duration), 0) as total_duration_seconds
        FROM base_calls
    ),
    agent_stats AS (
        SELECT
            bc.agent_id,
            (p.first_name || ' ' || COALESCE(p.last_name, '')) as agent_name,
            COUNT(*) as total,
            COUNT(*) FILTER (WHERE bc.is_contacted) as contacted,
            COUNT(*) FILTER (WHERE bc.is_converted) as converted,
            COALESCE(SUM(bc.duration), 0) as total_duration,
            COALESCE(AVG(bc.duration), 0) as avg_duration
        FROM base_calls bc
        JOIN profiles p ON p.id = bc.agent_id
        WHERE bc.agent_id IS NOT NULL
        GROUP BY bc.agent_id, p.first_name, p.last_name
    )
    SELECT jsonb_build_object(
        'total_calls', t.total_calls,
        'outbound', t.outbound_calls,
        'inbound', t.inbound_calls,
        'contacted', t.contacted_calls,
        'converted', t.converted_calls,
        'total_duration_seconds', t.total_duration_seconds,
        'avg_duration_seconds', CASE WHEN t.total_calls > 0 THEN t.total_duration_seconds / t.total_calls ELSE 0 END,
        'answer_rate_pct', CASE WHEN t.total_calls > 0 THEN ROUND((t.contacted_calls::numeric / t.total_calls::numeric) * 100, 2) ELSE 0 END,
        'conversion_rate_pct', CASE WHEN t.contacted_calls > 0 THEN ROUND((t.converted_calls::numeric / t.contacted_calls::numeric) * 100, 2) ELSE 0 END,
        'calls_by_agent', COALESCE((SELECT jsonb_agg(row_to_json(a.*)) FROM agent_stats a), '[]'::jsonb),
        'calls_by_direction', jsonb_build_object('outbound', t.outbound_calls, 'inbound', t.inbound_calls)
    ) INTO v_result
    FROM totals t;

    RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."rpc_report_call_summary"("p_org_id" "uuid", "p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone, "p_agent_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_report_call_volume_timeseries"("p_org_id" "uuid", "p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone, "p_agent_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_result jsonb;
BEGIN
    WITH base_calls AS (
        SELECT c.*,
               (c.duration > 45 OR EXISTS (
                   SELECT 1 FROM dispositions d
                   WHERE d.id = c.disposition_id
                   AND d.dnc_auto_add = true
               )) as is_contacted,
               EXISTS (
                   SELECT 1 FROM dispositions d
                   JOIN pipeline_stages ps ON ps.id = d.pipeline_stage_id
                   WHERE d.id = c.disposition_id AND ps.convert_to_client = true
               ) as is_converted,
               EXTRACT(HOUR FROM c.started_at AT TIME ZONE 'UTC') as hour_of_day,
               EXTRACT(DOW FROM c.started_at AT TIME ZONE 'UTC') as dow,
               (c.started_at AT TIME ZONE 'UTC')::date as call_date
        FROM calls c
        WHERE c.organization_id = p_org_id
          AND c.started_at >= p_start_date
          AND c.started_at <= p_end_date
          AND (p_agent_id IS NULL OR c.agent_id = p_agent_id)
    ),
    by_hour AS (
        SELECT hour_of_day as hour,
               COUNT(*) as total,
               COUNT(*) FILTER (WHERE is_contacted) as contacted,
               COUNT(*) FILTER (WHERE is_converted) as converted
        FROM base_calls
        GROUP BY hour_of_day
    ),
    dow_names AS (
        SELECT 0 as dow, 'Sun' as dow_name UNION ALL
        SELECT 1, 'Mon' UNION ALL
        SELECT 2, 'Tue' UNION ALL
        SELECT 3, 'Wed' UNION ALL
        SELECT 4, 'Thu' UNION ALL
        SELECT 5, 'Fri' UNION ALL
        SELECT 6, 'Sat'
    ),
    by_dow AS (
        SELECT b.dow,
               n.dow_name,
               COUNT(*) as total,
               COUNT(*) FILTER (WHERE is_contacted) as contacted,
               COUNT(*) FILTER (WHERE is_converted) as converted
        FROM base_calls b
        JOIN dow_names n ON n.dow = b.dow
        GROUP BY b.dow, n.dow_name
    ),
    by_date AS (
        SELECT call_date::text as date,
               COUNT(*) as total,
               COUNT(*) FILTER (WHERE is_contacted) as contacted,
               COUNT(*) FILTER (WHERE is_converted) as converted
        FROM base_calls
        GROUP BY call_date
        ORDER BY call_date ASC
    ),
    heatmap AS (
        SELECT dow,
               hour_of_day as hour,
               COUNT(*) as total,
               COUNT(*) FILTER (WHERE is_contacted) as contacted
        FROM base_calls
        GROUP BY dow, hour_of_day
    )
    SELECT jsonb_build_object(
        'by_hour', COALESCE((SELECT jsonb_agg(row_to_json(h.*)) FROM by_hour h), '[]'::jsonb),
        'by_day_of_week', COALESCE((SELECT jsonb_agg(row_to_json(d.*)) FROM by_dow d), '[]'::jsonb),
        'by_date', COALESCE((SELECT jsonb_agg(row_to_json(dt.*)) FROM by_date dt), '[]'::jsonb),
        'heatmap', COALESCE((SELECT jsonb_agg(row_to_json(hm.*)) FROM heatmap hm), '[]'::jsonb)
    ) INTO v_result;

    RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."rpc_report_call_volume_timeseries"("p_org_id" "uuid", "p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone, "p_agent_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_report_campaign_performance"("p_org_id" "uuid", "p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone, "p_agent_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_result jsonb;
BEGIN
    WITH camp_stats AS (
        SELECT cmp.id as campaign_id,
               cmp.name as campaign_name,
               cmp.campaign_type as campaign_type,
               COUNT(DISTINCT cl.lead_id) as total_leads,
               COUNT(DISTINCT c.contact_id) FILTER (WHERE (c.duration > 45 OR EXISTS (SELECT 1 FROM dispositions d WHERE d.id = c.disposition_id AND d.dnc_auto_add = true))) as contacted,
               COUNT(DISTINCT c.contact_id) FILTER (WHERE EXISTS (SELECT 1 FROM dispositions d JOIN pipeline_stages ps ON ps.id = d.pipeline_stage_id WHERE d.id = c.disposition_id AND ps.convert_to_client = true)) as converted
        FROM campaigns cmp
        JOIN campaign_leads cl ON cl.campaign_id = cmp.id
        LEFT JOIN calls c ON c.campaign_id = cmp.id
            AND c.contact_id = cl.lead_id
            AND c.organization_id = p_org_id
            AND c.started_at >= p_start_date
            AND c.started_at <= p_end_date
            AND (p_agent_id IS NULL OR c.agent_id = p_agent_id)
        WHERE cmp.organization_id = p_org_id
        GROUP BY cmp.id, cmp.name, cmp.campaign_type
    ),
    ls_stats AS (
        SELECT l.lead_source,
               COUNT(DISTINCT l.id) as total,
               COUNT(DISTINCT c.contact_id) FILTER (WHERE (c.duration > 45 OR EXISTS (SELECT 1 FROM dispositions d WHERE d.id = c.disposition_id AND d.dnc_auto_add = true))) as contacted,
               COUNT(DISTINCT c.contact_id) FILTER (WHERE EXISTS (SELECT 1 FROM dispositions d JOIN pipeline_stages ps ON ps.id = d.pipeline_stage_id WHERE d.id = c.disposition_id AND ps.convert_to_client = true)) as converted
        FROM leads l
        LEFT JOIN calls c ON c.contact_id = l.id
            AND c.organization_id = p_org_id
            AND c.started_at >= p_start_date
            AND c.started_at <= p_end_date
            AND (p_agent_id IS NULL OR c.agent_id = p_agent_id)
        WHERE l.organization_id = p_org_id
          AND l.lead_source IS NOT NULL AND l.lead_source != ''
        GROUP BY l.lead_source
    )
    SELECT jsonb_build_object(
        'campaigns', COALESCE((SELECT jsonb_agg(jsonb_build_object(
            'campaign_id', c.campaign_id,
            'campaign_name', c.campaign_name,
            'campaign_type', c.campaign_type,
            'total_leads', c.total_leads,
            'contacted', c.contacted,
            'converted', c.converted,
            'conversion_rate_pct', CASE WHEN c.contacted > 0 THEN ROUND((c.converted::numeric / c.contacted::numeric) * 100, 2) ELSE 0 END
        )) FROM camp_stats c), '[]'::jsonb),
        'by_lead_source', COALESCE((SELECT jsonb_agg(jsonb_build_object(
            'lead_source', ls.lead_source,
            'total', ls.total,
            'contacted', ls.contacted,
            'converted', ls.converted,
            'conversion_rate_pct', CASE WHEN ls.contacted > 0 THEN ROUND((ls.converted::numeric / ls.contacted::numeric) * 100, 2) ELSE 0 END
        )) FROM ls_stats ls), '[]'::jsonb)
    ) INTO v_result;

    RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."rpc_report_campaign_performance"("p_org_id" "uuid", "p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone, "p_agent_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_report_disposition_breakdown"("p_org_id" "uuid", "p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone, "p_agent_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_result jsonb;
BEGIN
    WITH base_calls AS (
        SELECT c.id, c.agent_id, c.campaign_id, c.duration,
               COALESCE(d.name, '[No Disposition]') as disposition_name,
               COALESCE(d.color, '#6B7280') as color,
               COALESCE(ps.convert_to_client, false) as is_converted,
               CASE 
                   WHEN c.duration < 30 THEN '0-30s'
                   WHEN c.duration < 60 THEN '30s-1m'
                   WHEN c.duration < 120 THEN '1m-2m'
                   WHEN c.duration < 300 THEN '2m-5m'
                   ELSE '5m+'
               END as duration_range
        FROM calls c
        LEFT JOIN dispositions d ON d.id = c.disposition_id
        LEFT JOIN pipeline_stages ps ON ps.id = d.pipeline_stage_id
        WHERE c.organization_id = p_org_id
          AND c.started_at >= p_start_date
          AND c.started_at <= p_end_date
          AND (p_agent_id IS NULL OR c.agent_id = p_agent_id)
    ),
    by_disp AS (
        SELECT disposition_name,
               MAX(color) as color,
               COUNT(*) as count,
               COALESCE(AVG(duration), 0) as avg_duration,
               bool_or(is_converted) as is_converted
        FROM base_calls
        GROUP BY disposition_name
    ),
    by_agent AS (
        SELECT agent_id,
               jsonb_object_agg(disposition_name, count) as dispositions
        FROM (
            SELECT agent_id, disposition_name, COUNT(*) as count
            FROM base_calls
            WHERE agent_id IS NOT NULL
            GROUP BY agent_id, disposition_name
        ) a
        GROUP BY agent_id
    ),
    by_camp AS (
        SELECT bc.campaign_id,
               MAX(cmp.name) as campaign_name,
               jsonb_object_agg(bc.disposition_name, bc.count) as dispositions
        FROM (
            SELECT campaign_id, disposition_name, COUNT(*) as count
            FROM base_calls
            WHERE campaign_id IS NOT NULL
            GROUP BY campaign_id, disposition_name
        ) bc
        JOIN campaigns cmp ON cmp.id = bc.campaign_id
        GROUP BY bc.campaign_id
    ),
    dur_hist AS (
        SELECT duration_range as range,
               COUNT(*) as count
        FROM base_calls
        GROUP BY duration_range
    )
    SELECT jsonb_build_object(
        'by_disposition', COALESCE((SELECT jsonb_agg(row_to_json(d.*)) FROM by_disp d), '[]'::jsonb),
        'by_agent', COALESCE((SELECT jsonb_agg(row_to_json(a.*)) FROM by_agent a), '[]'::jsonb),
        'by_campaign', COALESCE((SELECT jsonb_agg(row_to_json(c.*)) FROM by_camp c), '[]'::jsonb),
        'duration_histogram', COALESCE((SELECT jsonb_agg(row_to_json(h.*)) FROM dur_hist h), '[]'::jsonb)
    ) INTO v_result;

    RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."rpc_report_disposition_breakdown"("p_org_id" "uuid", "p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone, "p_agent_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_contacts_clients"("p_filters" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  WITH f AS (SELECT * FROM public._contacts_filtered_clients(p_filters)),
  pg AS (
    SELECT f.id, f.ord FROM f
    ORDER BY f.ord
    LIMIT  COALESCE((p_filters->>'page_size')::int, 50)
    OFFSET COALESCE((p_filters->>'page')::int, 0) * COALESCE((p_filters->>'page_size')::int, 50)
  )
  SELECT jsonb_build_object(
    'total_count', (SELECT count(*) FROM f),
    'rows', COALESCE(
      (SELECT jsonb_agg(to_jsonb(c) ORDER BY pg.ord) FROM pg JOIN public.clients c ON c.id = pg.id),
      '[]'::jsonb
    )
  );
$$;


ALTER FUNCTION "public"."search_contacts_clients"("p_filters" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_contacts_leads"("p_filters" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  WITH f AS (
    SELECT * FROM public._contacts_filtered_leads(p_filters)
  ),
  pg AS (
    SELECT f.id, f.ord
    FROM f
    ORDER BY f.ord
    LIMIT  COALESCE((p_filters->>'page_size')::int, 50)
    OFFSET COALESCE((p_filters->>'page')::int, 0) * COALESCE((p_filters->>'page_size')::int, 50)
  )
  SELECT jsonb_build_object(
    'total_count', (SELECT count(*) FROM f),
    'rows', COALESCE(
      (
        SELECT jsonb_agg(
          to_jsonb(l)
          || jsonb_build_object(
               'attempt_count',
                 (
                   SELECT count(DISTINCT c.id)
                   FROM public.calls c
                   WHERE c.direction = 'outbound'
                     AND (
                       c.lead_id = l.id
                       OR (c.lead_id IS NULL AND c.contact_id = l.id AND (c.contact_type = 'lead' OR c.contact_type IS NULL))
                     )
                 ),
               'last_disposition',
                 (
                   SELECT NULLIF(btrim(c.disposition_name), '')
                   FROM public.calls c
                   WHERE (
                       c.lead_id = l.id
                       OR (c.lead_id IS NULL AND c.contact_id = l.id AND (c.contact_type = 'lead' OR c.contact_type IS NULL))
                     )
                     AND (c.disposition_id IS NOT NULL OR btrim(coalesce(c.disposition_name, '')) <> '')
                   ORDER BY c.created_at DESC NULLS LAST, c.id DESC
                   LIMIT 1
                 )
             )
          ORDER BY pg.ord
        )
        FROM pg
        JOIN public.leads l ON l.id = pg.id
      ),
      '[]'::jsonb
    )
  );
$$;


ALTER FUNCTION "public"."search_contacts_leads"("p_filters" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_contacts_recruits"("p_filters" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  WITH f AS (SELECT * FROM public._contacts_filtered_recruits(p_filters)),
  pg AS (
    SELECT f.id, f.ord FROM f
    ORDER BY f.ord
    LIMIT  COALESCE((p_filters->>'page_size')::int, 50)
    OFFSET COALESCE((p_filters->>'page')::int, 0) * COALESCE((p_filters->>'page_size')::int, 50)
  )
  SELECT jsonb_build_object(
    'total_count', (SELECT count(*) FROM f),
    'rows', COALESCE(
      (SELECT jsonb_agg(to_jsonb(r) ORDER BY pg.ord) FROM pg JOIN public.recruits r ON r.id = pg.id),
      '[]'::jsonb
    )
  );
$$;


ALTER FUNCTION "public"."search_contacts_recruits"("p_filters" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."seed_default_appointment_types"("p_organization_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  INSERT INTO public.appointment_types (organization_id, name, color, duration_minutes, sort_order, is_default, is_locked, is_active)
  SELECT p_organization_id, 'Sales Call', '#3B82F6', 30, 10, true, true, true
  WHERE NOT EXISTS (SELECT 1 FROM public.appointment_types WHERE organization_id = p_organization_id AND lower(name) = lower('Sales Call') AND is_active = true);

  INSERT INTO public.appointment_types (organization_id, name, color, duration_minutes, sort_order, is_default, is_locked, is_active)
  SELECT p_organization_id, 'Follow Up', '#F97316', 20, 20, true, true, true
  WHERE NOT EXISTS (SELECT 1 FROM public.appointment_types WHERE organization_id = p_organization_id AND lower(name) = lower('Follow Up') AND is_active = true);

  INSERT INTO public.appointment_types (organization_id, name, color, duration_minutes, sort_order, is_default, is_locked, is_active)
  SELECT p_organization_id, 'Recruit Interview', '#A855F7', 45, 30, true, true, true
  WHERE NOT EXISTS (SELECT 1 FROM public.appointment_types WHERE organization_id = p_organization_id AND lower(name) = lower('Recruit Interview') AND is_active = true);

  INSERT INTO public.appointment_types (organization_id, name, color, duration_minutes, sort_order, is_default, is_locked, is_active)
  SELECT p_organization_id, 'Policy Review', '#22C55E', 60, 40, true, true, true
  WHERE NOT EXISTS (SELECT 1 FROM public.appointment_types WHERE organization_id = p_organization_id AND lower(name) = lower('Policy Review') AND is_active = true);

  INSERT INTO public.appointment_types (organization_id, name, color, duration_minutes, sort_order, is_default, is_locked, is_active)
  SELECT p_organization_id, 'Policy Anniversary', '#EC4899', 60, 50, true, true, true
  WHERE NOT EXISTS (SELECT 1 FROM public.appointment_types WHERE organization_id = p_organization_id AND lower(name) = lower('Policy Anniversary') AND is_active = true);

  INSERT INTO public.appointment_types (organization_id, name, color, duration_minutes, sort_order, is_default, is_locked, is_active)
  SELECT p_organization_id, 'Other', '#64748B', 30, 60, true, true, true
  WHERE NOT EXISTS (SELECT 1 FROM public.appointment_types WHERE organization_id = p_organization_id AND lower(name) = lower('Other') AND is_active = true);
END;
$$;


ALTER FUNCTION "public"."seed_default_appointment_types"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."seed_default_lead_sources"("p_organization_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'seed_default_lead_sources: organization_id required';
  END IF;
  INSERT INTO public.lead_sources (organization_id, name, color, active, sort_order)
  SELECT p_organization_id, d.name, d.color, true, d.sort_order
  FROM (VALUES
    ('Final Expense (Direct Mail)', '#3B82F6', 0),
    ('Mortgage Protection',         '#10B981', 1),
    ('Aged Leads',                  '#F59E0B', 2),
    ('Live Transfer',               '#8B5CF6', 3),
    ('Referral',                    '#22C55E', 4),
    ('Facebook / Social',           '#EC4899', 5),
    ('Existing Client',             '#14B8A6', 6),
    ('Other',                       '#64748B', 7)
  ) AS d(name, color, sort_order)
  WHERE NOT EXISTS (
    SELECT 1 FROM public.lead_sources ls
    WHERE ls.organization_id = p_organization_id
      AND lower(btrim(ls.name)) = lower(btrim(d.name))
  );
END
$$;


ALTER FUNCTION "public"."seed_default_lead_sources"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."seed_default_pipeline_stages"("p_organization_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  INSERT INTO public.pipeline_stages
