CREATE OR REPLACE FUNCTION "public"."set_claim"("uid" "uuid", "claim" "text", "value" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  UPDATE auth.users
  SET raw_app_meta_data = 
    coalesce(raw_app_meta_data, '{}'::jsonb) || 
    jsonb_build_object(claim, value)
  WHERE id = uid;
  RETURN 'OK';
END;
$$;


ALTER FUNCTION "public"."set_claim"("uid" "uuid", "claim" "text", "value" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_twilio_subaccount_token"("p_org_id" "uuid", "p_token" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'vault', 'pg_temp'
    AS $$
DECLARE
  v_name text := 'twilio_subaccount_token_' || p_org_id::text;
  v_existing uuid;
BEGIN
  IF p_org_id IS NULL OR p_token IS NULL OR length(p_token) = 0 THEN
    RAISE EXCEPTION 'set_twilio_subaccount_token: org id and token are required';
  END IF;

  SELECT id INTO v_existing FROM vault.secrets WHERE name = v_name LIMIT 1;

  IF v_existing IS NULL THEN
    PERFORM vault.create_secret(p_token, v_name, 'Twilio subaccount auth token for organization ' || p_org_id::text);
  ELSE
    PERFORM vault.update_secret(v_existing, p_token, v_name, 'Twilio subaccount auth token for organization ' || p_org_id::text);
  END IF;

  RETURN v_name;
END;
$$;


ALTER FUNCTION "public"."set_twilio_subaccount_token"("p_org_id" "uuid", "p_token" "text") OWNER TO "postgres";


