CREATE OR REPLACE FUNCTION "public"."start_dialer_session"("p_campaign_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
  v_org uuid;
  v_agent uuid;
  v_session public.dialer_sessions%ROWTYPE;
BEGIN
  v_org := public.get_org_id();
  v_agent := auth.uid();

  IF v_org IS NULL THEN
    RAISE EXCEPTION 'organization context required';
  END IF;

  IF v_agent IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;

  PERFORM private.close_stale_dialer_sessions(v_org, v_agent, 3);

  SELECT *
  INTO v_session
  FROM public.dialer_sessions
  WHERE organization_id = v_org
    AND agent_id = v_agent
    AND status = 'active'
  ORDER BY started_at DESC
  LIMIT 1;

  IF FOUND THEN
    RETURN jsonb_build_object(
      'id', v_session.id,
      'organization_id', v_session.organization_id,
      'agent_id', v_session.agent_id,
      'campaign_id', v_session.campaign_id,
      'started_at', v_session.started_at,
      'last_heartbeat_at', v_session.last_heartbeat_at,
      'ended_at', v_session.ended_at,
      'status', v_session.status
    );
  END IF;

  INSERT INTO public.dialer_sessions (
    organization_id,
    agent_id,
    campaign_id,
    started_at,
    last_heartbeat_at,
    status
  )
  VALUES (
    v_org,
    v_agent,
    p_campaign_id,
    now(),
    now(),
    'active'
  )
  RETURNING * INTO v_session;

  RETURN jsonb_build_object(
    'id', v_session.id,
    'organization_id', v_session.organization_id,
    'agent_id', v_session.agent_id,
    'campaign_id', v_session.campaign_id,
    'started_at', v_session.started_at,
    'last_heartbeat_at', v_session.last_heartbeat_at,
    'ended_at', v_session.ended_at,
    'status', v_session.status
  );
END;
$$;


ALTER FUNCTION "public"."start_dialer_session"("p_campaign_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."storage_agency_group_resource_member_ok"("p_object_name" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_group_id uuid;
BEGIN
  IF p_object_name IS NULL OR btrim(p_object_name) = '' THEN
    RETURN false;
  END IF;

  BEGIN
    v_group_id := split_part(p_object_name, '/', 1)::uuid;
  EXCEPTION
    WHEN invalid_text_representation THEN
      RETURN false;
  END;

  RETURN public.is_org_member_of_agency_group(v_group_id, ARRAY['active']::text[]);
END;
$$;


ALTER FUNCTION "public"."storage_agency_group_resource_member_ok"("p_object_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."super_admin_all_users"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v jsonb;
BEGIN
  IF NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT jsonb_agg(
    jsonb_build_object(
      'id', p.id,
      'first_name', p.first_name,
      'last_name', p.last_name,
      'email', p.email,
      'role', p.role,
      'status', p.status,
      'organization_id', p.organization_id,
      'organization_name', o.name,
      'agency_display_name', COALESCE(NULLIF(trim(cs.company_name), ''), NULLIF(trim(o.name::text), ''), 'Agency'),
      'created_at', p.created_at
    )
    ORDER BY p.created_at DESC
  )
  INTO v
  FROM public.profiles p
  LEFT JOIN public.organizations o ON p.organization_id = o.id
  LEFT JOIN public.company_settings cs ON cs.organization_id = o.id;

  RETURN COALESCE(v, '[]'::jsonb);
END;
$$;


ALTER FUNCTION "public"."super_admin_all_users"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."super_admin_all_users"() IS 'Super admin only — list all users across all organizations for platform management.';



CREATE OR REPLACE FUNCTION "public"."super_admin_dashboard_snapshot"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v jsonb;
BEGIN
  IF NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT jsonb_build_object(
    'organizations',
    COALESCE(
      (
        SELECT jsonb_agg(
          jsonb_build_object(
            'id', sq.id,
            'name', sq.name,
            'slug', sq.slug,
            'logo_url', sq.logo_url,
            'created_at', sq.created_at,
            'status', COALESCE(sq.status::text, 'active'),
            'display_name', sq.display_name,
            'user_count', sq.user_count,
            'lead_count', sq.lead_count,
            'twilio_subaccount_sid', sq.twilio_subaccount_sid,
            'twilio_subaccount_status', sq.twilio_subaccount_status,
            'twilio_provisioned_at', sq.twilio_provisioned_at
          )
          ORDER BY sq.created_at DESC NULLS LAST
        )
        FROM (
          SELECT
            o.id,
            o.name,
            o.slug,
            o.logo_url,
            o.created_at,
            o.status,
            COALESCE(NULLIF(trim(cs.company_name), ''), NULLIF(trim(o.name::text), ''), 'Agency') AS display_name,
            (SELECT count(*)::int FROM public.profiles p WHERE p.organization_id = o.id) AS user_count,
            (SELECT count(*)::int FROM public.leads l WHERE l.organization_id = o.id) AS lead_count,
            o.twilio_subaccount_sid,
            o.twilio_subaccount_status,
            o.twilio_provisioned_at
          FROM public.organizations o
          LEFT JOIN public.company_settings cs ON cs.organization_id = o.id
        ) sq
      ),
      '[]'::jsonb
    ),
    'total_users', (SELECT count(*)::int FROM public.profiles),
    'total_leads', (SELECT count(*)::int FROM public.leads),
    'active_calls', (
      SELECT count(*)::int
      FROM public.calls c
      WHERE c.status = 'in-progress'
    )
  )
  INTO v;

  RETURN v;
END;
$$;


ALTER FUNCTION "public"."super_admin_dashboard_snapshot"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."super_admin_organization_detail"("p_organization_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org json;
  v_company text;
BEGIN
  IF NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_organization_id IS NULL THEN
    RETURN NULL::jsonb;
  END IF;

  SELECT row_to_json(o)::json INTO v_org
  FROM public.organizations o
  WHERE o.id = p_organization_id;

  IF v_org IS NULL THEN
    RETURN NULL::jsonb;
  END IF;

  SELECT trim(cs.company_name) INTO v_company
  FROM public.company_settings cs
  WHERE cs.organization_id = p_organization_id
  LIMIT 1;

  RETURN jsonb_build_object(
    'organization', to_jsonb(v_org),
    'agency_display_name', COALESCE(NULLIF(v_company, ''), v_org ->> 'name'),
    'stats', jsonb_build_object(
      'total_users',
        (SELECT count(*) FROM public.profiles p WHERE p.organization_id = p_organization_id),
      'total_leads',
        (SELECT count(*) FROM public.leads l WHERE l.organization_id = p_organization_id),
      'total_clients',
        (SELECT count(*) FROM public.clients c WHERE c.organization_id = p_organization_id),
      'total_campaigns',
        (SELECT count(*) FROM public.campaigns c WHERE c.organization_id = p_organization_id),
      'total_calls',
        (SELECT count(*) FROM public.calls c WHERE c.organization_id = p_organization_id),
      'total_appointments',
        (SELECT count(*) FROM public.appointments a WHERE a.organization_id = p_organization_id)
    ),
    'profiles',
      COALESCE(
        (
          SELECT jsonb_agg(to_jsonb(p) ORDER BY p.created_at DESC NULLS LAST)
          FROM (
            SELECT *
            FROM public.profiles pr
            WHERE pr.organization_id = p_organization_id
            ORDER BY pr.created_at DESC
            LIMIT 5000
          ) p
        ),
        '[]'::jsonb
      )
  );
END;
$$;


ALTER FUNCTION "public"."super_admin_organization_detail"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."super_admin_own_org"("row_org" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT CASE
    WHEN row_org IS NULL THEN false
    WHEN NOT public.is_super_admin() THEN false
    WHEN public.get_org_id() IS NULL THEN false
    ELSE row_org = public.get_org_id()
  END;
$$;


ALTER FUNCTION "public"."super_admin_own_org"("row_org" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."super_admin_own_org"("row_org" "uuid") IS 'True when JWT super admin''s organization_id equals the row org (tenant scope).';



CREATE OR REPLACE FUNCTION "public"."super_admin_update_organization_status"("p_organization_id" "uuid", "p_status" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'Missing organization id' USING ERRCODE = '23502';
  END IF;
  IF p_status IS NULL OR lower(p_status) NOT IN ('active', 'suspended', 'archived') THEN
    RAISE EXCEPTION 'invalid status' USING ERRCODE = '22023';
  END IF;

  UPDATE public.organizations
  SET status = lower(p_status)
  WHERE id = p_organization_id;
END;
$$;


ALTER FUNCTION "public"."super_admin_update_organization_status"("p_organization_id" "uuid", "p_status" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."super_admin_update_organization_status"("p_organization_id" "uuid", "p_status" "text") IS 'Super admin only — update organizations.status across tenants (Agencies UI).';



CREATE OR REPLACE FUNCTION "public"."super_admin_update_user"("p_user_id" "uuid", "p_role" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Forbidden' USING ERRCODE = '42501';
  END IF;

  UPDATE public.profiles
  SET
    role = COALESCE(p_role, role),
    status = COALESCE(p_status, status),
    updated_at = now()
  WHERE id = p_user_id;
END;
$$;


