CREATE OR REPLACE FUNCTION "public"."sync_campaign_leads_called"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF COALESCE(NEW.call_attempts, 0) > 0 THEN
      UPDATE public.campaigns
      SET leads_called = leads_called + 1
      WHERE id = NEW.campaign_id;
    END IF;
    RETURN NEW;
  ELSIF TG_OP = 'UPDATE' THEN
    IF COALESCE(OLD.call_attempts, 0) = 0 AND COALESCE(NEW.call_attempts, 0) > 0 THEN
      UPDATE public.campaigns
      SET leads_called = leads_called + 1
      WHERE id = NEW.campaign_id;
    ELSIF COALESCE(OLD.call_attempts, 0) > 0 AND COALESCE(NEW.call_attempts, 0) = 0 THEN
      UPDATE public.campaigns
      SET leads_called = GREATEST(leads_called - 1, 0)
      WHERE id = NEW.campaign_id;
    ELSIF COALESCE(OLD.call_attempts, 0) > 0
      AND COALESCE(NEW.call_attempts, 0) > 0
      AND NEW.campaign_id IS DISTINCT FROM OLD.campaign_id THEN
      UPDATE public.campaigns
      SET leads_called = GREATEST(leads_called - 1, 0)
      WHERE id = OLD.campaign_id;
      UPDATE public.campaigns
      SET leads_called = leads_called + 1
      WHERE id = NEW.campaign_id;
    END IF;
    RETURN NEW;
  ELSIF TG_OP = 'DELETE' THEN
    IF COALESCE(OLD.call_attempts, 0) > 0 THEN
      UPDATE public.campaigns
      SET leads_called = GREATEST(leads_called - 1, 0)
      WHERE id = OLD.campaign_id;
    END IF;
    RETURN OLD;
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."sync_campaign_leads_called"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_campaign_total_leads"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    UPDATE public.campaigns
    SET total_leads = total_leads + 1
    WHERE id = NEW.campaign_id;
    RETURN NEW;

  ELSIF TG_OP = 'DELETE' THEN
    UPDATE public.campaigns
    SET total_leads = GREATEST(total_leads - 1, 0)
    WHERE id = OLD.campaign_id;
    RETURN OLD;

  ELSIF TG_OP = 'UPDATE' THEN
    IF OLD.campaign_id IS DISTINCT FROM NEW.campaign_id THEN
      UPDATE public.campaigns
      SET total_leads = GREATEST(total_leads - 1, 0)
      WHERE id = OLD.campaign_id;

      UPDATE public.campaigns
      SET total_leads = total_leads + 1
      WHERE id = NEW.campaign_id;
    END IF;
    RETURN NEW;
  END IF;

  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."sync_campaign_total_leads"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_last_login_at"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  -- Only run if last_sign_in_at actually changed
  IF NEW.last_sign_in_at IS DISTINCT FROM OLD.last_sign_in_at THEN
    UPDATE public.profiles
    SET last_login_at = NEW.last_sign_in_at,
        updated_at = NOW()
    WHERE id = NEW.id;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_last_login_at"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_leads_user_id"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Keep user_id in sync with assigned_agent_id so RLS (user_id = auth.uid()) is
  -- never stale after a reassignment.
  IF NEW.assigned_agent_id IS NOT NULL THEN
    NEW.user_id := NEW.assigned_agent_id;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_leads_user_id"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."undo_contact_import"("p_import_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  c            RECORD;
  v_lock       uuid;
  v_codes      text[];
  v_del_camp   int := 0;
  v_del_leads  int := 0;
BEGIN
  SELECT id INTO v_lock FROM public.import_history WHERE id = p_import_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'reason', 'not_found');
  END IF;

  SELECT * INTO c FROM public._import_undo_context(p_import_id);
  IF c.reason IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'reason', c.reason);
  END IF;
  IF c.already_undone THEN
    RETURN jsonb_build_object('success', false, 'reason', 'already_undone');
  END IF;
  IF c.expired THEN
    RETURN jsonb_build_object('success', false, 'reason', 'expired');
  END IF;

  v_codes := public._import_undo_blockers(p_import_id, c.org_id, c.validated_ids);
  IF array_length(v_codes, 1) IS NOT NULL THEN
    SELECT COALESCE(array_agg(DISTINCT x), ARRAY[]::text[]) INTO v_codes FROM unnest(v_codes) x;
    RETURN jsonb_build_object('success', false, 'reason', 'ineligible', 'blocked_reason_codes', to_jsonb(v_codes));
  END IF;

  DELETE FROM public.campaign_leads
   WHERE import_history_id = p_import_id;
  GET DIAGNOSTICS v_del_camp = ROW_COUNT;

  DELETE FROM public.leads
   WHERE id = ANY(c.validated_ids) AND organization_id = c.org_id;
  GET DIAGNOSTICS v_del_leads = ROW_COUNT;

  UPDATE public.import_history
     SET undo_status        = 'undone',
         undone_at          = now(),
         undone_by          = auth.uid(),
         undo_deleted_count = v_del_leads,
         undo_metadata      = jsonb_build_object(
                                'deleted_leads', v_del_leads,
                                'deleted_campaign_rows', v_del_camp,
                                'imported_count', c.imported_count)
   WHERE id = p_import_id;

  RETURN jsonb_build_object(
    'success', true,
    'deleted_leads', v_del_leads,
    'deleted_campaign_rows', v_del_camp,
    'undo_status', 'undone'
  );
END;
$$;


ALTER FUNCTION "public"."undo_contact_import"("p_import_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."campaigns" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "name" "text" NOT NULL,
    "type" "text" DEFAULT 'Personal'::"text" NOT NULL,
    "status" "text" DEFAULT 'Draft'::"text" NOT NULL,
    "description" "text" DEFAULT ''::"text",
    "assigned_agent_ids" "jsonb" DEFAULT '[]'::"jsonb",
    "created_by" "uuid",
    "total_leads" integer DEFAULT 0,
    "leads_contacted" integer DEFAULT 0,
    "leads_converted" integer DEFAULT 0,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "tags" "jsonb" DEFAULT '[]'::"jsonb",
    "auto_dial_enabled" boolean DEFAULT true,
    "local_presence_enabled" boolean DEFAULT true,
    "max_attempts" integer,
    "calling_hours_start" time without time zone DEFAULT '08:00:00'::time without time zone,
    "calling_hours_end" time without time zone DEFAULT '21:00:00'::time without time zone,
    "retry_interval_hours" integer DEFAULT 24,
    "organization_id" "uuid",
    "user_id" "uuid" DEFAULT "auth"."uid"(),
    "ring_timeout_seconds" integer,
    "leads_called" integer DEFAULT 0 NOT NULL,
    "number_group_id" "uuid",
    "queue_filters" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "retry_interval_minutes" integer DEFAULT 1440 NOT NULL,
    "settings_edit_policy" "text" DEFAULT 'creator_and_admins'::"text" NOT NULL,
    "require_licensed_state_access" boolean DEFAULT false NOT NULL,
    CONSTRAINT "campaigns_settings_edit_policy_check" CHECK (("settings_edit_policy" = ANY (ARRAY['creator_and_admins'::"text", 'admins_only'::"text", 'team_leaders'::"text", 'specific_users'::"text"]))),
    CONSTRAINT "campaigns_status_check" CHECK (("status" = ANY (ARRAY['Draft'::"text", 'Active'::"text", 'Paused'::"text", 'Completed'::"text", 'Archived'::"text"]))),
    CONSTRAINT "campaigns_type_check" CHECK (("type" = ANY (ARRAY['Open Pool'::"text", 'Personal'::"text", 'Team'::"text"])))
);


ALTER TABLE "public"."campaigns" OWNER TO "postgres";


COMMENT ON COLUMN "public"."campaigns"."auto_dial_enabled" IS 'Whether auto-dial is enabled for this campaign when loaded in the Dialer.';



COMMENT ON COLUMN "public"."campaigns"."local_presence_enabled" IS 'Whether local presence (area code matching) is used for this campaign.';



COMMENT ON COLUMN "public"."campaigns"."max_attempts" IS 'NULL = unlimited attempts. A number = max call attempts before lead is marked exhausted.';



COMMENT ON COLUMN "public"."campaigns"."calling_hours_start" IS 'Start of allowed calling window (agent local time).';



COMMENT ON COLUMN "public"."campaigns"."calling_hours_end" IS 'End of allowed calling window (agent local time).';



COMMENT ON COLUMN "public"."campaigns"."retry_interval_hours" IS 'Minimum hours between retry attempts on the same lead.';



COMMENT ON COLUMN "public"."campaigns"."ring_timeout_seconds" IS 'Outbound ring timeout for this campaign (seconds). NULL falls back to phone_settings.ring_timeout.';



COMMENT ON COLUMN "public"."campaigns"."number_group_id" IS 'The number group (pool of phone numbers) used for outbound dialing on this campaign. When NULL, the dialer uses all active non-direct-line org numbers.';



COMMENT ON COLUMN "public"."campaigns"."settings_edit_policy" IS 'Who may edit this campaign''s calling settings. creator_and_admins (default) | admins_only | team_leaders | specific_users. Enforced by trg_enforce_campaign_settings_edit + update_campaign_settings().';



CREATE OR REPLACE FUNCTION "public"."update_campaign_settings"("p_campaign_id" "uuid", "p_max_attempts" integer, "p_calling_hours_start" time without time zone, "p_calling_hours_end" time without time zone, "p_retry_interval_hours" integer, "p_retry_interval_minutes" integer, "p_ring_timeout_seconds" integer, "p_auto_dial_enabled" boolean, "p_local_presence_enabled" boolean, "p_settings_edit_policy" "text", "p_require_licensed_state_access" boolean) RETURNS "public"."campaigns"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_row public.campaigns;
BEGIN
  IF NOT public.can_edit_campaign_settings(p_campaign_id) THEN
    RAISE EXCEPTION 'You don''t have permission to edit this campaign''s settings.'
      USING ERRCODE = '42501';
  END IF;

  IF p_settings_edit_policy IS NOT NULL
     AND p_settings_edit_policy NOT IN ('creator_and_admins', 'admins_only', 'team_leaders', 'specific_users') THEN
    RAISE EXCEPTION 'Invalid settings_edit_policy: %', p_settings_edit_policy
      USING ERRCODE = '22023';
  END IF;

  UPDATE public.campaigns
  SET max_attempts                 = p_max_attempts,
      calling_hours_start          = p_calling_hours_start,
      calling_hours_end            = p_calling_hours_end,
      retry_interval_hours         = p_retry_interval_hours,
      retry_interval_minutes       = COALESCE(p_retry_interval_minutes, retry_interval_minutes),
      ring_timeout_seconds         = p_ring_timeout_seconds,
      auto_dial_enabled            = p_auto_dial_enabled,
      local_presence_enabled       = p_local_presence_enabled,
      settings_edit_policy         = COALESCE(p_settings_edit_policy, settings_edit_policy),
      require_licensed_state_access = COALESCE(p_require_licensed_state_access, require_licensed_state_access)
  WHERE id = p_campaign_id
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."update_campaign_settings"("p_campaign_id" "uuid", "p_max_attempts" integer, "p_calling_hours_start" time without time zone, "p_calling_hours_end" time without time zone, "p_retry_interval_hours" integer, "p_retry_interval_minutes" integer, "p_ring_timeout_seconds" integer, "p_auto_dial_enabled" boolean, "p_local_presence_enabled" boolean, "p_settings_edit_policy" "text", "p_require_licensed_state_access" boolean) OWNER TO "postgres";


