CREATE OR REPLACE FUNCTION "public"."workflow_dispatch_event"("p_org_id" "uuid", "p_trigger_type" "text", "p_trigger_key" "text", "p_contact_id" "uuid", "p_contact_type" "text", "p_metadata" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private', 'pg_temp'
    AS $$
BEGIN
  BEGIN
    PERFORM private.workflow_dispatch_event(
      p_org_id, p_trigger_type, p_trigger_key, p_contact_id, p_contact_type, p_metadata
    );
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'workflow_dispatch_event wrapper failed (% / %): %',
      p_trigger_type, p_contact_id, SQLERRM;
  END;
END;
$$;


ALTER FUNCTION "public"."workflow_dispatch_event"("p_org_id" "uuid", "p_trigger_type" "text", "p_trigger_key" "text", "p_contact_id" "uuid", "p_contact_type" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."workflow_on_call_created"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  BEGIN
    IF NEW.disposition_id IS NOT NULL AND NEW.contact_id IS NOT NULL THEN
      PERFORM private.workflow_dispatch_event(
        NEW.organization_id,
        'disposition',
        NEW.disposition_id::text,
        NEW.contact_id,
        'lead',
        jsonb_build_object('disposition_id', NEW.disposition_id)
      );
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'workflow_on_call_created dispatch failed (call %): %', NEW.id, SQLERRM;
  END;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."workflow_on_call_created"() OWNER TO "postgres";


