      NEW.organization_id,
      'lead_created',
      NULL,
      NEW.id,
      'lead',
      jsonb_build_object('source', NEW.lead_source)
    );
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'workflow_on_lead_created dispatch failed (lead %): %', NEW.id, SQLERRM;
  END;
