CREATE TABLE IF NOT EXISTS "public"."ai_test_sessions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "created_by" "uuid",
    "stack" "text" NOT NULL,
    "prompt" "text" NOT NULL,
    "to_number" "text",
    "from_number" "text",
    "twilio_call_sid" "text",
    "status" "text" DEFAULT 'queued'::"text" NOT NULL,
    "transcript" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "error_message" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "lead_context" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "debug_log" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "voice_id" "text",
    "temperature" numeric(3,2) DEFAULT 0.7,
    "speaking_rate" numeric(3,2) DEFAULT 1.0,
    "interruption_sensitivity" "text" DEFAULT 'medium'::"text",
    "model_id" "text",
    "bridge_token" "text",
    "usage_metrics" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "tunables" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "transport" "text" DEFAULT 'phone'::"text" NOT NULL,
    CONSTRAINT "ai_test_sessions_interruption_sensitivity_check" CHECK (("interruption_sensitivity" = ANY (ARRAY['low'::"text", 'medium'::"text", 'high'::"text"]))),
    CONSTRAINT "ai_test_sessions_stack_check" CHECK (("stack" = ANY (ARRAY['twilio_cr'::"text", 'xai_s2s'::"text", 'openai_realtime'::"text", 'openai_sip'::"text", 'deepgram_voice_agent'::"text", 'hypercheap_voice_agent'::"text", 'pipeline_voice_agent'::"text", 'inworld_realtime_agent'::"text"]))),
    CONSTRAINT "ai_test_sessions_status_check" CHECK (("status" = ANY (ARRAY['queued'::"text", 'ringing'::"text", 'in-progress'::"text", 'completed'::"text", 'failed'::"text", 'busy'::"text", 'no-answer'::"text", 'canceled'::"text"]))),
    CONSTRAINT "ai_test_sessions_transport_check" CHECK (("transport" = ANY (ARRAY['phone'::"text", 'browser'::"text"])))
);


ALTER TABLE "public"."ai_test_sessions" OWNER TO "postgres";


COMMENT ON TABLE "public"."ai_test_sessions" IS 'POC AI voice lab sessions; isolated from production calls CRM.';



COMMENT ON COLUMN "public"."ai_test_sessions"."stack" IS 'Voice stack: twilio_cr | xai_s2s | openai_realtime | openai_sip | deepgram_voice_agent | hypercheap_voice_agent | pipeline_voice_agent | inworld_realtime_agent';



COMMENT ON COLUMN "public"."ai_test_sessions"."debug_log" IS 'Append-only bridge lifecycle log written by ai-testing-* Edge Functions: [{at, level, event, data}]';



COMMENT ON COLUMN "public"."ai_test_sessions"."voice_id" IS 'Provider-specific voice id (ElevenLabs voice name for Stack A, OpenAI/xAI voice name for B/C).';



COMMENT ON COLUMN "public"."ai_test_sessions"."bridge_token" IS 'Single-use token for Render Media Stream auth (Twilio Parameter bridgeToken). Not exposed in Stream URL.';



COMMENT ON COLUMN "public"."ai_test_sessions"."usage_metrics" IS 'Measured usage for cost estimates: Twilio durations, media packet counts, Deepgram WS seconds, OpenAI tokens.';



COMMENT ON COLUMN "public"."ai_test_sessions"."tunables" IS 'Per-stack extra tunables (jsonb). hypercheap: max_response_tokens, vad_aggressiveness. pipeline: max_response_tokens. inworld_realtime_agent: tts_model, max_response_tokens, turn_detection_type.';



COMMENT ON COLUMN "public"."ai_test_sessions"."transport" IS 'How the test audio is carried: phone (Twilio Media Streams) | browser (mic/speakers over WebSocket to ai-voice-bridge /browser/*).';



