CREATE TABLE IF NOT EXISTS "public"."phone_numbers" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "phone_number" "text" NOT NULL,
    "friendly_name" "text",
    "status" "text" DEFAULT 'active'::"text",
    "assigned_to" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "is_default" boolean DEFAULT false,
    "area_code" "text" DEFAULT ''::"text",
    "spam_status" "text" DEFAULT 'Unknown'::"text",
    "spam_score" integer DEFAULT 0,
    "spam_checked_at" timestamp with time zone,
    "daily_call_count" integer DEFAULT 0,
    "daily_call_limit" integer DEFAULT 100,
    "limit_reset_at" timestamp with time zone DEFAULT (CURRENT_DATE + '1 day'::interval),
    "attestation_level" "text",
    "carrier_reputation_data" "jsonb",
    "total_calls_7d" integer DEFAULT 0 NOT NULL,
    "rejected_calls_7d" integer DEFAULT 0 NOT NULL,
    "rejection_rate_7d" numeric(5,2) DEFAULT 0 NOT NULL,
    "total_calls_30d" integer DEFAULT 0 NOT NULL,
    "rejected_calls_30d" integer DEFAULT 0 NOT NULL,
    "rejection_rate_30d" numeric(5,2) DEFAULT 0 NOT NULL,
    "last_rejection_at" timestamp with time zone,
    "shaken_stir_a_count" integer DEFAULT 0 NOT NULL,
    "shaken_stir_unavailable_count" integer DEFAULT 0 NOT NULL,
    "shaken_stir_rate" numeric(5,2) DEFAULT 0 NOT NULL,
    "avg_quality_percentage" numeric(6,2),
    "avg_mos" numeric(6,4),
    "d51_count" integer DEFAULT 0 NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "twilio_sid" "text",
    "trust_hub_status" "text" DEFAULT 'pending'::"text",
    "shaken_stir_attestation" "text",
    "inbound_routing_mode" "text",
    "voicemail_enabled" boolean,
    "fallback_action" "text",
    "voicemail_greeting_text" "text",
    "forwarding_number" "text",
    "is_direct_line" boolean DEFAULT false NOT NULL,
    "voicemail_greeting_url" "text",
    "assignment_type" "text" DEFAULT 'agency'::"text" NOT NULL,
    CONSTRAINT "phone_numbers_assignment_type_check" CHECK (("assignment_type" = ANY (ARRAY['agency'::"text", 'personal'::"text"]))),
    CONSTRAINT "phone_numbers_personal_not_default_check" CHECK ((("assignment_type" <> 'personal'::"text") OR (COALESCE("is_default", false) = false))),
    CONSTRAINT "phone_numbers_personal_requires_owner_check" CHECK ((("assignment_type" <> 'personal'::"text") OR ("assigned_to" IS NOT NULL))),
    CONSTRAINT "phone_numbers_spam_status_check" CHECK ((("spam_status" IS NULL) OR ("regexp_replace"("lower"(TRIM(BOTH FROM "spam_status")), '\s+'::"text", '_'::"text", 'g'::"text") = ANY (ARRAY['unknown'::"text", 'checking'::"text", 'clean'::"text", 'at_risk'::"text", 'flagged'::"text", 'insufficient_data'::"text", 'evaluating'::"text"])))),
    CONSTRAINT "phone_numbers_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'released'::"text", 'spam'::"text"])))
);


ALTER TABLE "public"."phone_numbers" OWNER TO "postgres";


COMMENT ON COLUMN "public"."phone_numbers"."attestation_level" IS 'STIR/SHAKEN attestation level from Telnyx: A (Full), B (Partial), C (Gateway), or NULL (no attestation)';



COMMENT ON COLUMN "public"."phone_numbers"."carrier_reputation_data" IS 'Carrier-specific reputation data from Telnyx: blocking rates, spam labels, completion rates, etc. Structure: {"at&t": {"blocking_rate": 0.05, "label": "Scam Likely"}, "verizon": {...}}';



COMMENT ON COLUMN "public"."phone_numbers"."inbound_routing_mode" IS 'Override for organization-wide routing mode (e.g., assigned, all-ring)';



COMMENT ON COLUMN "public"."phone_numbers"."fallback_action" IS 'Override for organization-wide fallback action (e.g., voicemail, forward, hangup)';



COMMENT ON COLUMN "public"."phone_numbers"."voicemail_greeting_text" IS 'Override for organization-wide voicemail greeting text';



COMMENT ON COLUMN "public"."phone_numbers"."forwarding_number" IS 'Override for organization-wide external forwarding number';



COMMENT ON COLUMN "public"."phone_numbers"."is_direct_line" IS 'When true, this number is an agent''s personal direct line. It is excluded from all number group pools and the dialer never uses it for outbound. Inbound calls ring only the assigned_to agent.';



COMMENT ON COLUMN "public"."phone_numbers"."voicemail_greeting_url" IS 'URL to a custom voicemail greeting audio file for this specific number. Overrides the org-level voicemail_greeting_url when set.';



COMMENT ON CONSTRAINT "phone_numbers_spam_status_check" ON "public"."phone_numbers" IS 'Allowed spam_status labels (case/spacing-insensitive). Canonical form is snake_case.';



