CREATE POLICY "Admins can manage org default layouts" ON "public"."report_layouts" USING ((("organization_id" = "public"."get_org_id"()) AND ("user_id" IS NULL) AND (EXISTS ( SELECT 1
   FROM "public"."profiles"
  WHERE (("profiles"."id" = "auth"."uid"()) AND ("profiles"."role" = ANY (ARRAY['Admin'::"text", 'Team Leader'::"text"])))))));



CREATE POLICY "Admins can manage own organization agency resources" ON "public"."agency_resources" USING ((("organization_id" = ( SELECT "profiles"."organization_id"
   FROM "public"."profiles"
  WHERE ("profiles"."id" = "auth"."uid"()))) AND (EXISTS ( SELECT 1
   FROM "public"."profiles"
  WHERE (("profiles"."id" = "auth"."uid"()) AND ("lower"("profiles"."role") = ANY (ARRAY['admin'::"text", 'super admin'::"text"])))))));



CREATE POLICY "Admins can manage own organization categories" ON "public"."training_categories" USING ((("organization_id" = ( SELECT "profiles"."organization_id"
   FROM "public"."profiles"
  WHERE ("profiles"."id" = "auth"."uid"()))) AND (EXISTS ( SELECT 1
