-- ===== APPENDIX C: storage.objects policies (excluded from pg_dump) =====
DROP POLICY IF EXISTS "Admin Delete" ON storage.objects;
CREATE POLICY "Admin Delete" ON storage.objects FOR DELETE TO authenticated USING ((bucket_id = 'agency_materials'::text) AND (EXISTS ( SELECT 1 FROM public.profiles WHERE ((profiles.id = auth.uid()) AND (lower(profiles.role) = ANY (ARRAY['admin'::text, 'super admin'::text]))))));
DROP POLICY IF EXISTS "Admin Insert" ON storage.objects;
CREATE POLICY "Admin Insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK ((bucket_id = 'agency_materials'::text) AND (EXISTS ( SELECT 1 FROM public.profiles WHERE ((profiles.id = auth.uid()) AND (lower(profiles.role) = ANY (ARRAY['admin'::text, 'super admin'::text]))))));
DROP POLICY IF EXISTS "Admin Update" ON storage.objects;
CREATE POLICY "Admin Update" ON storage.objects FOR UPDATE TO authenticated USING ((bucket_id = 'agency_materials'::text) AND (EXISTS ( SELECT 1 FROM public.profiles WHERE ((profiles.id = auth.uid()) AND (lower(profiles.role) = ANY (ARRAY['admin'::text, 'super admin'::text]))))));
DROP POLICY IF EXISTS "Public Access" ON storage.objects;
CREATE POLICY "Public Access" ON storage.objects FOR SELECT USING (bucket_id = 'agency_materials'::text);
DROP POLICY IF EXISTS "agency_group_resources_storage_delete" ON storage.objects;
CREATE POLICY "agency_group_resources_storage_delete" ON storage.objects FOR DELETE TO authenticated USING ((bucket_id = 'agency-group-resources'::text) AND (public.is_super_admin() OR public.storage_agency_group_resource_member_ok(name)));
DROP POLICY IF EXISTS "agency_group_resources_storage_insert" ON storage.objects;
CREATE POLICY "agency_group_resources_storage_insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK ((bucket_id = 'agency-group-resources'::text) AND (public.is_super_admin() OR public.storage_agency_group_resource_member_ok(name)));
DROP POLICY IF EXISTS "agency_group_resources_storage_select" ON storage.objects;
CREATE POLICY "agency_group_resources_storage_select" ON storage.objects FOR SELECT TO authenticated USING ((bucket_id = 'agency-group-resources'::text) AND (public.is_super_admin() OR public.storage_agency_group_resource_member_ok(name)));
DROP POLICY IF EXISTS "agency_group_resources_storage_update" ON storage.objects;
CREATE POLICY "agency_group_resources_storage_update" ON storage.objects FOR UPDATE TO authenticated USING ((bucket_id = 'agency-group-resources'::text) AND (public.is_super_admin() OR public.storage_agency_group_resource_member_ok(name)));
DROP POLICY IF EXISTS "call_recordings_insert_own_org" ON storage.objects;
CREATE POLICY "call_recordings_insert_own_org" ON storage.objects FOR INSERT TO authenticated WITH CHECK ((bucket_id = 'call-recordings'::text) AND (split_part(name, '/'::text, 1) = (public.get_org_id())::text));
DROP POLICY IF EXISTS "call_recordings_select_own_org" ON storage.objects;
CREATE POLICY "call_recordings_select_own_org" ON storage.objects FOR SELECT TO authenticated USING ((bucket_id = 'call-recordings'::text) AND (split_part(name, '/'::text, 1) = (public.get_org_id())::text));
DROP POLICY IF EXISTS "call_recordings_update_own_org" ON storage.objects;
CREATE POLICY "call_recordings_update_own_org" ON storage.objects FOR UPDATE TO authenticated USING ((bucket_id = 'call-recordings'::text) AND (split_part(name, '/'::text, 1) = (public.get_org_id())::text)) WITH CHECK ((bucket_id = 'call-recordings'::text) AND (split_part(name, '/'::text, 1) = (public.get_org_id())::text));
DROP POLICY IF EXISTS "company_branding_delete" ON storage.objects;
CREATE POLICY "company_branding_delete" ON storage.objects FOR DELETE TO authenticated USING ((bucket_id = 'company-branding'::text) AND (split_part(name, '/'::text, 1) = (public.get_org_id())::text) AND ((public.get_user_role() = 'Admin'::text) OR public.is_super_admin()));
DROP POLICY IF EXISTS "company_branding_insert" ON storage.objects;
CREATE POLICY "company_branding_insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK ((bucket_id = 'company-branding'::text) AND (split_part(name, '/'::text, 1) = (public.get_org_id())::text) AND ((public.get_user_role() = 'Admin'::text) OR public.is_super_admin()));
DROP POLICY IF EXISTS "company_branding_update" ON storage.objects;
CREATE POLICY "company_branding_update" ON storage.objects FOR UPDATE TO authenticated USING ((bucket_id = 'company-branding'::text) AND (split_part(name, '/'::text, 1) = (public.get_org_id())::text) AND ((public.get_user_role() = 'Admin'::text) OR public.is_super_admin()));
DROP POLICY IF EXISTS "template_attachments_delete" ON storage.objects;
CREATE POLICY "template_attachments_delete" ON storage.objects FOR DELETE TO authenticated USING ((bucket_id = 'template-attachments'::text) AND (split_part(name, '/'::text, 1) = ( SELECT (profiles.organization_id)::text FROM public.profiles WHERE (profiles.id = auth.uid()) LIMIT 1)));
DROP POLICY IF EXISTS "template_attachments_insert" ON storage.objects;
CREATE POLICY "template_attachments_insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK ((bucket_id = 'template-attachments'::text) AND (split_part(name, '/'::text, 1) = ( SELECT (profiles.organization_id)::text FROM public.profiles WHERE (profiles.id = auth.uid()) LIMIT 1)));
DROP POLICY IF EXISTS "template_attachments_select" ON storage.objects;
CREATE POLICY "template_attachments_select" ON storage.objects FOR SELECT TO authenticated USING ((bucket_id = 'template-attachments'::text) AND (split_part(name, '/'::text, 1) = ( SELECT (profiles.organization_id)::text FROM public.profiles WHERE (profiles.id = auth.uid()) LIMIT 1)));
